{"-- Secure database access helpers for the AI assistant.
-- These helpers are intended to be called by the ai-assistant Edge Function
-- with SUPABASE_SERVICE_ROLE_KEY, not directly from the browser.

create or replace function public.ai_database_catalog()
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'table', table_name,
        'columns', columns
      )
      order by table_name
    ),
    '[]'::jsonb
  )
  from (
    select
      c.table_name,
      jsonb_agg(
        jsonb_build_object(
          'name', c.column_name,
          'type', c.data_type,
          'nullable', c.is_nullable = 'YES'
        )
        order by c.ordinal_position
      ) as columns
    from information_schema.columns c
    where c.table_schema = 'public'
      and c.table_name not like 'pg_%'
      and c.table_name not in ('app_code_counters')
    group by c.table_name
  ) s;
$$","create or replace function public.execute_ai_readonly_query(p_query text)
returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_sql text := trim(coalesce(p_query, ''));
  v_lower text;
  v_rows jsonb;
  v_row_count integer;
begin
  v_sql := regexp_replace(v_sql, ';\\s*$', '');
  v_lower := lower(v_sql);

  if v_sql = '' or v_lower !~ '^\\s*(select|with)\\s' then
    raise exception 'AI query must be SELECT-only';
  end if;

  if v_sql like '%;%' then
    raise exception 'AI query must contain a single statement';
  end if;

  if v_sql ~ '(--|/\\*)' then
    raise exception 'AI query comments are not allowed';
  end if;

  if v_lower ~ '(^|[^a-z_])(insert|update|delete|drop|alter|truncate|grant|revoke|create|replace|merge|call|copy|do|execute|notify|listen|vacuum|analyze|set|reset|refresh)([^a-z_]|$)' then
    raise exception 'AI query contains a blocked keyword';
  end if;

  if v_lower ~ '(^|[^a-z_])(auth|storage|vault|net|extensions|pg_catalog|information_schema)\\s*\\.' then
    raise exception 'AI query references a blocked schema';
  end if;

  perform set_config('statement_timeout', '5000', true);

  execute format(
    'select coalesce(jsonb_agg(to_jsonb(ai_limited)), ''[]''::jsonb)
       from (select * from (%s) ai_source limit 500) ai_limited',
    v_sql
  )
  into v_rows;

  v_row_count := coalesce(jsonb_array_length(v_rows), 0);
  return jsonb_build_object(
    'rows', v_rows,
    'rowCount', v_row_count,
    'limited', v_row_count >= 500
  );
end;
$$","create or replace function public.ai_search_knowledge(p_query text, p_limit integer default 8)
returns table (
  document_id text,
  title text,
  file_name text,
  content text,
  rank real
)
language plpgsql
stable
security invoker
set search_path = public
as $$
declare
  v_content_column text;
  v_limit integer := least(greatest(coalesce(p_limit, 8), 1), 20);
begin
  if to_regclass('public.rag_chunks') is null or to_regclass('public.rag_documents') is null then
    return;
  end if;

  select column_name
    into v_content_column
  from information_schema.columns
  where table_schema = 'public'
    and table_name = 'rag_chunks'
    and column_name in ('content', 'chunk_text', 'text')
  order by case column_name when 'content' then 1 when 'chunk_text' then 2 else 3 end
  limit 1;

  if v_content_column is null then
    return;
  end if;

  return query execute format(
    'select
       c.document_id::text,
       d.title::text,
       d.file_name::text,
       left(c.%1$I::text, 1800) as content,
       ts_rank_cd(to_tsvector(''simple'', coalesce(c.%1$I::text, '''')), plainto_tsquery(''simple'', $1))::real as rank
     from public.rag_chunks c
     join public.rag_documents d on d.id = c.document_id
     where coalesce(d.status, ''ready'') = ''ready''
       and to_tsvector(''simple'', coalesce(c.%1$I::text, '''')) @@ plainto_tsquery(''simple'', $1)
     order by rank desc
     limit $2',
    v_content_column
  )
  using p_query, v_limit;
end;
$$","revoke all on function public.ai_database_catalog() from public","revoke all on function public.execute_ai_readonly_query(text) from public","revoke all on function public.ai_search_knowledge(text, integer) from public","revoke execute on function public.ai_database_catalog() from anon, authenticated","revoke execute on function public.execute_ai_readonly_query(text) from anon, authenticated","revoke execute on function public.ai_search_knowledge(text, integer) from anon, authenticated","grant execute on function public.ai_database_catalog() to service_role","grant execute on function public.execute_ai_readonly_query(text) to service_role","grant execute on function public.ai_search_knowledge(text, integer) to service_role","notify pgrst, 'reload schema'"}

{"-- Keep the authenticated user's effective permission snapshot current when
-- Direct Grants are added, reactivated, expired, or revoked (soft update).

do $$
begin
  if not exists (
    select 1
    from pg_publication_tables
    where pubname = 'supabase_realtime'
      and schemaname = 'public'
      and tablename = 'user_permission_grants'
  ) then
    alter publication supabase_realtime add table public.user_permission_grants;
  end if;
end
$$"}

{"-- Room is the authoritative workflow gate for Project Material / PO actions.
-- The existing UI already filters recipients by Room; these checks make the
-- same rule effective for direct RPC/API calls as well.

create or replace function app_private.assert_project_permission_room_action(
  p_project_id text,
  p_construction_site_id text,
  p_room_code text,
  p_action_code text,
  p_user_id uuid default public.current_app_user_id()
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_user_id is null then
    raise exception 'Không xác định được người dùng đang thao tác.'
      using errcode = '42501';
  end if;

  if not app_private.project_user_has_room_action(
    p_user_id,
    p_project_id,
    p_construction_site_id,
    p_room_code,
    p_action_code
  ) then
    raise exception 'Bạn chưa có quyền % trong Room % của dự án này.', p_action_code, p_room_code
      using errcode = '42501';
  end if;
end;
$$","revoke all on function app_private.assert_project_permission_room_action(text, text, text, text, uuid) from public, anon, authenticated","create or replace function app_private.project_room_action_from_material_permission(
  p_permission_code text
)
returns text
language sql
immutable
security invoker
set search_path = ''
as $$
  select case
    when p_permission_code in ('project.material_request.submit', 'project.material_po.create') then 'submit'
    when p_permission_code in ('project.material_request.confirm_fulfillment', 'project.material_po.receive') then 'confirm'
    else 'approve'
  end;
$$","revoke all on function app_private.project_room_action_from_material_permission(text) from public, anon, authenticated","create or replace function public.transition_project_material_request_status(
  p_request_id text,
  p_status text,
  p_action text,
  p_actor_user_id text,
  p_target_user_id text default null,
  p_target_permission text default null,
  p_note text default null,
  p_patch jsonb default '{}'::jsonb
)
returns public.requests
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_request public.requests%rowtype;
  v_user_id uuid := public.current_app_user_id();
  v_required_permission text;
  v_room_action text;
  v_target_room_action text;
  v_previous_guard text;
begin
  if v_user_id is null or p_actor_user_id is distinct from v_user_id::text then
    raise exception 'Không xác định được người dùng chuyển bước phiếu vật tư.'
      using errcode = '42501';
  end if;

  select *
  into v_request
  from public.requests
  where id = p_request_id
    and coalesce(request_origin, 'wms') = 'project'
  for update;

  if not found then
    raise exception 'Không tìm thấy phiếu vật tư dự án.';
  end if;

  v_required_permission := case
    when upper(coalesce(p_action, '')) in ('SUBMITTED', 'RESUBMITTED') then 'project.material_request.submit'
    when upper(coalesce(p_action, '')) in ('RETURNED', 'REJECTED') then 'project.material_request.approve'
    when upper(coalesce(p_action, '')) in ('FULFILLED', 'CONFIRMED', 'CONFIRM_FULFILLMENT') then 'project.material_request.confirm_fulfillment'
    when coalesce(p_patch->>'workflow_step', '') in ('site_quality_check', 'completed')
      or upper(coalesce(p_status, '')) in ('COMPLETED', 'IN_TRANSIT') then 'project.material_request.confirm_fulfillment'
    else 'project.material_request.approve'
  end;
  v_room_action := app_private.project_room_action_from_material_permission(v_required_permission);

  if v_required_permission = 'project.material_request.submit' then
    if coalesce(v_request.status::text, 'DRAFT') not in ('DRAFT', 'REJECTED') then
      raise exception 'Chỉ phiếu nháp hoặc bị trả lại mới được gửi duyệt.';
    end if;
    if v_request.requester_id is distinct from v_user_id then
      raise exception 'Chỉ người tạo phiếu mới được gửi duyệt.'
        using errcode = '42501';
    end if;
  elsif v_request.submitted_to_user_id is not null
    and v_request.submitted_to_user_id <> v_user_id::text then
    raise exception 'Bạn không phải người đang được giao xử lý phiếu vật tư này.'
      using errcode = '42501';
  end if;

  perform app_private.assert_project_permission_room_action(
    v_request.project_id::text,
    v_request.construction_site_id::text,
    'material_request',
    v_room_action,
    v_user_id
  );

  if nullif(p_target_user_id, '') is not null then
    v_target_room_action := app_private.project_room_action_from_material_permission(p_target_permission);
    perform app_private.assert_project_permission_room_action(
      v_request.project_id::text,
      v_request.construction_site_id::text,
      'material_request',
      v_target_room_action,
      p_target_user_id::uuid
    );
  end if;

  v_previous_guard := current_setting('app.material_transition_context', true);
  perform set_config('app.material_transition_context', 'on', true);

  update public.requests
  set
    status = coalesce(nullif(p_status, '')::public.request_status, status),
    logs = case when p_patch ? 'logs' then p_patch->'logs' else logs end,
    ever_submitted = case when p_patch ? 'ever_submitted' then coalesce((p_patch->>'ever_submitted')::boolean, ever_submitted) else ever_submitted end,
    last_action_by = case when p_patch ? 'last_action_by' then nullif(p_patch->>'last_action_by', '') else last_action_by end,
    last_action_at = case when p_patch ? 'last_action_at' then nullif(p_patch->>'last_action_at', '')::timestamptz else last_action_at end,
    workflow_step = case when p_patch ? 'workflow_step' then nullif(p_patch->>'workflow_step', '') else workflow_step end,
    workflow_step_started_at = case when p_patch ? 'workflow_step_started_at' then nullif(p_patch->>'workflow_step_started_at', '')::timestamptz else workflow_step_started_at end,
    workflow_step_due_at = case when p_patch ? 'workflow_step_due_at' then nullif(p_patch->>'workflow_step_due_at', '')::timestamptz else workflow_step_due_at end,
    workflow_step_sla_hours = case when p_patch ? 'workflow_step_sla_hours' then nullif(p_patch->>'workflow_step_sla_hours', '')::integer else workflow_step_sla_hours end,
    workflow_step_actor_user_id = case when p_patch ? 'workflow_step_actor_user_id' then nullif(p_patch->>'workflow_step_actor_user_id', '') else workflow_step_actor_user_id end,
    submitted_to_user_id = case when p_patch ? 'submitted_to_user_id' then nullif(p_patch->>'submitted_to_user_id', '') else submitted_to_user_id end,
    submitted_to_name = case when p_patch ? 'submitted_to_name' then nullif(p_patch->>'submitted_to_name', '') else submitted_to_name end,
    submitted_to_permission = case when p_patch ? 'submitted_to_permission' then nullif(p_patch->>'submitted_to_permission', '') else submitted_to_permission end,
    submission_note = case when p_patch ? 'submission_note' then nullif(p_patch->>'submission_note', '') else submission_note end
  where id = p_request_id
  returning * into v_request;

  perform set_config('app.material_transition_context', coalesce(v_previous_guard, ''), true);
  return v_request;
exception
  when others then
    perform set_config('app.material_transition_context', coalesce(v_previous_guard, ''), true);
    raise;
end;
$$","revoke all on function public.transition_project_material_request_status(text, text, text, text, text, text, text, jsonb) from public, anon","grant execute on function public.transition_project_material_request_status(text, text, text, text, text, text, text, jsonb) to authenticated","create or replace function public.transition_project_purchase_order_status(
  p_po_id text,
  p_status text,
  p_patch jsonb default '{}'::jsonb
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_po public.purchase_orders%rowtype;
  v_user_id uuid := public.current_app_user_id();
  v_required_permission text;
  v_room_action text;
  v_previous_guard text;
begin
  if v_user_id is null then
    raise exception 'Không xác định được người dùng chuyển trạng thái PO.'
      using errcode = '42501';
  end if;

  select * into v_po from public.purchase_orders where id = p_po_id for update;
  if not found then
    raise exception 'Không tìm thấy PO.';
  end if;

  v_required_permission := case
    when coalesce(p_status, '') in ('in_transit', 'partial', 'delivered', 'closed')
      or p_patch ? 'received_transaction_ids'
      or p_patch ? 'actual_delivery_date' then 'project.material_po.receive'
    when coalesce(p_status, '') in ('sent', 'confirmed', 'returned', 'cancelled') then 'project.material_po.approve'
    else 'project.material_po.create'
  end;

  -- Company procurement and warehouse receiving keep their existing specialized
  -- controls. Project PO submission/approval is now exclusively Room-based.
  if coalesce(v_po.source_mode, 'project') <> 'company_consolidated'
    and coalesce(p_status, '') in ('sent', 'confirmed', 'returned', 'cancelled') then
    v_room_action := case when p_status = 'sent' then 'submit' else 'approve' end;
    perform app_private.assert_project_permission_room_action(
      v_po.project_id::text,
      v_po.construction_site_id::text,
      'material_po',
      v_room_action,
      v_user_id
    );

    if p_status = 'sent' and nullif(p_patch->>'submitted_to_user_id', '') is not null then
      perform app_private.assert_project_permission_room_action(
        v_po.project_id::text,
        v_po.construction_site_id::text,
        'material_po',
        'approve',
        (p_patch->>'submitted_to_user_id')::uuid
      );
    end if;
  elsif not (
    public.is_admin()
    or public.is_module_admin('DA')
    or (v_po.source_mode = 'company_consolidated' and app_private.company_procurement_can_manage())
    or (
      v_required_permission = 'project.material_po.receive'
      and (app_private.current_user_is_global_wms_keeper() or app_private.current_user_is_wms_keeper_for(v_po.target_warehouse_id))
    )
    or app_private.material_has_action(v_po.project_id, v_po.construction_site_id, v_required_permission, v_user_id)
  ) then
    raise exception 'Bạn cần quyền % để chuyển trạng thái PO.', v_required_permission
      using errcode = '42501';
  end if;

  v_previous_guard := current_setting('app.material_transition_context', true);
  perform set_config('app.material_transition_context', 'on', true);

  update public.purchase_orders
  set
    status = coalesce(nullif(p_status, ''), status),
    submitted_to_user_id = case when p_patch ? 'submitted_to_user_id' then nullif(p_patch->>'submitted_to_user_id', '') else submitted_to_user_id end,
    submitted_to_name = case when p_patch ? 'submitted_to_name' then nullif(p_patch->>'submitted_to_name', '') else submitted_to_name end,
    submitted_to_permission = case when p_patch ? 'submitted_to_permission' then nullif(p_patch->>'submitted_to_permission', '') else submitted_to_permission end,
    submission_note = case when p_patch ? 'submission_note' then nullif(p_patch->>'submission_note', '') else submission_note end,
    ever_submitted = case when p_patch ? 'ever_submitted' then coalesce((p_patch->>'ever_submitted')::boolean, ever_submitted) else ever_submitted end,
    last_action_by = case when p_patch ? 'last_action_by' then nullif(p_patch->>'last_action_by', '') else last_action_by end,
    last_action_at = case when p_patch ? 'last_action_at' then nullif(p_patch->>'last_action_at', '')::timestamptz else last_action_at end,
    received_transaction_ids = case when p_patch ? 'received_transaction_ids' then coalesce(p_patch->'received_transaction_ids', '[]'::jsonb) else received_transaction_ids end,
    actual_delivery_date = case when p_patch ? 'actual_delivery_date' then nullif(p_patch->>'actual_delivery_date', '') else actual_delivery_date end
  where id = p_po_id;

  perform set_config('app.material_transition_context', coalesce(v_previous_guard, ''), true);
exception
  when others then
    perform set_config('app.material_transition_context', coalesce(v_previous_guard, ''), true);
    raise;
end;
$$","revoke all on function public.transition_project_purchase_order_status(text, text, jsonb) from public, anon","grant execute on function public.transition_project_purchase_order_status(text, text, jsonb) to authenticated","notify pgrst, 'reload schema'"}

{"-- Existing document services write their workflow status directly. These
-- BEFORE UPDATE triggers make Room membership an additional server-side gate,
-- including calls that bypass the React recipient picker.

create or replace function app_private.enforce_daily_log_room_status()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_action text;
  v_target_action text;
begin
  if new.status is not distinct from old.status
    and new.submitted_to_user_id is not distinct from old.submitted_to_user_id
    and new.submitted_to_permission is not distinct from old.submitted_to_permission then
    return new;
  end if;

  if new.status is not distinct from old.status and new.status = 'submitted' then
    v_action := 'submit';
    v_target_action := case when new.submitted_to_permission = 'approve' then 'approve' else 'verify' end;
  elsif new.status = 'submitted' then
    v_action := 'submit';
    v_target_action := case when new.submitted_to_permission = 'approve' then 'approve' else 'verify' end;
  elsif new.status = 'verified' then
    v_action := case when old.submitted_to_permission = 'approve' then 'approve' else 'verify' end;
  elsif new.status = 'rejected' then
    v_action := case when old.submitted_to_permission = 'approve' then 'approve' else 'verify' end;
  else
    return new;
  end if;

  perform app_private.assert_project_permission_room_action(
    new.project_id::text, new.construction_site_id::text, 'daily_log', v_action
  );

  if new.status = 'submitted' and nullif(new.submitted_to_user_id, '') is not null then
    perform app_private.assert_project_permission_room_action(
      new.project_id::text, new.construction_site_id::text, 'daily_log', v_target_action,
      new.submitted_to_user_id::uuid
    );
  end if;
  return new;
end;
$$","create or replace function app_private.enforce_quality_checklist_room_status()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_action text;
begin
  if new.status is not distinct from old.status then return new; end if;
  v_action := case
    when new.status = 'submitted' then 'submit'
    when new.status in ('approved', 'returned', 'cancelled') then 'approve'
    else null
  end;
  if v_action is null then return new; end if;
  perform app_private.assert_project_permission_room_action(
    new.project_id::text, new.construction_site_id::text, 'quality', v_action
  );
  if new.status = 'submitted' then
    if nullif(new.submitted_to_user_id, '') is null then
      raise exception 'Vui lòng chọn người duyệt hồ sơ chất lượng trong Room.' using errcode = '42501';
    end if;
    perform app_private.assert_project_permission_room_action(
      new.project_id::text, new.construction_site_id::text, 'quality', 'approve', new.submitted_to_user_id::uuid
    );
  end if;
  return new;
end;
