on storage.objects for delete
to authenticated
using (
  bucket_id = 'wms-transaction-attachments'
  and split_part(name, '/', 1) <> ''
  and app_private.wms_transaction_attachment_can_access(name)
)","create or replace function public.update_transaction_items_for_receipt(
  p_transaction_id text,
  p_items jsonb
)
returns public.transactions
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tx public.transactions%rowtype;
  v_user public.users%rowtype;
  v_item_count integer;
  v_idx integer;
  v_old_item jsonb;
  v_new_item jsonb;
  v_old_qty numeric;
  v_new_qty numeric;
  v_ordered_qty numeric;
  v_is_fulfillment_transfer boolean := false;
  v_can_adjust boolean := false;
begin
  select * into v_tx
  from public.transactions
  where id = p_transaction_id
  for update;
  if not found then
    raise exception 'transaction not found: %', p_transaction_id;
  end if;

  select * into v_user from public.users where id = public.current_app_user_id();
  if v_user.id is null then
    raise exception 'authentication required';
  end if;

  if v_tx.status not in ('PENDING'::public.transaction_status, 'APPROVED'::public.transaction_status) then
    raise exception 'Chỉ được điều chỉnh số lượng ở bước chờ duyệt hoặc chờ xác nhận nhập.';
  end if;

  if jsonb_typeof(p_items) <> 'array' then
    raise exception 'invalid transaction items payload';
  end if;

  v_item_count := jsonb_array_length(coalesce(v_tx.items, '[]'::jsonb));
  if v_item_count = 0 then
    raise exception 'Phiếu kho không có dòng vật tư để điều chỉnh.';
  end if;
  if jsonb_array_length(p_items) <> v_item_count then
    raise exception 'Không được thêm/xóa dòng vật tư khi duyệt phiếu kho.';
  end if;

  select exists (
    select 1
    from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb)) line(value)
    where nullif(line.value->>'fulfillmentBatchId', '') is not null
  )
  into v_is_fulfillment_transfer;

  v_is_fulfillment_transfer := v_is_fulfillment_transfer
    and v_tx.type = 'TRANSFER'::public.transaction_type
    and nullif(v_tx.target_warehouse_id, '') is not null;

  v_can_adjust :=
    public.is_module_admin('WMS')
    or (
      v_user.role = 'WAREHOUSE_KEEPER'
      and (
        v_user.assigned_warehouse_id is null
        or (v_tx.type = 'IMPORT'::public.transaction_type and v_user.assigned_warehouse_id is not distinct from v_tx.target_warehouse_id)
        or (v_is_fulfillment_transfer and v_user.assigned_warehouse_id is not distinct from v_tx.target_warehouse_id)
        or (
          v_tx.status = 'APPROVED'::public.transaction_status
          and v_tx.type = 'TRANSFER'::public.transaction_type
          and v_user.assigned_warehouse_id is not distinct from v_tx.target_warehouse_id
        )
      )
    );

  if not v_can_adjust then
    raise exception 'insufficient privilege to adjust transaction quantities';
  end if;

  for v_idx in 0..(v_item_count - 1) loop
    v_old_item := v_tx.items -> v_idx;
    v_new_item := p_items -> v_idx;

    if v_old_item is null or v_new_item is null then
      raise exception 'invalid transaction items payload';
    end if;

    if coalesce(v_old_item->>'itemId', '') is distinct from coalesce(v_new_item->>'itemId', '')
       or coalesce(v_old_item->>'requestLineId', '') is distinct from coalesce(v_new_item->>'requestLineId', '')
       or coalesce(v_old_item->>'fulfillmentBatchId', '') is distinct from coalesce(v_new_item->>'fulfillmentBatchId', '') then
      raise exception 'Không được đổi vật tư/dòng đề xuất khi duyệt phiếu kho.';
    end if;

    v_old_qty := coalesce(nullif(v_old_item->>'quantity', '')::numeric, 0);
    v_new_qty := coalesce(nullif(v_new_item->>'quantity', '')::numeric, 0);
    v_ordered_qty := coalesce(
      nullif(v_new_item->>'orderedQty', '')::numeric,
      nullif(v_new_item->>'ordered_qty', '')::numeric,
      v_old_qty
    );

    if v_new_qty < 0 then
      raise exception 'Số lượng thực nhận không được âm.';
    end if;
    if v_ordered_qty < 0 then
      raise exception 'Số lượng đặt không được âm.';
    end if;
    if v_new_qty is distinct from v_ordered_qty
       and nullif(trim(coalesce(v_new_item->>'varianceReason', '')), '') is null
       and nullif(trim(coalesce(v_new_item->>'variance_reason', '')), '') is null then
      raise exception 'Phải nhập lý do khi số lượng thực nhận lệch số lượng trên phiếu.';
    end if;
  end loop;

  update public.transactions
  set items = p_items
  where id = p_transaction_id
  returning * into v_tx;

  return v_tx;
end;
$$","revoke all on function public.update_transaction_items_for_receipt(text, jsonb) from public, anon","grant execute on function public.update_transaction_items_for_receipt(text, jsonb) to authenticated","notify pgrst, 'reload schema'","-- Re-define the completion sync so PO received quantities are never capped by
-- the ordered baseline. The PO qty remains the audit baseline; receivedQty is
-- the actual approved quantity.
create or replace function public.sync_fulfillment_receipt_for_transaction(
  p_transaction_id text,
  p_actor_user_id uuid default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, app_private
as $$
declare
  v_tx public.transactions%rowtype;
  v_user public.users%rowtype;
  v_batch public.material_request_fulfillment_batches%rowtype;
  v_actor_user_id uuid;
  v_can_sync boolean := false;
  v_line record;
  v_received_qty numeric;
  v_reason text;
  v_has_variance boolean := false;
  v_po_id text;
  v_po public.purchase_orders%rowtype;
  v_next_items jsonb;
  v_is_delivered boolean;
  v_already_recorded boolean;
begin
  select * into v_tx
  from public.transactions
  where id = p_transaction_id
  for update;
  if not found then
    raise exception 'transaction not found: %', p_transaction_id;
  end if;

  select * into v_user
  from public.users
  where id = public.current_app_user_id();
  if v_user.id is null then
    raise exception 'authentication required';
  end if;

  v_actor_user_id := coalesce(p_actor_user_id, v_user.id);

  v_can_sync :=
    public.is_admin()
    or public.is_module_admin('WMS')
    or (
      v_user.role = 'WAREHOUSE_KEEPER'
      and (
        v_user.assigned_warehouse_id is null
        or (
          v_tx.type in ('IMPORT'::public.transaction_type, 'TRANSFER'::public.transaction_type)
          and v_user.assigned_warehouse_id is not distinct from v_tx.target_warehouse_id
        )
      )
    );

  if not v_can_sync then
    raise exception 'insufficient privilege to sync fulfillment receipt';
  end if;

  if v_tx.status <> 'COMPLETED'::public.transaction_status then
    raise exception 'Chỉ đồng bộ nhận hàng cho phiếu kho đã hoàn tất.';
  end if;

  select * into v_batch
  from public.material_request_fulfillment_batches
  where transaction_id = p_transaction_id
  for update;
  if not found then
    return jsonb_build_object('synced', false, 'reason', 'batch_not_found');
  end if;

  if v_batch.status not in ('issued', 'received') then
    return jsonb_build_object('synced', false, 'reason', 'batch_not_receivable', 'batchStatus', v_batch.status);
  end if;

  for v_line in
    select *
    from public.material_request_fulfillment_lines
    where batch_id = v_batch.id
    order by created_at asc
    for update
  loop
    select
      coalesce(sum(coalesce(nullif(item.value->>'quantity', '')::numeric, 0)), 0),
      max(nullif(item.value->>'varianceReason', ''))
    into v_received_qty, v_reason
    from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb)) item(value)
    where coalesce(item.value->>'fulfillmentBatchId', '') = v_batch.id::text
      and item.value->>'requestLineId' = v_line.request_line_id;

    if coalesce(v_received_qty, 0) = 0 then
      select
        coalesce(sum(coalesce(nullif(item.value->>'quantity', '')::numeric, 0)), 0),
        max(nullif(item.value->>'varianceReason', ''))
      into v_received_qty, v_reason
      from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb)) item(value)
      where coalesce(item.value->>'fulfillmentBatchId', '') = v_batch.id::text
        and item.value->>'itemId' = v_line.item_id;
    end if;

    if coalesce(v_received_qty, 0) <> coalesce(v_line.issued_qty, 0) then
      v_has_variance := true;
    end if;

    update public.material_request_fulfillment_lines
    set
      received_qty = coalesce(v_received_qty, 0),
      variance_reason = coalesce(
        nullif(v_reason, ''),
        variance_reason,
        case
          when coalesce(v_received_qty, 0) <> coalesce(v_line.issued_qty, 0)
            then 'Thủ kho công trường xác nhận số lượng thực nhận lệch phiếu kho.'
          else null
        end
      )
    where id = v_line.id;
  end loop;

  if v_batch.status = 'issued' then
    update public.material_request_fulfillment_batches
    set
      status = 'received',
      received_by = v_actor_user_id,
      received_at = now(),
      reason = coalesce(
        reason,
        case when v_has_variance then 'Thủ kho công trường xác nhận nhận lệch theo thực tế.' else null end
      )
    where id = v_batch.id
    returning * into v_batch;
  end if;

  for v_po_id in
    select distinct po_id
    from public.material_request_fulfillment_lines
    where batch_id = v_batch.id
      and po_id is not null
  loop
    select * into v_po
    from public.purchase_orders
    where id = v_po_id
    for update;
    if not found then continue; end if;

    select exists (
      select 1
      from jsonb_array_elements_text(coalesce(v_po.received_transaction_ids, '[]'::jsonb)) existing(id)
      where existing.id = v_tx.id
    ) into v_already_recorded;
    if v_already_recorded then continue; end if;

    with receipt_by_line as (
      select po_line_id, sum(coalesce(received_qty, 0)) as received_qty
      from public.material_request_fulfillment_lines
      where batch_id = v_batch.id
        and po_id = v_po_id
        and po_line_id is not null
      group by po_line_id
    ),
    item_rows as (
      select
        item.value as item,
        item.ordinality,
        coalesce(item.value->>'lineId', item.value->>'line_id', item.value->>'itemId', item.value->>'item_id') as line_key,
        coalesce(nullif(item.value->>'qty', '')::numeric, 0) as ordered_qty,
        coalesce(nullif(item.value->>'receivedQty', '')::numeric, 0) as current_received_qty
      from jsonb_array_elements(coalesce(v_po.items, '[]'::jsonb)) with ordinality item(value, ordinality)
    ),
    next_rows as (
      select
        case
          when coalesce(r.received_qty, 0) > 0 then
            jsonb_set(
              ir.item,
              '{receivedQty}',
              to_jsonb(ir.current_received_qty + coalesce(r.received_qty, 0)),
              true
            )
          else ir.item
        end as item,
        ir.ordinality
      from item_rows ir
      left join receipt_by_line r on r.po_line_id = ir.line_key
    )
    select coalesce(jsonb_agg(item order by ordinality), '[]'::jsonb)
    into v_next_items
    from next_rows;

    select coalesce(bool_and(
      coalesce(nullif(item.value->>'qty', '')::numeric, 0) <= coalesce(nullif(item.value->>'receivedQty', '')::numeric, 0)
    ), false)
    into v_is_delivered
    from jsonb_array_elements(coalesce(v_next_items, '[]'::jsonb)) item(value);

    update public.purchase_orders
    set
      items = v_next_items,
      status = case when v_is_delivered then 'delivered' else 'partial' end,
      actual_delivery_date = case when v_is_delivered then current_date::text else actual_delivery_date end,
      received_transaction_ids = coalesce(received_transaction_ids, '[]'::jsonb) || jsonb_build_array(v_tx.id)
    where id = v_po_id;
  end loop;

  perform app_private.sync_po_delivery_schedule_status_v1(v_batch.po_delivery_batch_id, v_batch.po_delivery_group_id);
  perform app_private.sync_material_request_receipt_status_v1(
    v_batch.material_request_id,
    v_actor_user_id,
    'Đồng bộ sau khi phiếu kho hoàn tất'
  );

  return jsonb_build_object(
    'synced', true,
    'batchId', v_batch.id,
    'batchStatus', v_batch.status,
    'hasVariance', v_has_variance
  );
end;
$$","revoke all on function public.sync_fulfillment_receipt_for_transaction(text, uuid) from public, anon","grant execute on function public.sync_fulfillment_receipt_for_transaction(text, uuid) to authenticated","notify pgrst, 'reload schema'"}

{"alter table public.contract_cost_items
  add column if not exists category text;

comment on column public.contract_cost_items.category is 'Explicit cost category mapping (materials, labor, machinery, subcontract, overhead, other)';"}

{"-- Mua nóng/CCDC: one guarded lifecycle from draft to supplier payable/payment.

create or replace function app_private.guard_site_direct_purchase_lifecycle()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_payable_status text;
begin
  if tg_op = 'INSERT' then
    if new.status <> 'draft' then
      raise exception 'Phiếu mua nóng mới phải được tạo ở trạng thái Nháp.';
    end if;
    return new;
  end if;

  if new.status = old.status then
    if old.status <> 'draft'
      and (to_jsonb(new) - array['updated_at', 'wms_transaction_id', 'last_action_by', 'last_action_at'])
        <> (to_jsonb(old) - array['updated_at', 'wms_transaction_id', 'last_action_by', 'last_action_at']) then
      raise exception 'Chỉ sửa được phiếu mua nóng ở trạng thái Nháp.';
    end if;
    return new;
  end if;

  if not (
    (old.status = 'draft' and new.status = 'submitted')
    or (old.status = 'submitted' and new.status in ('draft', 'approved_to_buy', 'rejected'))
    or (old.status = 'approved_to_buy' and new.status in ('submitted', 'purchased', 'rejected'))
    or (old.status in ('purchased', 'received', 'finance_review') and new.status in ('finance_review', 'reconciled', 'rejected'))
    or (old.status = 'reconciled' and new.status in ('finance_review', 'rejected', 'closed'))
    or (old.status = 'closed' and new.status = 'reconciled')
  ) then
    raise exception 'Chuyển trạng thái mua nóng không hợp lệ: % -> %.', old.status, new.status;
  end if;

  if new.status = 'reconciled' then
    select status into v_payable_status
    from public.supplier_payable_documents
    where source_type = 'site_direct_purchase'
      and source_id = new.id::text;

    if v_payable_status not in ('open', 'payable', 'partial') then
      raise exception 'Chỉ xác nhận công nợ khi phiếu có công nợ nhà cung cấp đang mở.';
    end if;
  end if;

  if new.status = 'closed' then
    select status into v_payable_status
    from public.supplier_payable_documents
    where source_type = 'site_direct_purchase'
      and source_id = new.id::text;

    if v_payable_status <> 'paid' then
      raise exception 'Chỉ đóng phiếu khi công nợ nhà cung cấp đã thanh toán đủ.';
    end if;
  end if;

  if new.status = 'rejected' then
    if exists (
      select 1
      from public.supplier_payable_documents payable
      where payable.source_type = 'site_direct_purchase'
        and payable.source_id = new.id::text
        and payable.status not in ('cancelled', 'reversed')
    ) then
      raise exception 'Phải hủy công nợ nhà cung cấp trước khi từ chối phiếu.';
    end if;
  end if;

  return new;
end;
$$","drop trigger if exists trg_guard_site_direct_purchase_lifecycle on public.site_direct_purchases","create trigger trg_guard_site_direct_purchase_lifecycle
before insert or update on public.site_direct_purchases
for each row execute function app_private.guard_site_direct_purchase_lifecycle()","create or replace function public.sync_supplier_payable_from_site_direct_purchase(p_direct_purchase_id uuid)
returns public.supplier_payable_documents
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_purchase public.site_direct_purchases%rowtype;
  v_recognized numeric(18,2);
  v_document public.supplier_payable_documents%rowtype;
  v_recording boolean := coalesce(current_setting('app.direct_purchase_recording', true), '') = 'on';
begin
  select * into v_purchase
  from public.site_direct_purchases
  where id = p_direct_purchase_id;

  if not found then
    raise exception 'Không tìm thấy phiếu mua nóng %. ', p_direct_purchase_id;
  end if;

  if not app_private.ap_scope_can_mutate(v_purchase.project_id, v_purchase.construction_site_id) then
    raise exception 'Bạn không có quyền đồng bộ công nợ phiếu mua nóng này.';
  end if;

  if not v_recording and v_purchase.status not in ('purchased', 'received', 'finance_review', 'reconciled') then
    raise exception 'Phiếu mua nóng chưa ở bước xác nhận công nợ.';
  end if;

  if exists (
    select 1
    from public.site_direct_purchase_lines line
    where line.direct_purchase_id = v_purchase.id
      and line.line_type = 'stock_item'
      and line.status <> 'rejected'
  )
  and not exists (
    select 1
    from public.transactions tx
    where tx.id = v_purchase.wms_transaction_id
      and upper(coalesce(tx.status::text, '')) = 'COMPLETED'
  )
  then
    raise exception 'Mua nóng vật tư tồn kho phải hoàn tất WMS import trước khi xác nhận công nợ.';
  end if;

  select coalesce(sum(
    case
      when line.status in ('accepted', 'adjusted') then coalesce(nullif(line.accepted_amount, 0), line.line_amount + line.vat_amount)
      else 0
    end
  ), 0)::numeric(18,2)
  into v_recognized
  from public.site_direct_purchase_lines line
  where line.direct_purchase_id = v_purchase.id;

  if v_recognized <= 0 then
    raise exception 'Phiếu mua nóng chưa có giá trị được chấp nhận để xác nhận công nợ.';
  end if;

  select * into v_document
  from public.supplier_payable_documents
  where source_type = 'site_direct_purchase'
    and source_id = v_purchase.id::text
  for update;

  if found and v_document.status in ('cancelled', 'reversed') and not v_recording then
    raise exception 'Công nợ của phiếu đã bị hủy. Hãy dùng thao tác Xác nhận công nợ nhà cung cấp để ghi nhận lại.';
  end if;

  insert into public.supplier_payable_documents (
    code, source_type, source_id, project_id, construction_site_id,
    supplier_id, supplier_name_snapshot, document_no, document_date, due_date,
    committed_amount, recognized_amount, credit_amount, status, qr_token,
    invoice_number, invoice_date, metadata, created_by
  )
  values (
    'AP-' || v_purchase.code,
    'site_direct_purchase',
    v_purchase.id::text,
    v_purchase.project_id,
    v_purchase.construction_site_id,
    v_purchase.supplier_id,
    v_purchase.supplier_name_snapshot,
    v_purchase.code,
    coalesce(v_purchase.purchase_date, current_date),
    null,
    v_purchase.total_amount,
    v_recognized,
    0,
    'open',
    coalesce(v_purchase.qr_token, 'ap_direct_' || replace(v_purchase.id::text, '-', '')),
    v_purchase.invoice_number,
    v_purchase.invoice_date,
    jsonb_build_object(
      'purchaseMode', v_purchase.purchase_mode,
      'paymentSource', v_purchase.payment_source,
      'wmsTransactionId', v_purchase.wms_transaction_id
    ),
    v_purchase.created_by
  )
  on conflict (source_type, source_id) do update
  set
    project_id = excluded.project_id,
    construction_site_id = excluded.construction_site_id,
    supplier_id = excluded.supplier_id,
    supplier_name_snapshot = excluded.supplier_name_snapshot,
    document_no = excluded.document_no,
    document_date = excluded.document_date,
    committed_amount = excluded.committed_amount,
    recognized_amount = excluded.recognized_amount,
    credit_amount = excluded.credit_amount,
    status = case
      when v_recording then 'open'
      else public.supplier_payable_documents.status
    end,
    invoice_number = excluded.invoice_number,
    invoice_date = excluded.invoice_date,
    metadata = public.supplier_payable_documents.metadata || excluded.metadata,
    updated_at = now()
  returning * into v_document;

  return v_document;
end;
$$","create or replace function app_private.cancel_site_direct_purchase_payable_v1(
  p_direct_purchase_id uuid,
  p_reason text,
  p_next_status text
)
returns public.site_direct_purchases
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_purchase public.site_direct_purchases%rowtype;
  v_actor_id uuid := auth.uid();
begin
  select * into v_purchase
  from public.site_direct_purchases
  where id = p_direct_purchase_id
  for update;

  if not found then
    raise exception 'Không tìm thấy phiếu mua nóng %. ', p_direct_purchase_id;
  end if;

  if not app_private.ap_scope_can_mutate(v_purchase.project_id, v_purchase.construction_site_id)
    or not app_private.material_flow_has_action_or_legacy(v_purchase.project_id, v_purchase.construction_site_id, 'project.material_direct_purchase.record_ap') then
    raise exception 'Bạn không có quyền hủy xác nhận công nợ phiếu mua nóng này.';
  end if;

  if v_purchase.status not in ('submitted', 'approved_to_buy', 'purchased', 'received', 'finance_review', 'reconciled') then
    raise exception 'Phiếu ở trạng thái % không thể từ chối hoặc bỏ xác nhận công nợ.', v_purchase.status;
  end if;

  if exists (
    select 1
    from public.supplier_payment_allocations allocation
    join public.supplier_payment_batches batch on batch.id = allocation.payment_batch_id
    join public.supplier_payable_documents payable on payable.id = allocation.payable_document_id
    where payable.source_type = 'site_direct_purchase'
      and payable.source_id = v_purchase.id::text
      and batch.status = 'paid'
  ) then
    raise exception 'Phiếu đã có thanh toán. Hãy Đảo thanh toán trước khi từ chối hoặc bỏ xác nhận công nợ.';
  end if;

  if v_purchase.site_cash_settlement_id is not null then
    raise exception 'Phiếu đã nằm trong quyết toán quỹ. Hãy đảo/quy hồi quyết toán trước.';
  end if;

  if v_purchase.wms_transaction_id is not null then
    raise exception 'Phiếu đã phát sinh WMS. Hãy hủy hoặc đảo phiếu kho trước.';
  end if;

  if exists (
    select 1
    from public.site_small_tool_records tool
    where tool.source_type = 'site_direct_purchase'
      and tool.source_id = v_purchase.id::text
      and tool.status <> 'stored'
  ) then
    raise exception 'CCDC đã được bàn giao hoặc sử dụng. Hãy thực hiện nghiệp vụ đảo CCDC trước.';
  end if;

  delete from public.site_small_tool_records tool
  where tool.source_type = 'site_direct_purchase'
    and tool.source_id = v_purchase.id::text
    and tool.status = 'stored';

  update public.supplier_payable_documents payable
  set
    status = 'cancelled',
    recognized_amount = 0,
    metadata = coalesce(payable.metadata, '{}'::jsonb) || jsonb_build_object(
      'cancelledAt', now(),
      'cancelledBy', v_actor_id,
      'cancellationReason', nullif(btrim(p_reason), '')
    ),
    updated_at = now()
  where payable.source_type = 'site_direct_purchase'
    and payable.source_id = v_purchase.id::text
    and payable.status not in ('cancelled', 'reversed');

  update public.site_direct_purchases purchase
  set
    status = p_next_status,
    note = concat_ws(E'\\n', nullif(purchase.note, ''), case when nullif(btrim(p_reason), '') is null then null else 'Lý do: ' || btrim(p_reason) end),
    last_action_by = v_actor_id,
    last_action_at = now(),
    updated_at = now()
  where purchase.id = v_purchase.id
  returning * into v_purchase;

  return v_purchase;
end;
$$","create or replace function public.record_site_direct_purchase_payable_v1(p_direct_purchase_id uuid)
returns public.supplier_payable_documents
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_purchase public.site_direct_purchases%rowtype;
  v_document public.supplier_payable_documents%rowtype;
begin
  select * into v_purchase
  from public.site_direct_purchases
  where id = p_direct_purchase_id
  for update;

  if not found then
    raise exception 'Không tìm thấy phiếu mua nóng %. ', p_direct_purchase_id;
  end if;

  if not app_private.ap_scope_can_mutate(v_purchase.project_id, v_purchase.construction_site_id)
    or not app_private.material_flow_has_action_or_legacy(v_purchase.project_id, v_purchase.construction_site_id, 'project.material_direct_purchase.record_ap') then
    raise exception 'Bạn không có quyền xác nhận công nợ phiếu mua nóng này.';
  end if;

  if v_purchase.status not in ('purchased', 'received', 'finance_review') then
    raise exception 'Chỉ xác nhận công nợ sau khi phiếu đã mua và sẵn sàng đối chiếu.';
  end if;

  if exists (
    select 1 from public.site_direct_purchase_lines line
    where line.direct_purchase_id = v_purchase.id
      and line.status in ('accepted', 'adjusted')
  ) is not true then
    raise exception 'Phiếu chưa có dòng hàng hợp lệ để xác nhận công nợ.';
  end if;

  perform set_config('app.direct_purchase_recording', 'on', true);

  if exists (
    select 1 from public.site_direct_purchase_lines line
    where line.direct_purchase_id = v_purchase.id
      and line.line_type = 'small_tool'
      and line.status in ('accepted', 'adjusted')
  ) then
    perform public.sync_site_small_tools_from_site_direct_purchase(v_purchase.id);
  end if;

  select * into v_document
  from public.sync_supplier_payable_from_site_direct_purchase(v_purchase.id);

  update public.site_direct_purchases purchase
  set
    status = 'reconciled',
    last_action_by = auth.uid(),
    last_action_at = now(),
    updated_at = now()
  where purchase.id = v_purchase.id;

  return v_document;
end;
$$","create or replace function public.unrecord_site_direct_purchase_payable_v1(
  p_direct_purchase_id uuid,
  p_reason text default null
)
returns public.site_direct_purchases
language sql
security invoker
set search_path = ''
as $$
  select app_private.cancel_site_direct_purchase_payable_v1(
    p_direct_purchase_id,
    coalesce(nullif(btrim(p_reason), ''), 'Bỏ xác nhận công nợ'),
    'finance_review'
  );
$$","create or replace function public.reject_site_direct_purchase_v1(
  p_direct_purchase_id uuid,
  p_reason text default null
)
returns public.site_direct_purchases
language sql
security invoker
set search_path = ''
as $$
  select app_private.cancel_site_direct_purchase_payable_v1(
    p_direct_purchase_id,
    coalesce(nullif(btrim(p_reason), ''), 'Từ chối phiếu'),
    'rejected'
  );
$$","create or replace function public.transition_site_direct_purchase_v1(
  p_direct_purchase_id uuid,
  p_action text,
  p_reason text default null,
  p_target_user_id uuid default null,
  p_target_name text default null,
  p_target_permission text default null
)
returns public.site_direct_purchases
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_purchase public.site_direct_purchases%rowtype;
  v_target_status text;
begin
  select * into v_purchase
  from public.site_direct_purchases
  where id = p_direct_purchase_id
  for update;

  if not found then
    raise exception 'Không tìm thấy phiếu mua nóng %. ', p_direct_purchase_id;
  end if;

  if not app_private.material_flow_has_action_or_legacy(v_purchase.project_id, v_purchase.construction_site_id, 'project.material_direct_purchase.edit') then
    raise exception 'Bạn không có quyền chuyển trạng thái phiếu mua nóng này.';
  end if;

  v_target_status := case p_action
    when 'submit' then 'submitted'
    when 'return_to_draft' then 'draft'
    when 'approve_to_buy' then 'approved_to_buy'
    when 'cancel_approval' then 'submitted'
    when 'mark_purchased' then 'purchased'
    when 'close_after_payment' then 'closed'
    else null
  end;

  if v_target_status is null then
    raise exception 'Thao tác vòng đời mua nóng không hợp lệ: %.', p_action;
  end if;

  update public.site_direct_purchases purchase
  set
    status = v_target_status,
    submitted_to_user_id = case when p_action = 'submit' then p_target_user_id else purchase.submitted_to_user_id end,
    submitted_to_name = case when p_action = 'submit' then p_target_name else purchase.submitted_to_name end,
    submitted_to_permission = case when p_action = 'submit' then coalesce(p_target_permission, 'approve') else purchase.submitted_to_permission end,
    ever_submitted = case when p_action = 'submit' then true else purchase.ever_submitted end,
    last_action_by = auth.uid(),
    last_action_at = now(),
    note = case
      when p_action = 'cancel_approval' and nullif(btrim(p_reason), '') is not null
        then concat_ws(E'\\n', nullif(purchase.note, ''), 'Hủy duyệt: ' || btrim(p_reason))
      else purchase.note
    end,
    updated_at = now()
  where purchase.id = v_purchase.id
  returning * into v_purchase;

  return v_purchase;
end;
$$","create or replace function public.delete_site_direct_purchase_v1(p_direct_purchase_id uuid)
returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_purchase public.site_direct_purchases%rowtype;
begin
  select * into v_purchase
  from public.site_direct_purchases
  where id = p_direct_purchase_id
  for update;

  if not found then
    raise exception 'Không tìm thấy phiếu mua nóng %. ', p_direct_purchase_id;
  end if;

  if not app_private.material_flow_has_action_or_legacy(v_purchase.project_id, v_purchase.construction_site_id, 'project.material_direct_purchase.delete') then
    raise exception 'Bạn không có quyền xóa phiếu mua nóng.';
  end if;

  if v_purchase.status <> 'draft' or coalesce(v_purchase.ever_submitted, false) then
    raise exception 'Chỉ xóa được phiếu mua nóng ở trạng thái Nháp và chưa từng trình duyệt.';
  end if;

  if v_purchase.wms_transaction_id is not null
    or v_purchase.site_cash_settlement_id is not null
    or exists (
      select 1 from public.supplier_payable_documents payable
      where payable.source_type = 'site_direct_purchase'
        and payable.source_id = p_direct_purchase_id::text
    )
    or exists (
      select 1 from public.site_small_tool_records tool
      where tool.source_type = 'site_direct_purchase'
        and tool.source_id = p_direct_purchase_id::text
    )
  then
    raise exception 'Không thể xóa phiếu mua nóng đã phát sinh WMS, CCDC, công nợ hoặc hoàn ứng.';
  end if;

  delete from public.site_direct_purchases where id = p_direct_purchase_id;
end;
$$","create or replace function app_private.sync_site_direct_purchase_payment_status()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if new.source_type <> 'site_direct_purchase' then
    return new;
  end if;

  if new.status = 'paid' then
    update public.site_direct_purchases purchase
    set status = 'closed', updated_at = now()
    where purchase.id::text = new.source_id
      and purchase.status = 'reconciled';
  elsif old.status = 'paid' and new.status in ('open', 'payable', 'partial') then
    update public.site_direct_purchases purchase
    set status = 'reconciled', updated_at = now()
    where purchase.id::text = new.source_id
      and purchase.status = 'closed';
  end if;

  return new;
end;
$$","drop trigger if exists trg_sync_site_direct_purchase_payment_status on public.supplier_payable_documents","create trigger trg_sync_site_direct_purchase_payment_status
after update of status on public.supplier_payable_documents
for each row execute function app_private.sync_site_direct_purchase_payment_status()","revoke all on function public.record_site_direct_purchase_payable_v1(uuid) from public, anon","revoke all on function public.unrecord_site_direct_purchase_payable_v1(uuid, text) from public, anon","revoke all on function public.reject_site_direct_purchase_v1(uuid, text) from public, anon","revoke all on function public.transition_site_direct_purchase_v1(uuid, text, text, uuid, text, text) from public, anon","grant execute on function public.record_site_direct_purchase_payable_v1(uuid) to authenticated","grant execute on function public.unrecord_site_direct_purchase_payable_v1(uuid, text) to authenticated","grant execute on function public.reject_site_direct_purchase_v1(uuid, text) to authenticated","grant execute on function public.transition_site_direct_purchase_v1(uuid, text, text, uuid, text, text) to authenticated","notify pgrst, 'reload schema'"}

{"drop function if exists public.create_material_issue_order(
  text, text, text, text, text, text, uuid, text, text, text, date, text, jsonb
)","create function public.create_material_issue_order(
  p_project_id text,
  p_construction_site_id text,
  p_source_warehouse_id text,
  p_recipient_type text,
  p_recipient_id text,
  p_recipient_name text,
  p_responsible_user_id uuid,
  p_subcontractor_contract_id text,
  p_material_request_id text,
  p_work_boq_item_id text,
  p_needed_date date,
  p_note text,
  p_lines jsonb,
  p_recipient_source_type text default null,
  p_recipient_source_id text default null
)
returns public.material_issue_orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := public.current_app_user_id();
  v_order public.material_issue_orders%rowtype;
  v_order_id uuid := gen_random_uuid();
  v_issue_no text;
  v_line jsonb;
  v_item public.items%rowtype;
  v_qty numeric;
begin
  if v_actor is null then raise exception 'authentication required'; end if;
  if not (
    app_private.material_issue_can_manage_project(p_project_id, p_construction_site_id)
    or app_private.current_user_is_wms_keeper_for(p_source_warehouse_id)
  ) then
    raise exception 'Bạn không có quyền tạo phiếu xuất cấp cho dự án/công trường này.';
  end if;
  if coalesce(p_source_warehouse_id, '') = '' then raise exception 'Chưa chọn kho xuất.'; end if;
  if p_recipient_type not in ('employee', 'work_group', 'subcontractor', 'partner', 'manual') then
    raise exception 'Loại bên nhận không hợp lệ.';
  end if;
  if coalesce(trim(p_recipient_name), '') = '' then raise exception 'Chưa nhập tên bên nhận.'; end if;
  if p_recipient_source_type is not null
     and p_recipient_source_type not in ('supplier_contract', 'business_partner') then
    raise exception 'Nguồn bên nhận không hợp lệ.';
  end if;
  if (p_recipient_source_type is null)
     <> (nullif(trim(coalesce(p_recipient_source_id, '')), '') is null) then
    raise exception 'Nguồn bên nhận phải có đủ loại và mã tham chiếu.';
  end if;
  if jsonb_typeof(p_lines) <> 'array' or jsonb_array_length(p_lines) = 0 then
    raise exception 'Phiếu xuất cấp chưa có dòng vật tư.';
  end if;

  v_issue_no := 'MI-' || to_char(now(), 'YYYYMMDD') || '-' || upper(substr(replace(v_order_id::text, '-', ''), 1, 6));

  insert into public.material_issue_orders(
    id, issue_no, project_id, construction_site_id, source_warehouse_id,
    recipient_type, recipient_id, recipient_name, recipient_source_type, recipient_source_id,
    responsible_user_id, subcontractor_contract_id, material_request_id, work_boq_item_id,
    needed_date, status, note, created_by
  ) values (
    v_order_id, v_issue_no, nullif(p_project_id, ''), nullif(p_construction_site_id, ''), p_source_warehouse_id,
    p_recipient_type, nullif(p_recipient_id, ''), trim(p_recipient_name),
    p_recipient_source_type, nullif(trim(coalesce(p_recipient_source_id, '')), ''),
    p_responsible_user_id, nullif(p_subcontractor_contract_id, ''), nullif(p_material_request_id, ''), nullif(p_work_boq_item_id, ''),
    p_needed_date, 'draft', nullif(trim(coalesce(p_note, '')), ''), v_actor
  )
  returning * into v_order;

  for v_line in select value from jsonb_array_elements(p_lines)
  loop
    v_qty := coalesce(nullif(v_line ->> 'quantity', '')::numeric, 0);
    if coalesce(v_line ->> 'itemId', '') = '' or v_qty <= 0 then
      raise exception 'Dòng vật tư không hợp lệ.';
    end if;

    select * into v_item from public.items where id = v_line ->> 'itemId';
    if not found then raise exception 'Không tìm thấy vật tư %.', v_line ->> 'itemId'; end if;

    insert into public.material_issue_lines(
      issue_order_id, item_id, sku_snapshot, item_name_snapshot, unit,
      requested_qty, approved_qty, unit_price,
      material_budget_item_id, material_request_line_id, work_boq_item_id,
      subcontractor_contract_id, note
    ) values (
      v_order_id, v_item.id, v_item.sku, v_item.name, coalesce(nullif(v_line ->> 'unit', ''), v_item.unit),
      v_qty, v_qty, coalesce(nullif(v_line ->> 'unitPrice', '')::numeric, coalesce(v_item.price_in, 0)),
      nullif(v_line ->> 'materialBudgetItemId', ''),
      nullif(v_line ->> 'materialRequestLineId', ''),
      coalesce(nullif(v_line ->> 'workBoqItemId', ''), nullif(p_work_boq_item_id, '')),
      coalesce(nullif(v_line ->> 'subcontractorContractId', ''), nullif(p_subcontractor_contract_id, '')),
      nullif(trim(coalesce(v_line ->> 'note', '')), '')
    );
  end loop;

  return v_order;
end;
