{"create schema if not exists app_private","create or replace function app_private.purchase_receipt_command_result_v2(
  p_delivery_batch_id uuid,
  p_already_finalized boolean default false
) returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'deliveryBatchId', batch.id::text,
    'wmsTransactionId', coalesce(batch.wms_transaction_id, ''),
    'deliveryStatus', batch.status,
    'transactionStatus', tx.status::text,
    'acceptedGrossAmount', coalesce(batch.accepted_gross_amount, 0),
    'alreadyFinalized', p_already_finalized
  )
  from public.purchase_order_delivery_batches batch
  join public.transactions tx on tx.id = batch.wms_transaction_id
  where batch.id = p_delivery_batch_id;
$$","revoke all on function app_private.purchase_receipt_command_result_v2(uuid, boolean)
  from public, anon","grant execute on function app_private.purchase_receipt_command_result_v2(uuid, boolean)
  to authenticated","create or replace function app_private.current_user_can_receive_purchase_batch_v2(
  p_actor_user_id uuid,
  p_target_warehouse_id text
) returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    public.is_admin()
    or public.is_module_admin('WMS')
    or app_private.current_user_is_global_wms_keeper()
    or app_private.current_user_is_wms_keeper_for(p_target_warehouse_id)
    or exists (
      select 1
      from public.users u
      where u.id = p_actor_user_id
        and u.is_active is not false
        and coalesce(u.account_status, 'ACTIVE') = 'ACTIVE'
        and u.role::text in ('ADMIN', 'WAREHOUSE_KEEPER', 'KEEPER')
        and (
          u.assigned_warehouse_id is null
          or u.assigned_warehouse_id = p_target_warehouse_id
        )
    ),
    false
  );
$$","revoke all on function app_private.current_user_can_receive_purchase_batch_v2(uuid, text)
  from public, anon","grant execute on function app_private.current_user_can_receive_purchase_batch_v2(uuid, text)
  to authenticated","create or replace function app_private.approve_receipt_quality_v2(
  p_delivery_batch_id uuid,
  p_wms_transaction_id text,
  p_actor_user_id uuid,
  p_quality_result text,
  p_lines jsonb,
  p_attachments jsonb
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_po_id text;
  v_po public.purchase_orders%rowtype;
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_tx public.transactions%rowtype;
  v_line jsonb;
  v_delivery_line public.purchase_order_delivery_lines%rowtype;
  v_delivery_line_id uuid;
  v_item_id text;
  v_accepted_purchase_qty numeric;
  v_accepted_stock_qty numeric;
  v_expected_stock_qty numeric;
  v_stock_factor numeric;
  v_variance_reason text;
  v_seen_line_ids uuid[] := '{}'::uuid[];
  v_expected_line_count integer;
  v_wms_items jsonb := '[]'::jsonb;
  v_gross numeric := 0;
  v_combined_reason text;
  v_variance_qty numeric;
  v_stock_unit_price numeric;
begin
  if p_actor_user_id is null then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if public.current_app_user_id() is null or p_actor_user_id <> public.current_app_user_id() then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if p_quality_result not in ('passed', 'partial', 'rejected') then
    raise exception 'Ket qua kiem tra SL/CL khong hop le.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' then
    raise exception 'Dong nhan hang khong hop le.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_attachments, '[]'::jsonb)) <> 'array' then
    raise exception 'Dinh kem nhan hang khong hop le.' using errcode = '22023';
  end if;

  select purchase_order_id into v_po_id
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id;
  if not found then
    raise exception 'Khong tim thay Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;

  select * into v_po
  from public.purchase_orders
  where id = v_po_id
  for update;
  if not found then
    raise exception 'Khong tim thay Goi mua hang cua Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;

  select * into v_batch
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id
  for update;
  if not found then
    raise exception 'Khong tim thay Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;
  if v_batch.wms_transaction_id is distinct from p_wms_transaction_id then
    raise exception 'WMS transaction khong khop Dot giao.' using errcode = '22023';
  end if;
  if v_batch.status <> 'receiving' then
    raise exception 'Dot giao da khoa hoac khong con cho duyet SL/CL.' using errcode = '22023';
  end if;

  select * into v_tx
  from public.transactions
  where id = p_wms_transaction_id
  for update;
  if not found then
    raise exception 'Khong tim thay WMS cua Dot giao.' using errcode = '22023';
  end if;
  if v_tx.source_type <> 'po_delivery_batch' or v_tx.source_id <> p_delivery_batch_id::text then
    raise exception 'WMS khong lien ket dung Dot giao.' using errcode = '22023';
  end if;
  if v_tx.status <> 'PENDING'::public.transaction_status then
    raise exception 'Phieu WMS da khoa va khong con cho duyet SL/CL.' using errcode = '22023';
  end if;
  if not app_private.current_user_can_receive_purchase_batch_v2(p_actor_user_id, v_tx.target_warehouse_id) then
    raise exception 'Nguoi dung khong co quyen duyet SL/CL tai kho nhan.' using errcode = '42501';
  end if;

  select count(*) into v_expected_line_count
  from public.purchase_order_delivery_lines
  where delivery_batch_id = p_delivery_batch_id;
  if v_expected_line_count = 0 or jsonb_array_length(p_lines) <> v_expected_line_count then
    raise exception 'Payload nhan hang phai khop 1-1 voi dong Dot giao.' using errcode = '22023';
  end if;

  for v_line in
    select value from jsonb_array_elements(p_lines) as line(value)
  loop
    v_delivery_line_id := nullif(coalesce(v_line ->> 'deliveryLineId', v_line ->> 'delivery_line_id'), '')::uuid;
    v_item_id := nullif(coalesce(v_line ->> 'itemId', v_line ->> 'item_id'), '');
    v_accepted_purchase_qty := coalesce(
      nullif(coalesce(v_line ->> 'acceptedPurchaseQty', v_line ->> 'accepted_purchase_qty'), '')::numeric,
      0
    );
    v_accepted_stock_qty := coalesce(
      nullif(coalesce(v_line ->> 'acceptedStockQty', v_line ->> 'accepted_stock_qty'), '')::numeric,
      0
    );
    v_variance_reason := nullif(trim(coalesce(v_line ->> 'varianceReason', v_line ->> 'variance_reason', '')), '');

    if v_delivery_line_id is null or v_item_id is null then
      raise exception 'Dong nhan hang thieu deliveryLineId hoac itemId.' using errcode = '22023';
    end if;
    if v_delivery_line_id = any(v_seen_line_ids) then
      raise exception 'Dong nhan hang bi lap.' using errcode = '22023';
    end if;
    if v_accepted_purchase_qty < 0 or v_accepted_stock_qty < 0 then
      raise exception 'So luong thuc nhan khong duoc am.' using errcode = '22023';
    end if;

    select * into v_delivery_line
    from public.purchase_order_delivery_lines
    where id = v_delivery_line_id
      and delivery_batch_id = p_delivery_batch_id
    for update;
    if not found then
      raise exception 'Dong nhan hang khong thuoc Dot giao.' using errcode = '22023';
    end if;
    if v_delivery_line.item_id <> v_item_id then
      raise exception 'Vat tu nhan hang khong khop dong Dot giao.' using errcode = '22023';
    end if;

    v_stock_factor := case
      when coalesce(v_delivery_line.planned_qty, 0) > 0
        and coalesce(v_delivery_line.stock_planned_qty, 0) > 0
        then v_delivery_line.stock_planned_qty / v_delivery_line.planned_qty
      else 1
    end;
    v_expected_stock_qty := round(v_accepted_purchase_qty * v_stock_factor, 6);
    if abs(v_expected_stock_qty - round(v_accepted_stock_qty, 6)) > 0.000001 then
      raise exception 'So luong ton kho thuc nhan khong khop snapshot quy doi.' using errcode = '22023';
    end if;
    if v_accepted_purchase_qty is distinct from coalesce(v_delivery_line.planned_qty, 0)
       and v_variance_reason is null then
      raise exception 'Phai nhap ly do khi so luong thuc nhan lech Dot giao.' using errcode = '22023';
    end if;

    update public.purchase_order_delivery_lines
    set accepted_qty = v_accepted_purchase_qty,
        accepted_stock_qty = v_accepted_stock_qty,
        updated_at = now()
    where id = v_delivery_line.id;

    v_seen_line_ids := array_append(v_seen_line_ids, v_delivery_line.id);
    v_variance_qty := v_accepted_purchase_qty - coalesce(v_delivery_line.planned_qty, 0);
    if v_variance_reason is not null then
      v_combined_reason := concat_ws('; ', v_combined_reason, v_variance_reason);
    end if;
    v_stock_unit_price := case
      when v_stock_factor > 0 then coalesce(v_delivery_line.delivery_unit_price, 0) / v_stock_factor
      else coalesce(v_delivery_line.delivery_unit_price, 0)
    end;
    v_gross := v_gross
      + v_accepted_purchase_qty
      * coalesce(v_delivery_line.delivery_unit_price, 0)
      * (1 + coalesce(v_batch.vat_rate, 0) / 100);

    v_wms_items := v_wms_items || jsonb_build_array(jsonb_build_object(
      'itemId', v_delivery_line.item_id,
      'quantity', v_accepted_stock_qty,
      'orderedQty', coalesce(v_delivery_line.stock_planned_qty, v_delivery_line.planned_qty, 0),
      'price', v_stock_unit_price,
      'accountingQty', v_accepted_purchase_qty,
      'accountingUnit', coalesce(v_delivery_line.unit, v_delivery_line.stock_unit, ''),
      'accountingPrice', coalesce(v_delivery_line.delivery_unit_price, 0),
      'varianceQty', v_variance_qty,
      'varianceReason', v_variance_reason,
      'purchaseOrderLineId', v_delivery_line.purchase_order_line_id,
      'purchaseOrderDeliveryBatchId', p_delivery_batch_id,
      'purchaseOrderDeliveryLineId', v_delivery_line.id,
      'fulfillmentMode', coalesce(v_batch.fulfillment_mode, 'RECEIVE_TO_STOCK')
    ));
  end loop;

  if coalesce(array_length(v_seen_line_ids, 1), 0) <> v_expected_line_count then
    raise exception 'Payload nhan hang thieu dong Dot giao.' using errcode = '22023';
  end if;

  update public.transactions
  set items = v_wms_items,
      attachments = coalesce(p_attachments, '[]'::jsonb),
      status = 'APPROVED'::public.transaction_status,
      approver_id = p_actor_user_id,
      approved_at = now()
  where id = p_wms_transaction_id;

  update public.purchase_order_delivery_batches
  set status = 'quality_approved',
      quality_result = p_quality_result,
      variance_reason = v_combined_reason,
      quality_approved_by = p_actor_user_id,
      quality_approved_at = now(),
      accepted_gross_amount = round(v_gross, 2),
      updated_at = now()
  where id = p_delivery_batch_id;

  return app_private.purchase_receipt_command_result_v2(p_delivery_batch_id, false);
end;
$$","revoke all on function app_private.approve_receipt_quality_v2(uuid, text, uuid, text, jsonb, jsonb)
  from public, anon","grant execute on function app_private.approve_receipt_quality_v2(uuid, text, uuid, text, jsonb, jsonb)
  to authenticated","create or replace function public.approve_receipt_quality_v2(
  p_delivery_batch_id uuid,
  p_wms_transaction_id text,
  p_actor_user_id uuid default null,
  p_quality_result text default 'passed',
  p_lines jsonb default '[]'::jsonb,
  p_attachments jsonb default '[]'::jsonb
) returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_current_actor text := nullif(public.current_app_user_id()::text, '');
  v_actor uuid := coalesce(p_actor_user_id, v_current_actor::uuid);
begin
  if v_current_actor is null or v_actor::text <> v_current_actor then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;

  return app_private.approve_receipt_quality_v2(
    p_delivery_batch_id,
    p_wms_transaction_id,
    v_actor,
    p_quality_result,
    p_lines,
    p_attachments
  );
end;
$$","revoke all on function public.approve_receipt_quality_v2(uuid, text, uuid, text, jsonb, jsonb)
  from public, anon","grant execute on function public.approve_receipt_quality_v2(uuid, text, uuid, text, jsonb, jsonb)
  to authenticated","create or replace function app_private.finalize_purchase_receipt_v2(
  p_delivery_batch_id uuid,
  p_wms_transaction_id text,
  p_actor_user_id uuid
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_po_id text;
  v_po public.purchase_orders%rowtype;
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_tx public.transactions%rowtype;
  v_item jsonb;
  v_item_id text;
  v_qty numeric;
  v_planned_purchase_qty numeric;
  v_accepted_purchase_qty numeric;
  v_delivery_status text;
  v_next_items jsonb;
  v_is_delivered boolean;
  v_already_recorded boolean;
begin
  if p_actor_user_id is null then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if public.current_app_user_id() is null or p_actor_user_id <> public.current_app_user_id() then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;

  select purchase_order_id into v_po_id
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id;
  if not found then
    raise exception 'Khong tim thay Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;

  select * into v_po
  from public.purchase_orders
  where id = v_po_id
  for update;
  if not found then
    raise exception 'Khong tim thay Goi mua hang cua Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;

  select * into v_batch
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id
  for update;
  if not found then
    raise exception 'Khong tim thay Dot giao %.', p_delivery_batch_id using errcode = '22023';
  end if;
  if v_batch.wms_transaction_id is distinct from p_wms_transaction_id then
    raise exception 'WMS transaction khong khop Dot giao.' using errcode = '22023';
  end if;

  select * into v_tx
  from public.transactions
  where id = p_wms_transaction_id
  for update;
  if not found then
    raise exception 'Khong tim thay WMS cua Dot giao.' using errcode = '22023';
  end if;
  if v_tx.source_type <> 'po_delivery_batch' or v_tx.source_id <> p_delivery_batch_id::text then
    raise exception 'WMS khong lien ket dung Dot giao.' using errcode = '22023';
  end if;
  if not app_private.current_user_can_receive_purchase_batch_v2(p_actor_user_id, v_tx.target_warehouse_id) then
    raise exception 'Nguoi dung khong co quyen xac nhan nhan hang tai kho nhan.' using errcode = '42501';
  end if;

  if v_batch.status in ('received', 'received_short', 'received_over')
     and v_tx.status = 'COMPLETED'::public.transaction_status then
    return app_private.purchase_receipt_command_result_v2(p_delivery_batch_id, true);
  end if;
  if v_batch.status in ('received', 'received_short', 'received_over')
     or v_tx.status = 'COMPLETED'::public.transaction_status then
    raise exception 'Anomaly: Dot giao va WMS khong dong bo trang thai finalize.' using errcode = 'P0001';
  end if;
  if v_batch.status <> 'quality_approved' or v_tx.status <> 'APPROVED'::public.transaction_status then
    raise exception 'Chi finalize Dot da duyet SL/CL va WMS APPROVED.' using errcode = '22023';
  end if;

  perform 1
  from public.purchase_order_delivery_lines
  where delivery_batch_id = p_delivery_batch_id
  order by id
  for update;

  perform 1
  from public.items item
  where item.id in (
    select distinct line.value ->> 'itemId'
    from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb)) line(value)
    where nullif(line.value ->> 'itemId', '') is not null
  )
  order by item.id
  for update;

  if coalesce(v_batch.fulfillment_mode, 'RECEIVE_TO_STOCK') = 'RECEIVE_TO_STOCK' then
    for v_item in
      select value from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb)) as item(value)
    loop
      v_item_id := nullif(v_item ->> 'itemId', '');
      v_qty := coalesce(nullif(v_item ->> 'quantity', '')::numeric, 0);
      if v_item_id is null or v_qty < 0 then
        raise exception 'WMS item nhan hang khong hop le.' using errcode = '22023';
      end if;
      if v_qty > 0 then
        perform public.apply_stock_change(v_item_id, v_tx.target_warehouse_id, v_qty);
      end if;
    end loop;
  elsif coalesce(v_batch.fulfillment_mode, '') <> 'DIRECT_CONSUMPTION' then
    raise exception 'Fulfillment mode khong hop le: %', v_batch.fulfillment_mode using errcode = '22023';
  end if;

  update public.transactions
  set status = 'COMPLETED'::public.transaction_status,
      approver_id = p_actor_user_id,
      approved_at = coalesce(approved_at, now())
  where id = p_wms_transaction_id
  returning * into v_tx;

  select
    coalesce(sum(coalesce(planned_qty, 0)), 0),
    coalesce(sum(coalesce(accepted_qty, 0)), 0)
  into v_planned_purchase_qty, v_accepted_purchase_qty
  from public.purchase_order_delivery_lines
  where delivery_batch_id = p_delivery_batch_id;

  v_delivery_status := case
    when v_accepted_purchase_qty > v_planned_purchase_qty then 'received_over'
    when v_accepted_purchase_qty < v_planned_purchase_qty then 'received_short'
    else 'received'
  end;

  update public.purchase_order_delivery_batches
  set status = v_delivery_status,
      received_by = p_actor_user_id,
      received_at = now(),
      updated_at = now()
  where id = p_delivery_batch_id
  returning * into v_batch;

  select exists (
    select 1
    from jsonb_array_elements_text(coalesce(v_po.received_transaction_ids, '[]'::jsonb)) existing(id)
    where existing.id = v_tx.id
  ) into v_already_recorded;

  with receipt_by_line as (
    select
      purchase_order_line_id,
      sum(coalesce(accepted_qty, 0)) as accepted_purchase_qty
    from public.purchase_order_delivery_lines
    where delivery_batch_id = p_delivery_batch_id
    group by purchase_order_line_id
  ),
  item_rows as (
    select
      item.value as item,
      item.ordinality,
      coalesce(item.value ->> 'lineId', item.value ->> 'line_id', item.value ->> 'itemId', item.value ->> 'item_id') as line_key,
      coalesce(nullif(item.value ->> 'receivedQty', '')::numeric, 0) as current_received_qty
    from jsonb_array_elements(coalesce(v_po.items, '[]'::jsonb)) with ordinality item(value, ordinality)
  ),
  next_rows as (
    select
      case
        when coalesce(r.accepted_purchase_qty, 0) > 0 then
          jsonb_set(
            ir.item,
            '{receivedQty}',
            to_jsonb(ir.current_received_qty + coalesce(r.accepted_purchase_qty, 0)),
            true
          )
        else ir.item
      end as item,
      ir.ordinality
    from item_rows ir
    left join receipt_by_line r on r.purchase_order_line_id = ir.line_key
  )
  select coalesce(jsonb_agg(item order by ordinality), '[]'::jsonb)
  into v_next_items
  from next_rows;

  select coalesce(bool_and(
    coalesce(nullif(item.value ->> 'receivedQty', '')::numeric, 0)
      >= coalesce(nullif(item.value ->> 'qty', '')::numeric, 0)
  ), false)
  into v_is_delivered
  from jsonb_array_elements(coalesce(v_next_items, '[]'::jsonb)) item(value);

  update public.purchase_orders
  set items = v_next_items,
      status = case when v_is_delivered then 'delivered' else 'partial' end,
      actual_delivery_date = case when v_is_delivered then current_date::text else actual_delivery_date end,
      received_transaction_ids = case
        when v_already_recorded then coalesce(received_transaction_ids, '[]'::jsonb)
        else coalesce(received_transaction_ids, '[]'::jsonb) || jsonb_build_array(v_tx.id)
      end
  where id = v_po.id;

  update public.material_request_fulfillment_lines mfl
  set received_qty = coalesce(line.accepted_stock_qty, line.accepted_qty, 0),
      variance_reason = coalesce(v_batch.variance_reason, mfl.variance_reason),
      updated_at = now()
  from public.purchase_order_delivery_lines line
  where mfl.po_delivery_line_id = line.id
    and line.delivery_batch_id = p_delivery_batch_id;

  update public.material_request_fulfillment_batches
  set status = 'received',
      received_by = p_actor_user_id,
      received_at = now(),
      updated_at = now()
  where po_delivery_batch_id = p_delivery_batch_id
    and status = 'issued';

  return app_private.purchase_receipt_command_result_v2(p_delivery_batch_id, false);
end;
$$","revoke all on function app_private.finalize_purchase_receipt_v2(uuid, text, uuid)
  from public, anon","grant execute on function app_private.finalize_purchase_receipt_v2(uuid, text, uuid)
  to authenticated","create or replace function public.finalize_purchase_receipt_v2(
  p_delivery_batch_id uuid,
  p_wms_transaction_id text,
  p_actor_user_id uuid default null
) returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_current_actor text := nullif(public.current_app_user_id()::text, '');
  v_actor uuid := coalesce(p_actor_user_id, v_current_actor::uuid);
begin
  if v_current_actor is null or v_actor::text <> v_current_actor then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;

  return app_private.finalize_purchase_receipt_v2(
    p_delivery_batch_id,
    p_wms_transaction_id,
    v_actor
  );
end;
$$","revoke all on function public.finalize_purchase_receipt_v2(uuid, text, uuid)
  from public, anon","grant execute on function public.finalize_purchase_receipt_v2(uuid, text, uuid)
  to authenticated","create or replace function app_private.trg_sync_wms_transaction_inventory_ledger()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status::text = 'COMPLETED'
     and (tg_op = 'INSERT' or old.status is distinct from new.status)
     and not (
       new.source_type = 'po_delivery_batch'
       and exists (
         select 1
         from jsonb_array_elements(coalesce(new.items, '[]'::jsonb)) item(value)
         where item.value ->> 'fulfillmentMode' = 'DIRECT_CONSUMPTION'
       )
     ) then
    perform app_private.sync_wms_transaction_to_inventory_ledger(new.id);
  end if;
  return new;
end;
$$","notify pgrst, 'reload schema'"}

{"create schema if not exists app_private","create or replace function app_private.post_purchase_receipt_return_finance_v2(
  p_supplier_return_id uuid,
  p_actor_user_id uuid
) returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_return public.purchase_order_supplier_returns%rowtype;
  v_po public.purchase_orders%rowtype;
  v_tx public.transactions%rowtype;
  v_has_v2_receipt boolean := false;
  v_existing_cost public.project_transactions%rowtype;
  v_project_finance_id text;
  v_source_ref text := 'purchase_receipt_return:' || p_supplier_return_id::text;
  v_description text;
  v_total_gross numeric(18,2) := 0;
  v_return_line record;
  v_delivery record;
  v_remaining_qty numeric;
  v_take_qty numeric;
  v_line_gross numeric(18,2);
  v_ap public.supplier_payable_documents%rowtype;
  v_credit_key text;
  v_existing_credit jsonb;
begin
  select * into v_return
  from public.purchase_order_supplier_returns
  where id = p_supplier_return_id
  for update;
  if not found then
    raise exception 'Khong tim thay phieu tra NCC %.', p_supplier_return_id using errcode = '22023';
  end if;
  if v_return.status <> 'completed' then
    raise exception 'Chi post finance cho phieu tra NCC da completed.' using errcode = '22023';
  end if;

  select * into v_existing_cost
  from public.project_transactions
  where source_ref = v_source_ref
  for update;
  if found then
    return;
  end if;

  select * into v_tx
  from public.transactions
  where id = v_return.transaction_id
  for update;
  if not found or v_tx.status <> 'COMPLETED'::public.transaction_status then
    raise exception 'Chi post finance tra NCC khi WMS EXPORT da COMPLETED.' using errcode = '22023';
  end if;

  select * into v_po
  from public.purchase_orders
  where id = v_return.purchase_order_id
  for update;
  if not found then
    raise exception 'Khong tim thay PO cua phieu tra NCC %.', p_supplier_return_id using errcode = '22023';
  end if;

  select exists (
    select 1
    from public.purchase_order_delivery_lines line
    join public.purchase_order_delivery_batches batch on batch.id = line.delivery_batch_id
    where line.purchase_order_id = v_return.purchase_order_id
      and batch.status in ('received', 'received_short', 'received_over')
      and coalesce(line.accepted_qty, 0) > 0
  ) into v_has_v2_receipt;

  if not v_has_v2_receipt then
    return;
  end if;

  select id into v_project_finance_id
  from public.project_finances
  where (v_po.project_id is not null and project_id = v_po.project_id)
     or (v_po.construction_site_id is not null and construction_site_id = v_po.construction_site_id)
  limit 1;

  for v_return_line in
    select *
    from public.purchase_order_supplier_return_lines
    where supplier_return_id = p_supplier_return_id
    order by id
  loop
    v_remaining_qty := coalesce(v_return_line.return_qty, 0);
    if v_remaining_qty <= 0 then
      raise exception 'Dong tra NCC khong hop le.' using errcode = '22023';
    end if;

    for v_delivery in
      select
        line.id as delivery_line_id,
        line.delivery_batch_id,
        line.purchase_order_line_id,
        line.accepted_qty,
        line.returned_qty,
        line.delivery_unit_price,
        batch.delivery_no,
        batch.vat_rate,
        batch.received_at,
        batch.updated_at,
        batch.created_at
      from public.purchase_order_delivery_lines line
      join public.purchase_order_delivery_batches batch on batch.id = line.delivery_batch_id
      where line.purchase_order_id = v_return.purchase_order_id
        and line.purchase_order_line_id = v_return_line.purchase_order_line_id
        and batch.status in ('received', 'received_short', 'received_over')
        and coalesce(line.accepted_qty, 0) > coalesce(line.returned_qty, 0)
      order by coalesce(batch.received_at, batch.updated_at, batch.created_at), batch.delivery_no, line.id
      for update of line
    loop
      exit when v_remaining_qty <= 0;

      v_take_qty := least(
        v_remaining_qty,
        greatest(0, coalesce(v_delivery.accepted_qty, 0) - coalesce(v_delivery.returned_qty, 0))
      );
      if v_take_qty <= 0 then
        continue;
      end if;

      update public.purchase_order_delivery_lines
      set returned_qty = round(coalesce(returned_qty, 0) + v_take_qty, 6),
          updated_at = now()
      where id = v_delivery.delivery_line_id;

      v_line_gross := round(
        v_take_qty
        * coalesce(v_delivery.delivery_unit_price, 0)
        * (1 + coalesce(v_delivery.vat_rate, 0) / 100),
        2
      );
      v_total_gross := round(v_total_gross + v_line_gross, 2);

      select * into v_ap
      from public.supplier_payable_documents
      where source_type = 'purchase_delivery_receipt'
        and source_id = v_delivery.delivery_batch_id::text
      for update;
      if not found then
        raise exception 'Anomaly: AP receipt cua Dot giao % chua duoc ghi nhan.', v_delivery.delivery_batch_id
          using errcode = 'P0001';
      end if;
      if v_ap.status in ('cancelled', 'reversed') then
        raise exception 'Anomaly: khong the credit AP receipt da huy/dao.' using errcode = 'P0001';
      end if;

      v_credit_key := p_supplier_return_id::text || ':' || v_delivery.delivery_line_id::text;
      v_existing_credit := coalesce(v_ap.metadata, '{}'::jsonb)
        -> 'purchaseReceiptReturnCredits'
        -> v_credit_key;

      if v_existing_credit is not null then
        if round(coalesce(nullif(v_existing_credit ->> 'amount', '')::numeric, 0), 2) <> v_line_gross then
          raise exception 'Anomaly: AP return credit da ton tai voi gia tri khac.' using errcode = 'P0001';
        end if;
      else
        update public.supplier_payable_documents
        set credit_amount = round(coalesce(credit_amount, 0) + v_line_gross, 2),
            status = case
              when round(coalesce(recognized_amount, 0) - (coalesce(credit_amount, 0) + v_line_gross), 2) <= 0 then 'paid'
              when coalesce(credit_amount, 0) + v_line_gross > 0 then 'partial'
              else status
            end,
            metadata = jsonb_set(
              coalesce(metadata, '{}'::jsonb),
              '{purchaseReceiptReturnCredits}',
              coalesce(metadata -> 'purchaseReceiptReturnCredits', '{}'::jsonb)
                || jsonb_build_object(
                  v_credit_key,
                  jsonb_build_object(
                    'sourceType', 'supplier_return_credit',
                    'sourceId', p_supplier_return_id::text,
                    'sourceRef', v_source_ref,
                    'deliveryBatchId', v_delivery.delivery_batch_id::text,
                    'deliveryLineId', v_delivery.delivery_line_id::text,
                    'purchaseOrderLineId', v_return_line.purchase_order_line_id,
                    'returnQty', v_take_qty,
                    'amount', v_line_gross
                  )
                ),
              true
            ),
            updated_at = now()
        where id = v_ap.id;
      end if;

      v_remaining_qty := v_remaining_qty - v_take_qty;
    end loop;

    if round(v_remaining_qty, 6) > 0 then
      raise exception 'So luong tra cua dong % vuot so luong delivery da accepted con co the tra.',
        v_return_line.purchase_order_line_id using errcode = '22023';
    end if;
  end loop;

  if v_total_gross <= 0 then
    return;
  end if;

  v_description := 'Return to supplier '
    || coalesce(v_return.return_no, p_supplier_return_id::text)
    || ' - '
    || coalesce(v_po.po_number, v_po.id);

  insert into public.project_transactions (
    id, \"projectFinanceId\", \"constructionSiteId\",
    project_id, project_finance_id, construction_site_id,
    type, category, amount, description, date, source,
    \"sourceRef\", source_ref, contract_cost_item_id,
    cost_classification_status, counterparty_partner_id,
    counterparty_name, attachments, \"createdBy\", \"createdAt\"
  )
  values (
    'purchase-return-cost-' || p_supplier_return_id::text,
    coalesce(v_project_finance_id, ''),
    coalesce(v_po.construction_site_id, ''),
    v_po.project_id,
    nullif(v_project_finance_id, ''),
    v_po.construction_site_id,
    'expense',
    'materials',
    -v_total_gross,
    v_description,
    current_date::text,
    'workflow',
    v_source_ref,
    v_source_ref,
    null,
    'auto',
    v_po.vendor_id,
    coalesce(v_po.vendor_name, v_po.vendor_id, 'Nha cung cap'),
    coalesce(v_tx.attachments, '[]'::jsonb),
    coalesce(p_actor_user_id, v_return.completed_by, v_return.created_by)::text,
    now()
  )
  on conflict (source_ref) do nothing;
end;
$$","revoke all on function app_private.post_purchase_receipt_return_finance_v2(uuid, uuid)
  from public, anon, authenticated","create or replace function app_private.trg_post_purchase_receipt_return_finance_v2()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.status = 'completed'
     and old.status is distinct from new.status then
    perform app_private.post_purchase_receipt_return_finance_v2(
      new.id,
      coalesce(new.completed_by, new.created_by)
    );
  end if;
  return new;
end;
$$","revoke all on function app_private.trg_post_purchase_receipt_return_finance_v2()
  from public, anon, authenticated","drop trigger if exists trg_post_purchase_receipt_return_finance_v2
  on public.purchase_order_supplier_returns","create trigger trg_post_purchase_receipt_return_finance_v2
after update of status on public.purchase_order_supplier_returns
for each row
execute function app_private.trg_post_purchase_receipt_return_finance_v2()","notify pgrst, 'reload schema'"}

{"create schema if not exists app_private","create or replace function app_private.close_purchase_package_short_v2(
  p_purchase_order_id text,
  p_actor_user_id uuid,
  p_reason text,
  p_lines jsonb
) returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_po public.purchase_orders%rowtype;
  v_line jsonb;
  v_purchase_order_line_id text;
  v_close_qty numeric;
  v_po_item jsonb;
  v_request_id text;
  v_request_line_id text;
  v_item_id text;
  v_ordered_qty numeric;
  v_received_qty numeric;
  v_returned_qty numeric;
  v_existing_closed_qty numeric;
  v_remaining_need numeric;
  v_total_closed_qty numeric := 0;
  v_previous_guard text;
begin
  if p_actor_user_id is null then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if public.current_app_user_id() is null or p_actor_user_id <> public.current_app_user_id() then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;
  if nullif(trim(coalesce(p_reason, '')), '') is null then
    raise exception 'Ly do ket thuc thieu la bat buoc.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_lines, '[]'::jsonb)) = 0 then
    raise exception 'Phai co it nhat mot dong can ket thuc thieu.' using errcode = '22023';
  end if;

  select * into v_po
  from public.purchase_orders
  where id = p_purchase_order_id
  for update;
  if not found then
    raise exception 'Khong tim thay Goi mua hang %.', p_purchase_order_id using errcode = '22023';
  end if;
  if coalesce(v_po.source_mode, '') <> 'from_request' or coalesce(v_po.purchase_mode, '') not in ('single', 'multiple') then
    raise exception 'Chi ket thuc thieu cho Goi mua hang V2 tao tu MR.' using errcode = '22023';
  end if;
  if v_po.status not in ('confirmed', 'in_transit', 'partial') then
    raise exception 'Chi ket thuc thieu cho Goi da duyet hoac dang giao.' using errcode = '22023';
  end if;

  perform app_private.assert_project_permission_room_action(
    v_po.project_id,
    v_po.construction_site_id,
    'material_po',
    'submit',
    p_actor_user_id
  );

  if exists (
    select 1
    from public.purchase_order_delivery_batches batch
    where batch.purchase_order_id = p_purchase_order_id
      and batch.status not in ('received', 'cancelled')
  ) then
    raise exception 'Goi mua hang con Dot giao mo, khong the ket thuc thieu.' using errcode = '22023';
  end if;

  for v_line in
    select value from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) as line(value)
  loop
    v_purchase_order_line_id := nullif(v_line ->> 'purchaseOrderLineId', '');
    v_close_qty := coalesce(nullif(v_line ->> 'closeQty', '')::numeric, 0);
    if v_purchase_order_line_id is null then
      raise exception 'Dong ket thuc thieu thieu PO line.' using errcode = '22023';
    end if;
    if v_close_qty <= 0 then
      raise exception 'So luong ket thuc thieu phai lon hon 0.' using errcode = '22023';
    end if;

    select item.value into v_po_item
    from jsonb_array_elements(coalesce(v_po.items, '[]'::jsonb)) as item(value)
    where coalesce(item.value ->> 'lineId', item.value ->> 'itemId') = v_purchase_order_line_id
    limit 1;
    if v_po_item is null then
      raise exception 'Khong tim thay dong Goi mua hang %.', v_purchase_order_line_id using errcode = '22023';
    end if;

    v_request_id := nullif(v_po_item ->> 'requestId', '');
    v_request_line_id := nullif(v_po_item ->> 'requestLineId', '');
    v_item_id := nullif(v_po_item ->> 'itemId', '');
    if v_request_id is null or v_request_line_id is null or v_item_id is null then
      raise exception 'Dong Goi mua hang thieu lien ket MR.' using errcode = '22023';
    end if;

    v_ordered_qty := coalesce(nullif(v_po_item ->> 'qty', '')::numeric, 0);
    v_received_qty := coalesce(nullif(v_po_item ->> 'receivedQty', '')::numeric, 0);
    v_returned_qty := coalesce(nullif(v_po_item ->> 'returnedQty', '')::numeric, 0);

    select coalesce(sum(closure.closed_qty), 0)
    into v_existing_closed_qty
    from public.material_request_line_need_closures closure
    where closure.material_request_id = v_request_id
      and closure.request_line_id = v_request_line_id
      and closure.status = 'active';

    v_remaining_need := greatest(0, v_ordered_qty - greatest(0, v_received_qty - v_returned_qty) - v_existing_closed_qty);
    if v_close_qty > v_remaining_need then
      raise exception 'So luong ket thuc thieu vuot nhu cau con lai cua dong %.', v_purchase_order_line_id using errcode = '22023';
    end if;

    insert into public.material_request_line_need_closures (
      project_id,
      construction_site_id,
      material_request_id,
      request_line_id,
      item_id,
      work_boq_item_id,
      material_budget_item_id,
      closed_qty,
      actual_received_qty_snapshot,
      reason,
      status,
      closed_by,
      closed_at
    ) values (
      v_po.project_id,
      v_po.construction_site_id,
      v_request_id,
      v_request_line_id,
      v_item_id,
      nullif(v_po_item ->> 'workBoqItemId', ''),
      nullif(v_po_item ->> 'materialBudgetItemId', ''),
      v_close_qty,
      greatest(0, v_received_qty - v_returned_qty),
      trim(p_reason),
      'active',
      p_actor_user_id,
      now()
    );

    v_total_closed_qty := v_total_closed_qty + v_close_qty;
  end loop;

  v_previous_guard := current_setting('app.material_transition_context', true);
  perform set_config('app.material_transition_context', 'on', true);

  update public.purchase_orders
  set closed_need_qty = coalesce(closed_need_qty, 0) + v_total_closed_qty,
      status = 'closed',
      last_action_by = p_actor_user_id::text,
      last_action_at = now(),
      updated_at = now()
  where id = p_purchase_order_id;

  perform set_config('app.material_transition_context', coalesce(v_previous_guard, ''), true);
exception
  when others then
    perform set_config('app.material_transition_context', coalesce(v_previous_guard, ''), true);
    raise;
end;
$$","revoke all on function app_private.close_purchase_package_short_v2(text, uuid, text, jsonb)
  from public, anon","grant execute on function app_private.close_purchase_package_short_v2(text, uuid, text, jsonb)
  to authenticated","create or replace function public.close_purchase_package_short_v2(
  p_purchase_order_id text,
  p_actor_user_id uuid default null,
  p_reason text default null,
  p_lines jsonb default '[]'::jsonb
) returns void
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_current_actor text := nullif(public.current_app_user_id()::text, '');
  v_actor uuid := coalesce(p_actor_user_id, v_current_actor::uuid);
begin
  if v_current_actor is null or v_actor::text <> v_current_actor then
    raise exception 'Nguoi thuc hien lenh khong hop le.' using errcode = '42501';
  end if;

  perform app_private.close_purchase_package_short_v2(
    p_purchase_order_id,
    v_actor,
    p_reason,
    p_lines
  );
end;
$$","revoke all on function public.close_purchase_package_short_v2(text, uuid, text, jsonb)
  from public, anon","grant execute on function public.close_purchase_package_short_v2(text, uuid, text, jsonb)
  to authenticated"}

{"alter table public.supplier_payable_documents
  drop constraint if exists supplier_payable_documents_source_type_check","alter table public.supplier_payable_documents
  add constraint supplier_payable_documents_source_type_check
  check (source_type in (
    'purchase_order',
    'purchase_delivery_receipt',
    'supplier_invoice_adjustment',
    'site_direct_purchase',
    'supplier_delivery_statement',
    'supplier_return_credit',
    'opening_balance',
    'manual_adjustment'
  ))","create table if not exists public.supplier_invoices (
  id uuid primary key default gen_random_uuid(),
  supplier_id text not null,
  supplier_name_snapshot text not null,
  invoice_number text not null,
  invoice_date date not null,
  net_amount numeric not null check (net_amount >= 0),
  vat_amount numeric not null check (vat_amount >= 0),
  gross_amount numeric not null check (gross_amount >= 0),
  variance_reason text,
  attachments jsonb not null default '[]'::jsonb,
  created_by uuid references public.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
)","create unique index if not exists uq_supplier_invoice_header_number
  on public.supplier_invoices(supplier_id, lower(trim(invoice_number)))","create table if not exists public.supplier_invoice_payable_links (
  invoice_id uuid not null references public.supplier_invoices(id) on delete cascade,
  payable_document_id uuid not null references public.supplier_payable_documents(id) on delete restrict,
  allocated_gross_amount numeric not null check (allocated_gross_amount > 0),
  created_at timestamptz not null default now(),
  primary key (invoice_id, payable_document_id)
)","create index if not exists idx_supplier_invoices_supplier_date_v2
  on public.supplier_invoices(supplier_id, invoice_date desc)","create index if not exists idx_supplier_invoice_links_payable_v2
  on public.supplier_invoice_payable_links(payable_document_id)","alter table public.supplier_invoices enable row level security","alter table public.supplier_invoice_payable_links enable row level security","drop policy if exists supplier_invoices_access_v2 on public.supplier_invoices","create policy supplier_invoices_access_v2
on public.supplier_invoices
for all to authenticated
using (
  exists (
    select 1
    from public.supplier_invoice_payable_links link
    join public.supplier_payable_documents ap
      on ap.id = link.payable_document_id
    where link.invoice_id = supplier_invoices.id
      and app_private.ap_scope_can_view(ap.project_id, ap.construction_site_id)
  )
)
with check (
  public.is_admin()
  or app_private.company_procurement_can_manage()
)","drop policy if exists supplier_invoice_links_access_v2 on public.supplier_invoice_payable_links","create policy supplier_invoice_links_access_v2
on public.supplier_invoice_payable_links
for all to authenticated
using (
  exists (
    select 1
    from public.supplier_payable_documents ap
    where ap.id = supplier_invoice_payable_links.payable_document_id
      and app_private.ap_scope_can_view(ap.project_id, ap.construction_site_id)
  )
)
with check (
  exists (
    select 1
    from public.supplier_payable_documents ap
    where ap.id = supplier_invoice_payable_links.payable_document_id
      and app_private.ap_scope_can_mutate(ap.project_id, ap.construction_site_id)
  )
)","drop trigger if exists trg_supplier_invoices_updated_at on public.supplier_invoices","create trigger trg_supplier_invoices_updated_at
before update on public.supplier_invoices
for each row execute function public.set_updated_at()","drop trigger if exists trg_audit_supplier_invoices on public.supplier_invoices","create trigger trg_audit_supplier_invoices
after insert or update or delete on public.supplier_invoices
for each row execute function app_private.audit_supplier_ap_change()","drop trigger if exists trg_audit_supplier_invoice_payable_links on public.supplier_invoice_payable_links","create trigger trg_audit_supplier_invoice_payable_links
after insert or update or delete on public.supplier_invoice_payable_links
for each row execute function app_private.audit_supplier_ap_change()","revoke all on table public.supplier_invoices from public, anon, authenticated","revoke all on table public.supplier_invoice_payable_links from public, anon, authenticated","grant select, insert, update on table public.supplier_invoices to authenticated","grant select, insert, update, delete on table public.supplier_invoice_payable_links to authenticated","create or replace function app_private.record_supplier_invoice_reconciliation_v2(
  p_invoice jsonb,
  p_links jsonb,
  p_actor_user_id uuid
) returns public.supplier_invoices
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_invoice public.supplier_invoices%rowtype;
  v_invoice_id uuid := coalesce(nullif(p_invoice ->> 'id', '')::uuid, gen_random_uuid());
  v_supplier_id text := nullif(trim(coalesce(p_invoice ->> 'supplierId', p_invoice ->> 'supplier_id')), '');
  v_supplier_name text := nullif(trim(coalesce(p_invoice ->> 'supplierNameSnapshot', p_invoice ->> 'supplier_name_snapshot')), '');
  v_invoice_number text := nullif(trim(coalesce(p_invoice ->> 'invoiceNumber', p_invoice ->> 'invoice_number')), '');
  v_invoice_date date := nullif(coalesce(p_invoice ->> 'invoiceDate', p_invoice ->> 'invoice_date'), '')::date;
  v_net_amount numeric(18,2) := round(coalesce(nullif(coalesce(p_invoice ->> 'netAmount', p_invoice ->> 'net_amount'), '')::numeric, 0), 2);
  v_vat_amount numeric(18,2) := round(coalesce(nullif(coalesce(p_invoice ->> 'vatAmount', p_invoice ->> 'vat_amount'), '')::numeric, 0), 2);
  v_gross_amount numeric(18,2) := round(coalesce(nullif(coalesce(p_invoice ->> 'grossAmount', p_invoice ->> 'gross_amount'), '')::numeric, 0), 2);
  v_variance_reason text := nullif(trim(coalesce(p_invoice ->> 'varianceReason', p_invoice ->> 'variance_reason', '')), '');
  v_attachments jsonb := coalesce(p_invoice -> 'attachments', '[]'::jsonb);
  v_link jsonb;
  v_payable_id uuid;
  v_allocated numeric(18,2);
  v_allocated_total numeric(18,2) := 0;
  v_estimated_total numeric(18,2) := 0;
  v_variance numeric(18,2);
  v_ap public.supplier_payable_documents%rowtype;
  v_project_id text := null;
  v_site_id text := null;
  v_project_finance_id text := null;
  v_adjustment_ref text;
  v_adjustment_id text;
begin
  if public.current_app_user_id() is null or p_actor_user_id <> public.current_app_user_id() then
    raise exception 'Nguoi thao tac khong hop le.' using errcode = '42501';
  end if;
  if v_supplier_id is null or v_supplier_name is null or v_invoice_number is null then
    raise exception 'Hoa don thieu NCC hoac so hoa don.' using errcode = '22023';
  end if;
  if v_gross_amount <= 0 or v_net_amount < 0 or v_vat_amount < 0 then
    raise exception 'Gia tri hoa don khong hop le.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_links, '[]'::jsonb)) <> 'array' or jsonb_array_length(p_links) = 0 then
    raise exception 'Hoa don phai link it nhat mot AP.' using errcode = '22023';
  end if;
  if jsonb_typeof(v_attachments) <> 'array' then
    raise exception 'Dinh kem hoa don phai la mang JSON.' using errcode = '22023';
  end if;

  for v_link in select value from jsonb_array_elements(p_links) as link(value)
  loop
    v_payable_id := nullif(coalesce(v_link ->> 'payableDocumentId', v_link ->> 'payable_document_id'), '')::uuid;
    v_allocated := round(coalesce(nullif(coalesce(v_link ->> 'allocatedGrossAmount', v_link ->> 'allocated_gross_amount'), '')::numeric, 0), 2);
    if v_payable_id is null or v_allocated <= 0 then
      raise exception 'Link AP hoa don khong hop le.' using errcode = '22023';
    end if;

    select * into v_ap
    from public.supplier_payable_documents
    where id = v_payable_id
    for update;
    if not found then
      raise exception 'Khong tim thay AP %.', v_payable_id using errcode = '22023';
    end if;
    if coalesce(v_ap.supplier_id, '') <> v_supplier_id then
      raise exception 'Tat ca AP duoc link phai cung nha cung cap voi hoa don.' using errcode = '22023';
    end if;
    if not app_private.ap_scope_can_mutate(v_ap.project_id, v_ap.construction_site_id) then
      raise exception 'Nguoi dung khong co quyen doi soat AP.' using errcode = '42501';
    end if;
    if v_project_id is null and v_site_id is null then
      v_project_id := v_ap.project_id;
      v_site_id := v_ap.construction_site_id;
    end if;

    v_allocated_total := round(v_allocated_total + v_allocated, 2);
    v_estimated_total := round(v_estimated_total + greatest(coalesce(v_ap.recognized_amount, 0) - coalesce(v_ap.credit_amount, 0), 0), 2);
  end loop;

  if v_allocated_total <> v_gross_amount then
    raise exception 'Tong phan bo AP phai bang tong tien hoa don.' using errcode = '22023';
  end if;

  v_variance := round(v_gross_amount - v_estimated_total, 2);
  if v_variance <> 0 and v_variance_reason is null then
    raise exception 'Hoa don lech AP phai co ly do chenh lech.' using errcode = '22023';
  end if;

  insert into public.supplier_invoices (
    id, supplier_id, supplier_name_snapshot, invoice_number, invoice_date,
    net_amount, vat_amount, gross_amount, variance_reason, attachments, created_by
  )
  values (
    v_invoice_id, v_supplier_id, v_supplier_name, v_invoice_number, v_invoice_date,
    v_net_amount, v_vat_amount, v_gross_amount, v_variance_reason, v_attachments, p_actor_user_id
  )
  returning * into v_invoice;

  for v_link in select value from jsonb_array_elements(p_links) as link(value)
  loop
    v_payable_id := nullif(coalesce(v_link ->> 'payableDocumentId', v_link ->> 'payable_document_id'), '')::uuid;
    v_allocated := round(coalesce(nullif(coalesce(v_link ->> 'allocatedGrossAmount', v_link ->> 'allocated_gross_amount'), '')::numeric, 0), 2);

    insert into public.supplier_invoice_payable_links (
      invoice_id, payable_document_id, allocated_gross_amount
    ) values (
      v_invoice_id, v_payable_id, v_allocated
    );

    update public.supplier_payable_documents
    set invoice_number = v_invoice_number,
        invoice_date = v_invoice_date,
        metadata = coalesce(metadata, '{}'::jsonb)
          || jsonb_build_object('supplierInvoiceId', v_invoice_id, 'supplierInvoiceNumber', v_invoice_number),
        updated_at = now()
    where id = v_payable_id;
  end loop;

  if v_variance <> 0 then
    select id into v_project_finance_id
    from public.project_finances
    where (v_project_id is not null and project_id = v_project_id)
       or (v_site_id is not null and construction_site_id = v_site_id)
    limit 1;

    v_adjustment_ref := 'supplier_invoice_adjustment:' || v_invoice_id::text;
    v_adjustment_id := 'supplier-invoice-adjustment-' || v_invoice_id::text;

    insert into public.project_transactions (
      id, \"projectFinanceId\", \"constructionSiteId\",
      project_id, project_finance_id, construction_site_id,
      type, category, amount, description, date, source,
      \"sourceRef\", source_ref, contract_cost_item_id,
      cost_classification_status, counterparty_partner_id,
      counterparty_name, attachments, \"createdBy\", \"createdAt\"
    )
    values (
      v_adjustment_id,
      coalesce(v_project_finance_id, ''),
      coalesce(v_site_id, ''),
      v_project_id,
      nullif(v_project_finance_id, ''),
      v_site_id,
      'expense',
      'materials',
      v_variance,
      'Chênh lệch hóa đơn NCC ' || v_invoice_number,
      v_invoice_date::text,
      'workflow',
      v_adjustment_ref,
      v_adjustment_ref,
      null,
      'auto',
      v_supplier_id,
      v_supplier_name,
      v_attachments,
      p_actor_user_id::text,
      now()
    )
    on conflict (source_ref) do nothing;

    insert into public.supplier_payable_documents (
      code, source_type, source_id, project_id, construction_site_id,
      supplier_id, supplier_name_snapshot, document_no, document_date, due_date,
      committed_amount, recognized_amount, credit_amount, status, qr_token,
      invoice_number, invoice_date, metadata, created_by
    )
    values (
      'AP-INV-ADJ-' || replace(v_invoice_id::text, '-', ''),
      'supplier_invoice_adjustment',
      v_invoice_id::text,
      v_project_id,
      v_site_id,
      v_supplier_id,
      v_supplier_name,
      v_invoice_number || '-ADJ',
      v_invoice_date,
      null,
      abs(v_variance),
      greatest(v_variance, 0),
      greatest(-v_variance, 0),
      case when v_variance > 0 then 'open' else 'paid' end,
      'ap_invoice_adj_' || replace(v_invoice_id::text, '-', ''),
      v_invoice_number,
      v_invoice_date,
      jsonb_build_object(
        'supplierInvoiceId', v_invoice_id,
        'supplierInvoiceNumber', v_invoice_number,
        'sourceRef', v_adjustment_ref,
        'varianceAmount', v_variance,
        'varianceReason', v_variance_reason
      ),
      p_actor_user_id
    )
    on conflict (source_type, source_id) do nothing;
  end if;

  if to_regclass('public.project_document_links') is not null then
    for v_link in select value from jsonb_array_elements(p_links) as link(value)
    loop
      v_payable_id := nullif(coalesce(v_link ->> 'payableDocumentId', v_link ->> 'payable_document_id'), '')::uuid;
      v_allocated := round(coalesce(nullif(coalesce(v_link ->> 'allocatedGrossAmount', v_link ->> 'allocated_gross_amount'), '')::numeric, 0), 2);
      insert into public.project_document_links (
        source_type, source_id, target_type, target_id, project_id, relation_type, status, metadata
      )
      values (
        'supplier_payable_document', v_payable_id::text,
        'supplier_invoice', v_invoice_id::text,
        v_project_id,
        'invoiced_by',
        'active',
        jsonb_build_object('allocatedGrossAmount', v_allocated)
      )
      on conflict (source_type, source_id, target_type, target_id, relation_type) do update
      set status = excluded.status,
          metadata = coalesce(public.project_document_links.metadata, '{}'::jsonb) || excluded.metadata,
          updated_at = now();
    end loop;

    if v_variance <> 0 then
      insert into public.project_document_links (
        source_type, source_id, target_type, target_id, project_id, relation_type, status, metadata
      )
      values (
        'supplier_invoice', v_invoice_id::text,
        'supplier_payable_document',
        (select id::text from public.supplier_payable_documents
         where source_type = 'supplier_invoice_adjustment' and source_id = v_invoice_id::text limit 1),
        v_project_id,
        'adjusts_ap',
        'active',
        jsonb_build_object('varianceAmount', v_variance)
      )
      on conflict (source_type, source_id, target_type, target_id, relation_type) do update
      set status = excluded.status,
          metadata = coalesce(public.project_document_links.metadata, '{}'::jsonb) || excluded.metadata,
          updated_at = now();

      insert into public.project_document_links (
        source_type, source_id, target_type, target_id, project_id, relation_type, status, metadata
      )
      values (
        'supplier_invoice', v_invoice_id::text,
        'project_transaction', v_adjustment_id,
        v_project_id,
        'adjusts_cost',
        'active',
        jsonb_build_object('varianceAmount', v_variance)
      )
      on conflict (source_type, source_id, target_type, target_id, relation_type) do update
      set status = excluded.status,
          metadata = coalesce(public.project_document_links.metadata, '{}'::jsonb) || excluded.metadata,
          updated_at = now();
    end if;
  end if;

  return v_invoice;
end;
$$","revoke all on function app_private.record_supplier_invoice_reconciliation_v2(jsonb, jsonb, uuid)
  from public, anon, authenticated","grant execute on function app_private.record_supplier_invoice_reconciliation_v2(jsonb, jsonb, uuid)
  to authenticated","create or replace function public.record_supplier_invoice_reconciliation_v2(
  p_invoice jsonb,
  p_links jsonb,
  p_actor_user_id uuid
) returns public.supplier_invoices
language plpgsql
security invoker
set search_path = ''
as $$
begin
  return app_private.record_supplier_invoice_reconciliation_v2(p_invoice, p_links, p_actor_user_id);
end;
$$","revoke all on function public.record_supplier_invoice_reconciliation_v2(jsonb, jsonb, uuid)
  from public, anon","grant execute on function public.record_supplier_invoice_reconciliation_v2(jsonb, jsonb, uuid)
  to authenticated"}

{"-- Request template draft/publish commands.
-- A request template owns one hidden shared-workflow template. Every publish
-- creates immutable request/workflow snapshots; runtime never reads draft rows.

alter table public.request_templates
  add column if not exists workflow_template_id uuid
  references public.workflow_templates(id) on delete set null","create index if not exists idx_request_templates_workflow_template
  on public.request_templates(workflow_template_id)
  where workflow_template_id is not null","create or replace function app_private.request_template_draft_payload(
  p_template_version_id uuid
)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'templateId', version.request_template_id,
    'name', template.name,
    'description', coalesce(template.description, ''),
    'formSchema', coalesce(version.form_schema, '[]'::jsonb),
    'usageScope', coalesce(version.usage_scope, '{}'::jsonb),
    'flowMode', version.flow_mode,
    'completionPolicy', version.completion_policy,
    'requestSlaHours', version.request_sla_hours,
    'blocks', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'key', block.block_key,
          'name', block.name,
          'source', block.approver_source,
          'fixedUserIds', to_jsonb(block.fixed_user_ids),
          'minimumDynamicApprovers', block.minimum_dynamic_approvers,
          'slaHours', block.sla_hours,
          'sortOrder', block.sort_order
        ) order by block.sort_order, block.block_key
      )
      from public.request_approval_blocks block
      where block.request_template_version_id = version.id
    ), '[]'::jsonb),
    'watcherUserIds', coalesce((
      select jsonb_agg(watcher.user_id order by watcher.user_id)
      from public.request_template_watchers watcher
      where watcher.request_template_version_id = version.id
    ), '[]'::jsonb),
    'printConfig', coalesce(version.print_config, '{}'::jsonb),
    'notificationConfig', coalesce(version.notification_config, '{}'::jsonb)
  )
  from public.request_template_versions version
  join public.request_templates template
    on template.id = version.request_template_id
  where version.id = p_template_version_id
    and (
      app_private.request_user_can_manage(public.current_app_user_id())
      or app_private.request_template_version_can_select(
        version.id, public.current_app_user_id()
      )
    );
$$","create or replace function app_private.request_template_summary(
  p_template_id uuid
)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'id', template.id,
    'name', template.name,
    'status', template.lifecycle_status,
    'publishedVersionNumber', (
      select version.version_number
      from public.request_template_versions version
      where version.id = template.current_version_id
    ),
    'usageScopeLabel', case
      when coalesce((current_version.usage_scope ->> 'companyWide')::boolean, false)
        then 'Toàn công ty'
      when jsonb_array_length(coalesce(current_version.usage_scope -> 'userIds', '[]'::jsonb)) > 0
        then 'Người dùng cụ thể'
      when jsonb_array_length(coalesce(current_version.usage_scope -> 'orgUnitIds', '[]'::jsonb)) > 0
        then 'Đơn vị/phòng ban'
      when jsonb_array_length(coalesce(current_version.usage_scope -> 'permissionCodes', '[]'::jsonb)) > 0
        then 'Nhóm quyền'
      else 'Chưa giới hạn'
    end,
    'updatedAt', template.updated_at
  )
  from public.request_templates template
  left join public.request_template_versions current_version
    on current_version.id = template.current_version_id
  where template.id = p_template_id
    and (
      app_private.request_user_can_manage(public.current_app_user_id())
      or app_private.request_template_can_select(
        template.id, public.current_app_user_id()
      )
    );
$$","create or replace function app_private.save_request_template_draft(
  p_payload jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := public.current_app_user_id();
  v_template public.request_templates%rowtype;
  v_version public.request_template_versions%rowtype;
  v_template_id uuid;
  v_version_number integer;
  v_block jsonb;
  v_fixed_ids uuid[];
  v_expected_updated_at timestamptz;
  v_name text := nullif(trim(p_payload ->> 'name'), '');
  v_form_schema jsonb := coalesce(p_payload -> 'formSchema', '[]'::jsonb);
  v_usage_scope jsonb := coalesce(p_payload -> 'usageScope', '{}'::jsonb);
  v_blocks jsonb := coalesce(p_payload -> 'blocks', '[]'::jsonb);
  v_watcher_ids jsonb := coalesce(p_payload -> 'watcherUserIds', '[]'::jsonb);
begin
  if v_actor is null or not app_private.request_user_can_manage(v_actor) then
    raise exception using errcode = '42501', message = 'REQUEST_TEMPLATE_FORBIDDEN';
  end if;
  if v_name is null then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_NAME_REQUIRED';
  end if;
  if jsonb_typeof(v_form_schema) <> 'array'
     or jsonb_typeof(v_usage_scope) <> 'object'
     or jsonb_typeof(v_blocks) <> 'array'
     or jsonb_typeof(v_watcher_ids) <> 'array' then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_PAYLOAD_INVALID';
  end if;
  if coalesce(p_payload ->> 'flowMode', 'SEQUENTIAL') not in ('SEQUENTIAL', 'PARALLEL')
     or coalesce(p_payload ->> 'completionPolicy', 'ALL') not in ('ALL', 'ANY_ONE') then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_POLICY_INVALID';
  end if;
  if jsonb_array_length(v_blocks) = 0 then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_BLOCK_REQUIRED';
  end if;
  if coalesce(v_usage_scope ->> 'companyWide', 'false') not in ('true', 'false')
     or jsonb_typeof(coalesce(v_usage_scope -> 'orgUnitIds', '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(v_usage_scope -> 'permissionCodes', '[]'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(v_usage_scope -> 'userIds', '[]'::jsonb)) <> 'array' then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_SCOPE_INVALID';
  end if;
  if p_payload ? 'requestSlaHours'
     and nullif(p_payload ->> 'requestSlaHours', '')::numeric < 0 then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_SLA_INVALID';
  end if;

  v_template_id := nullif(p_payload ->> 'templateId', '')::uuid;
  v_expected_updated_at := nullif(p_payload ->> 'expectedUpdatedAt', '')::timestamptz;

  if v_template_id is null then
    insert into public.request_templates(name, description, created_by)
    values (v_name, coalesce(p_payload ->> 'description', ''), v_actor)
    returning * into v_template;
  else
    select * into v_template
    from public.request_templates
    where id = v_template_id
    for update;
    if not found then
      raise exception using errcode = 'P0002', message = 'REQUEST_TEMPLATE_NOT_FOUND';
    end if;
    if v_expected_updated_at is not null
       and v_template.updated_at <> v_expected_updated_at then
      raise exception using errcode = '40001', message = 'CONFLICT';
    end if;
    if v_template.lifecycle_status = 'DEACTIVATED' then
      raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_DEACTIVATED';
    end if;
    update public.request_templates
    set name = v_name,
        description = coalesce(p_payload ->> 'description', ''),
        lifecycle_status = 'DRAFT'
    where id = v_template.id
    returning * into v_template;
  end if;

  select * into v_version
  from public.request_template_versions
  where request_template_id = v_template.id
    and status = 'DRAFT'
  order by version_number desc
  limit 1
  for update;

  if not found then
    select coalesce(max(version_number), 0) + 1
      into v_version_number
    from public.request_template_versions
    where request_template_id = v_template.id;
    insert into public.request_template_versions(
      request_template_id, version_number, form_schema, usage_scope,
      flow_mode, completion_policy, request_sla_hours, print_config,
      notification_config, status, created_by
    ) values (
      v_template.id, v_version_number, v_form_schema, v_usage_scope,
      coalesce(p_payload ->> 'flowMode', 'SEQUENTIAL'),
      coalesce(p_payload ->> 'completionPolicy', 'ALL'),
      nullif(p_payload ->> 'requestSlaHours', '')::numeric,
      coalesce(p_payload -> 'printConfig', '{}'::jsonb),
      coalesce(p_payload -> 'notificationConfig', '{}'::jsonb),
      'DRAFT', v_actor
    ) returning * into v_version;
  else
    update public.request_template_versions
    set form_schema = v_form_schema,
        usage_scope = v_usage_scope,
        flow_mode = coalesce(p_payload ->> 'flowMode', 'SEQUENTIAL'),
        completion_policy = coalesce(p_payload ->> 'completionPolicy', 'ALL'),
        request_sla_hours = nullif(p_payload ->> 'requestSlaHours', '')::numeric,
        print_config = coalesce(p_payload -> 'printConfig', '{}'::jsonb),
        notification_config = coalesce(p_payload -> 'notificationConfig', '{}'::jsonb),
        created_by = v_actor
    where id = v_version.id
    returning * into v_version;
    delete from public.request_approval_blocks
    where request_template_version_id = v_version.id;
    delete from public.request_template_watchers
    where request_template_version_id = v_version.id;
  end if;

  for v_block in select value from jsonb_array_elements(v_blocks)
  loop
    if nullif(trim(v_block ->> 'key'), '') is null
       or nullif(trim(v_block ->> 'name'), '') is null
       or coalesce(v_block ->> 'source', '') not in (
         'FIXED_SINGLE', 'FIXED_MULTI', 'DIRECT_MANAGER', 'DYNAMIC_CREATOR_SELECT'
       ) then
      raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_BLOCK_INVALID';
    end if;
    select coalesce(array_agg(value::uuid), '{}'::uuid[])
      into v_fixed_ids
    from jsonb_array_elements_text(coalesce(v_block -> 'fixedUserIds', '[]'::jsonb));
    if coalesce(v_block ->> 'source', '') in ('FIXED_SINGLE', 'FIXED_MULTI')
       and cardinality(v_fixed_ids) = 0 then
      raise exception using errcode = '22023', message = 'REQUEST_APPROVER_REQUIRED';
    end if;
    if exists (
      select 1
      from unnest(v_fixed_ids) id
      left join public.users app_user on app_user.id = id
      where app_user.id is null
         or not coalesce(app_user.is_active, true)
         or coalesce(app_user.account_status, 'ACTIVE') <> 'ACTIVE'
       ) then
      raise exception using errcode = '22023', message = 'REQUEST_APPROVER_INACTIVE';
    end if;
    if coalesce((v_block ->> 'sortOrder')::integer, 0) < 0
       or nullif(v_block ->> 'slaHours', '')::numeric < 0
       or nullif(v_block ->> 'minimumDynamicApprovers', '')::integer < 1 then
      raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_BLOCK_INVALID';
    end if;
    insert into public.request_approval_blocks(
      request_template_version_id, block_key, name, sort_order,
      approver_source, fixed_user_ids, minimum_dynamic_approvers, sla_hours
    ) values (
      v_version.id,
      trim(v_block ->> 'key'),
      trim(v_block ->> 'name'),
      coalesce((v_block ->> 'sortOrder')::integer, 0),
      v_block ->> 'source',
      v_fixed_ids,
      nullif(v_block ->> 'minimumDynamicApprovers', '')::integer,
      nullif(v_block ->> 'slaHours', '')::numeric
    );
  end loop;

  insert into public.request_template_watchers(request_template_version_id, user_id)
  select v_version.id, value::uuid
  from jsonb_array_elements_text(v_watcher_ids)
  on conflict do nothing;

  update public.request_templates
  set current_version_id = null,
      lifecycle_status = 'DRAFT'
  where id = v_template.id
    and current_version_id = v_version.id;
  select * into v_template
  from public.request_templates
  where id = v_template.id;

  return jsonb_build_object(
    'id', v_version.request_template_id,
    'status', v_version.status,
    'versionNumber', v_version.version_number,
    'updatedAt', v_template.updated_at,
    'payload', app_private.request_template_draft_payload(v_version.id)
  );
end;
$$","create or replace function app_private.publish_request_template_version(
  p_request_template_id uuid,
  p_expected_updated_at timestamptz
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := public.current_app_user_id();
  v_template public.request_templates%rowtype;
  v_draft public.request_template_versions%rowtype;
  v_old_version public.request_template_versions%rowtype;
  v_workflow_template_id uuid;
  v_workflow_version_id uuid;
  v_start_node_id uuid := gen_random_uuid();
  v_end_node_id uuid := gen_random_uuid();
  v_node_id uuid;
  v_next_node_id uuid;
  v_block record;
  v_block_ids uuid[] := '{}'::uuid[];
  v_number integer;
  v_snapshot jsonb;
  v_docx_path text;
begin
  if v_actor is null or not app_private.request_user_can_manage(v_actor) then
    raise exception using errcode = '42501', message = 'REQUEST_TEMPLATE_FORBIDDEN';
  end if;
  if p_expected_updated_at is null then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_EXPECTED_UPDATED_AT_REQUIRED';
  end if;
  select * into v_template
  from public.request_templates
  where id = p_request_template_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'REQUEST_TEMPLATE_NOT_FOUND';
  end if;
  if v_template.updated_at <> p_expected_updated_at then
    raise exception using errcode = '40001', message = 'CONFLICT';
  end if;
  select * into v_draft
  from public.request_template_versions
  where request_template_id = v_template.id
    and status = 'DRAFT'
  order by version_number desc
  limit 1
  for update;
  if not found then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_DRAFT_REQUIRED';
  end if;
  if jsonb_typeof(v_draft.form_schema) <> 'array'
     or jsonb_array_length(v_draft.form_schema) = 0
     or not exists (
       select 1 from public.request_approval_blocks block
       where block.request_template_version_id = v_draft.id
     ) then
    raise exception using errcode = '22023', message = 'REQUEST_FORM_SCHEMA_INVALID';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(v_draft.form_schema) field
    where jsonb_typeof(field) <> 'object'
       or nullif(trim(field ->> 'key'), '') is null
       or nullif(trim(field ->> 'label'), '') is null
       or coalesce(field ->> 'fieldType', '') not in (
         'text', 'textarea', 'number', 'date', 'select', 'user', 'file'
       )
  ) or exists (
    select field ->> 'key'
    from jsonb_array_elements(v_draft.form_schema) field
    group by field ->> 'key'
    having count(*) > 1
  ) then
    raise exception using errcode = '22023', message = 'REQUEST_FORM_SCHEMA_INVALID';
  end if;
  if exists (
    select 1
    from public.request_approval_blocks block
    left join public.users app_user
      on app_user.id = any(block.fixed_user_ids)
    where block.request_template_version_id = v_draft.id
      and block.approver_source in ('FIXED_SINGLE', 'FIXED_MULTI')
      and (
        cardinality(block.fixed_user_ids) = 0
        or exists (
          select 1
          from unnest(block.fixed_user_ids) fixed_id
          left join public.users fixed_user on fixed_user.id = fixed_id
          where fixed_user.id is null
             or not coalesce(fixed_user.is_active, true)
             or coalesce(fixed_user.account_status, 'ACTIVE') <> 'ACTIVE'
        )
      )
  ) then
    raise exception using errcode = '22023', message = 'REQUEST_APPROVER_INACTIVE';
  end if;

  v_docx_path := v_draft.print_config ->> 'docxStoragePath';
  if v_docx_path is not null and v_docx_path <> '' then
    if not exists (
      select 1
      from public.request_print_templates print_template
      where print_template.request_template_version_id = v_draft.id
        and print_template.storage_path = v_docx_path
        and print_template.validation_status = 'VALID'
    ) then
      raise exception using errcode = '22023', message = 'REQUEST_PRINT_TEMPLATE_INVALID';
    end if;
    if exists (
      select 1
      from public.request_print_templates print_template
      cross join lateral jsonb_object_keys(
        case
          when jsonb_typeof(print_template.placeholder_schema) = 'object'
            then print_template.placeholder_schema
          else '{}'::jsonb
        end
      ) placeholder_key
      where print_template.request_template_version_id = v_draft.id
        and print_template.storage_path = v_docx_path
        and print_template.validation_status = 'VALID'
        and placeholder_key not in (
          select field ->> 'key'
          from jsonb_array_elements(v_draft.form_schema) field
          union all
          select value from jsonb_array_elements_text(
            '[\"title\",\"description\",\"requestCode\",\"createdAt\",\"createdBy\"]'::jsonb
          )
        )
    ) then
      raise exception using errcode = '22023', message = 'REQUEST_PRINT_PLACEHOLDER_UNKNOWN';
    end if;
    if exists (
      select 1
      from public.request_print_templates print_template
      where print_template.request_template_version_id = v_draft.id
        and print_template.storage_path = v_docx_path
        and jsonb_typeof(print_template.placeholder_schema) <> 'object'
    ) then
      raise exception using errcode = '22023', message = 'REQUEST_PRINT_PLACEHOLDER_INVALID';
    end if;
  end if;

  -- Every publish receives a fresh hidden workflow graph. Keeping old graphs
  -- intact makes workflow snapshots immutable and prevents stale nodes from
  -- leaking into a later request submission.
  v_workflow_template_id := gen_random_uuid();
  insert into public.workflow_templates(
    id, name, description, created_by, is_active, custom_fields,
    managers, default_watchers
  ) values (
    v_workflow_template_id,
    '[Request] ' || v_template.name,
    coalesce(v_template.description, ''),
    v_actor,
    true,
    jsonb_build_array(jsonb_build_object('_requestTemplateId', v_template.id)),
    '{}'::text[],
    '{}'::text[]
  );
  update public.request_templates
  set workflow_template_id = v_workflow_template_id
  where id = v_template.id;

  insert into public.workflow_nodes(id, template_id, type, label, config, position_x, position_y)
  values (
    v_start_node_id, v_workflow_template_id, 'START'::public.workflow_node_type,
    'Bắt đầu đề xuất', jsonb_build_object('executionPolicy', 'AUTO_ADVANCE_APPROVAL'), 0, 0
  );

  for v_block in
    select *
    from public.request_approval_blocks
    where request_template_version_id = v_draft.id
    order by sort_order, block_key
  loop
    v_node_id := gen_random_uuid();
    v_block_ids := array_append(v_block_ids, v_node_id);
    insert into public.workflow_nodes(
      id, template_id, type, label, config, position_x, position_y
    ) values (
      v_node_id,
      v_workflow_template_id,
      'APPROVAL'::public.workflow_node_type,
      v_block.name,
      jsonb_build_object(
        'executionPolicy', 'AUTO_ADVANCE_APPROVAL',
        'requestBlockKey', v_block.block_key,
        'approverSource', v_block.approver_source,
        'fixedUserIds', to_jsonb(v_block.fixed_user_ids),
        'minimumDynamicApprovers', v_block.minimum_dynamic_approvers,
        'flowMode', v_draft.flow_mode,
        'completionPolicy', v_draft.completion_policy,
        'slaHours', v_block.sla_hours
      ),
      v_block.sort_order * 240 + 180,
      v_block.sort_order * 120
    );
  end loop;

  insert into public.workflow_nodes(id, template_id, type, label, config, position_x, position_y)
  values (
    v_end_node_id, v_workflow_template_id, 'END'::public.workflow_node_type,
    'Hoàn thành đề xuất', jsonb_build_object('executionPolicy', 'AUTO_ADVANCE_APPROVAL'),
    (coalesce(array_length(v_block_ids, 1), 0) + 1) * 240, 0
  );

  if v_draft.flow_mode = 'PARALLEL' then
    for v_number in 1..coalesce(array_length(v_block_ids, 1), 0) loop
      insert into public.workflow_edges(template_id, source_node_id, target_node_id, label)
      values (v_workflow_template_id, v_start_node_id, v_block_ids[v_number], 'Bước duyệt');
      insert into public.workflow_edges(template_id, source_node_id, target_node_id, label)
      values (v_workflow_template_id, v_block_ids[v_number], v_end_node_id, 'Hoàn tất');
    end loop;
  else
    v_next_node_id := v_start_node_id;
    for v_number in 1..coalesce(array_length(v_block_ids, 1), 0) loop
      insert into public.workflow_edges(template_id, source_node_id, target_node_id, label)
      values (v_workflow_template_id, v_next_node_id, v_block_ids[v_number], 'Bước kế tiếp');
      v_next_node_id := v_block_ids[v_number];
    end loop;
    insert into public.workflow_edges(template_id, source_node_id, target_node_id, label)
    values (v_workflow_template_id, v_next_node_id, v_end_node_id, 'Hoàn tất');
  end if;

  select coalesce(max(version_number), 0) + 1
    into v_number
  from public.workflow_template_versions
  where template_id = v_workflow_template_id;
  v_snapshot := jsonb_build_object(
    'template', (select to_jsonb(template) from public.workflow_templates template where template.id = v_workflow_template_id),
    'nodes', coalesce((
      select jsonb_agg(to_jsonb(node) order by node.position_y, node.position_x, node.id)
      from public.workflow_nodes node
      where node.template_id = v_workflow_template_id
    ), '[]'::jsonb),
    'edges', coalesce((
      select jsonb_agg(to_jsonb(edge) order by edge.id)
      from public.workflow_edges edge
      where edge.template_id = v_workflow_template_id
    ), '[]'::jsonb)
  );
  insert into public.workflow_template_versions(
    template_id, version_number, name, description, custom_fields,
    managers, default_watchers, snapshot, created_by
  )
  select workflow_template.id, v_number, workflow_template.name,
    workflow_template.description, workflow_template.custom_fields,
    workflow_template.managers, workflow_template.default_watchers,
    v_snapshot, v_actor
  from public.workflow_templates workflow_template
  where workflow_template.id = v_workflow_template_id
  returning id into v_workflow_version_id;

  select * into v_old_version
  from public.request_template_versions
  where request_template_id = v_template.id
    and status = 'PUBLISHED'
  order by version_number desc
  limit 1
  for update;
  if found then
    update public.request_template_versions
    set status = 'SUPERSEDED'
    where id = v_old_version.id;
  end if;
  update public.request_template_versions
  set status = 'PUBLISHED',
      workflow_template_version_id = v_workflow_version_id,
      published_by = v_actor,
      published_at = now()
  where id = v_draft.id;
  update public.request_templates
  set lifecycle_status = 'PUBLISHED', current_version_id = v_draft.id
  where id = v_template.id;

  return jsonb_build_object(
    'requestTemplateId', v_template.id,
    'requestTemplateVersionId', v_draft.id,
    'versionNumber', v_draft.version_number,
    'workflowTemplateId', v_workflow_template_id,
    'workflowTemplateVersionId', v_workflow_version_id
  );
end;
