{"-- Public request-template RPCs are SECURITY INVOKER wrappers and call this
-- private guard, so authenticated users need execute access to the guard.
grant execute on function app_private.request_user_can_manage(uuid) to authenticated"}

{"-- Business-level optimistic concurrency conflicts must not use SQLSTATE 40001.
-- PostgREST maps class 40 errors to HTTP 500, which can trigger aggressive
-- retry behavior. Keep the private implementation intact and translate the
-- exposed RPC boundary to an explicit HTTP 409.

create or replace function public.save_request_template_draft(p_payload jsonb)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_saved jsonb;
  v_draft_version_id uuid;
begin
  if nullif(p_payload ->> 'templateId', '') is not null
     and nullif(p_payload ->> 'expectedUpdatedAt', '') is null then
    raise exception using
      errcode = '22023',
      message = 'REQUEST_TEMPLATE_EXPECTED_UPDATED_AT_REQUIRED';
  end if;

  v_saved := app_private.save_request_template_draft(p_payload);

  select version.id into v_draft_version_id
  from public.request_template_versions version
  where version.request_template_id = (v_saved ->> 'id')::uuid
    and version.status = 'DRAFT'
  order by version.version_number desc
  limit 1;

  return v_saved || jsonb_build_object('draftVersionId', v_draft_version_id);
exception
  when serialization_failure then
    raise sqlstate 'PT409' using message = 'CONFLICT';
end;
$$","create or replace function public.publish_request_template_version(
  p_request_template_id uuid,
  p_expected_updated_at timestamptz
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
begin
  return app_private.publish_request_template_version(
    p_request_template_id,
    p_expected_updated_at
  );
exception
  when serialization_failure then
    raise sqlstate 'PT409' using message = 'CONFLICT';
end;
$$","create or replace function public.deactivate_request_template(
  p_request_template_id uuid,
  p_expected_updated_at timestamptz
)
returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
begin
  return app_private.deactivate_request_template(
    p_request_template_id,
    p_expected_updated_at
  );
exception
  when serialization_failure then
    raise sqlstate 'PT409' using message = 'CONFLICT';
end;
$$"}

{"-- Keep request-template publish validation aligned with the editor schema.
-- In particular, table fields are first-class request fields.
create or replace function app_private.publish_request_template_version(
  p_request_template_id uuid,
  p_expected_updated_at timestamptz
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := public.current_app_user_id();
  v_template public.request_templates%rowtype;
  v_draft public.request_template_versions%rowtype;
  v_old_version public.request_template_versions%rowtype;
  v_workflow_template_id uuid;
  v_workflow_version_id uuid;
  v_start_node_id uuid := gen_random_uuid();
  v_end_node_id uuid := gen_random_uuid();
  v_node_id uuid;
  v_next_node_id uuid;
  v_block record;
  v_block_ids uuid[] := '{}'::uuid[];
  v_number integer;
  v_snapshot jsonb;
  v_docx_path text;
begin
  if v_actor is null or not app_private.request_user_can_manage(v_actor) then
    raise exception using errcode = '42501', message = 'REQUEST_TEMPLATE_FORBIDDEN';
  end if;
  if p_expected_updated_at is null then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_EXPECTED_UPDATED_AT_REQUIRED';
  end if;
  select * into v_template
  from public.request_templates
  where id = p_request_template_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'REQUEST_TEMPLATE_NOT_FOUND';
  end if;
  if v_template.updated_at <> p_expected_updated_at then
    raise exception using errcode = '40001', message = 'CONFLICT';
  end if;
  select * into v_draft
  from public.request_template_versions
  where request_template_id = v_template.id
    and status = 'DRAFT'
  order by version_number desc
  limit 1
  for update;
  if not found then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_DRAFT_REQUIRED';
  end if;
  if jsonb_typeof(v_draft.form_schema) <> 'array'
     or jsonb_array_length(v_draft.form_schema) = 0
     or not exists (
       select 1 from public.request_approval_blocks block
       where block.request_template_version_id = v_draft.id
     ) then
    raise exception using errcode = '22023', message = 'REQUEST_FORM_SCHEMA_INVALID';
  end if;
  if exists (
    select 1
    from jsonb_array_elements(v_draft.form_schema) field
    where jsonb_typeof(field) <> 'object'
       or nullif(trim(field ->> 'key'), '') is null
       or nullif(trim(field ->> 'label'), '') is null
       or coalesce(field ->> 'fieldType', '') not in (
         'text', 'textarea', 'number', 'date', 'select', 'table', 'user', 'file'
       )
  ) or exists (
    select field ->> 'key'
    from jsonb_array_elements(v_draft.form_schema) field
    group by field ->> 'key'
    having count(*) > 1
  ) then
    raise exception using errcode = '22023', message = 'REQUEST_FORM_SCHEMA_INVALID';
  end if;
  if exists (
    select 1
    from public.request_approval_blocks block
    left join public.users app_user
      on app_user.id = any(block.fixed_user_ids)
    where block.request_template_version_id = v_draft.id
      and block.approver_source in ('FIXED_SINGLE', 'FIXED_MULTI')
      and (
        cardinality(block.fixed_user_ids) = 0
        or exists (
          select 1
          from unnest(block.fixed_user_ids) fixed_id
          left join public.users fixed_user on fixed_user.id = fixed_id
          where fixed_user.id is null
             or not coalesce(fixed_user.is_active, true)
             or coalesce(fixed_user.account_status, 'ACTIVE') <> 'ACTIVE'
        )
      )
  ) then
    raise exception using errcode = '22023', message = 'REQUEST_APPROVER_INACTIVE';
  end if;

  v_docx_path := v_draft.print_config ->> 'docxStoragePath';
  if v_docx_path is not null and v_docx_path <> '' then
    if not exists (
      select 1
      from public.request_print_templates print_template
      where print_template.request_template_version_id = v_draft.id
        and print_template.storage_path = v_docx_path
        and print_template.validation_status = 'VALID'
    ) then
      raise exception using errcode = '22023', message = 'REQUEST_PRINT_TEMPLATE_INVALID';
    end if;
    if exists (
      select 1
      from public.request_print_templates print_template
      cross join lateral jsonb_object_keys(
        case
          when jsonb_typeof(print_template.placeholder_schema) = 'object'
            then print_template.placeholder_schema
          else '{}'::jsonb
        end
      ) placeholder_key
      where print_template.request_template_version_id = v_draft.id
        and print_template.storage_path = v_docx_path
        and print_template.validation_status = 'VALID'
        and placeholder_key not in (
          select field ->> 'key'
          from jsonb_array_elements(v_draft.form_schema) field
          union all
          select value from jsonb_array_elements_text(
            '[\"title\",\"description\",\"requestCode\",\"createdAt\",\"createdBy\"]'::jsonb
          )
        )
    ) then
      raise exception using errcode = '22023', message = 'REQUEST_PRINT_PLACEHOLDER_UNKNOWN';
    end if;
    if exists (
      select 1
      from public.request_print_templates print_template
      where print_template.request_template_version_id = v_draft.id
        and print_template.storage_path = v_docx_path
        and jsonb_typeof(print_template.placeholder_schema) <> 'object'
    ) then
      raise exception using errcode = '22023', message = 'REQUEST_PRINT_PLACEHOLDER_INVALID';
    end if;
  end if;

  v_workflow_template_id := gen_random_uuid();
  insert into public.workflow_templates(
    id, name, description, created_by, is_active, custom_fields,
    managers, default_watchers
  ) values (
    v_workflow_template_id,
    '[Request] ' || v_template.name,
    coalesce(v_template.description, ''),
    v_actor,
    true,
    jsonb_build_array(jsonb_build_object('_requestTemplateId', v_template.id)),
    '{}'::text[],
    '{}'::text[]
  );
  update public.request_templates
  set workflow_template_id = v_workflow_template_id
  where id = v_template.id;

  insert into public.workflow_nodes(id, template_id, type, label, config, position_x, position_y)
  values (
    v_start_node_id, v_workflow_template_id, 'START'::public.workflow_node_type,
    'Bắt đầu đề xuất', jsonb_build_object('executionPolicy', 'AUTO_ADVANCE_APPROVAL'), 0, 0
  );

  for v_block in
    select *
    from public.request_approval_blocks
    where request_template_version_id = v_draft.id
    order by sort_order, block_key
  loop
    v_node_id := gen_random_uuid();
    v_block_ids := array_append(v_block_ids, v_node_id);
    insert into public.workflow_nodes(
      id, template_id, type, label, config, position_x, position_y
    ) values (
      v_node_id,
      v_workflow_template_id,
      'APPROVAL'::public.workflow_node_type,
      v_block.name,
      jsonb_build_object(
        'executionPolicy', 'AUTO_ADVANCE_APPROVAL',
        'requestBlockKey', v_block.block_key,
        'approverSource', v_block.approver_source,
        'fixedUserIds', to_jsonb(v_block.fixed_user_ids),
        'minimumDynamicApprovers', v_block.minimum_dynamic_approvers,
        'flowMode', v_draft.flow_mode,
        'completionPolicy', v_draft.completion_policy,
        'slaHours', v_block.sla_hours
      ),
      v_block.sort_order * 240 + 180,
      v_block.sort_order * 120
    );
  end loop;

  insert into public.workflow_nodes(id, template_id, type, label, config, position_x, position_y)
  values (
    v_end_node_id, v_workflow_template_id, 'END'::public.workflow_node_type,
    'Hoàn thành đề xuất', jsonb_build_object('executionPolicy', 'AUTO_ADVANCE_APPROVAL'),
    (coalesce(array_length(v_block_ids, 1), 0) + 1) * 240, 0
  );

  if v_draft.flow_mode = 'PARALLEL' then
    for v_number in 1..coalesce(array_length(v_block_ids, 1), 0) loop
      insert into public.workflow_edges(template_id, source_node_id, target_node_id, label)
      values (v_workflow_template_id, v_start_node_id, v_block_ids[v_number], 'Bước duyệt');
      insert into public.workflow_edges(template_id, source_node_id, target_node_id, label)
      values (v_workflow_template_id, v_block_ids[v_number], v_end_node_id, 'Hoàn tất');
    end loop;
  else
    v_next_node_id := v_start_node_id;
    for v_number in 1..coalesce(array_length(v_block_ids, 1), 0) loop
      insert into public.workflow_edges(template_id, source_node_id, target_node_id, label)
      values (v_workflow_template_id, v_next_node_id, v_block_ids[v_number], 'Bước kế tiếp');
      v_next_node_id := v_block_ids[v_number];
    end loop;
    insert into public.workflow_edges(template_id, source_node_id, target_node_id, label)
    values (v_workflow_template_id, v_next_node_id, v_end_node_id, 'Hoàn tất');
  end if;

  select coalesce(max(version_number), 0) + 1
    into v_number
  from public.workflow_template_versions
  where template_id = v_workflow_template_id;
  v_snapshot := jsonb_build_object(
    'template', (select to_jsonb(template) from public.workflow_templates template where template.id = v_workflow_template_id),
    'nodes', coalesce((
      select jsonb_agg(to_jsonb(node) order by node.position_y, node.position_x, node.id)
      from public.workflow_nodes node
      where node.template_id = v_workflow_template_id
    ), '[]'::jsonb),
    'edges', coalesce((
      select jsonb_agg(to_jsonb(edge) order by edge.id)
      from public.workflow_edges edge
      where edge.template_id = v_workflow_template_id
    ), '[]'::jsonb)
  );
  insert into public.workflow_template_versions(
    template_id, version_number, name, description, custom_fields,
    managers, default_watchers, snapshot, created_by
  )
  select workflow_template.id, v_number, workflow_template.name,
    workflow_template.description, workflow_template.custom_fields,
    workflow_template.managers, workflow_template.default_watchers,
    v_snapshot, v_actor
  from public.workflow_templates workflow_template
  where workflow_template.id = v_workflow_template_id
  returning id into v_workflow_version_id;

  select * into v_old_version
  from public.request_template_versions
  where request_template_id = v_template.id
    and status = 'PUBLISHED'
  order by version_number desc
  limit 1
  for update;
  if found then
    update public.request_template_versions
    set status = 'SUPERSEDED'
    where id = v_old_version.id;
  end if;
  update public.request_template_versions
  set status = 'PUBLISHED',
      workflow_template_version_id = v_workflow_version_id,
      published_by = v_actor,
      published_at = now()
  where id = v_draft.id;
  update public.request_templates
  set lifecycle_status = 'PUBLISHED', current_version_id = v_draft.id
  where id = v_template.id;

  return jsonb_build_object(
    'requestTemplateId', v_template.id,
    'requestTemplateVersionId', v_draft.id,
    'versionNumber', v_draft.version_number,
    'workflowTemplateId', v_workflow_template_id,
    'workflowTemplateVersionId', v_workflow_version_id
  );
end;
$$","-- Preparing a new version of an existing template must also preserve a
-- validated DOCX registration. The binary remains at its immutable path.
create or replace function app_private.create_request_template_draft_from_published(
  p_request_template_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := public.current_app_user_id();
  v_template public.request_templates%rowtype;
  v_published public.request_template_versions%rowtype;
  v_draft public.request_template_versions%rowtype;
  v_number integer;
begin
  if v_actor is null or not app_private.request_user_can_manage(v_actor) then
    raise exception using errcode = '42501', message = 'REQUEST_TEMPLATE_FORBIDDEN';
  end if;

  select * into v_template
  from public.request_templates
  where id = p_request_template_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'REQUEST_TEMPLATE_NOT_FOUND';
  end if;

  select * into v_published
  from public.request_template_versions
  where request_template_id = v_template.id
    and status = 'PUBLISHED'
  order by version_number desc
  limit 1;
  if not found then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_PUBLISHED_REQUIRED';
  end if;

  select coalesce(max(version_number), 0) + 1 into v_number
  from public.request_template_versions
  where request_template_id = v_template.id;

  insert into public.request_template_versions(
    request_template_id, version_number, form_schema, usage_scope, flow_mode,
    completion_policy, request_sla_hours, print_config, notification_config,
    status, created_by
  ) values (
    v_template.id, v_number, v_published.form_schema, v_published.usage_scope,
    v_published.flow_mode, v_published.completion_policy, v_published.request_sla_hours,
    v_published.print_config, v_published.notification_config, 'DRAFT', v_actor
  ) returning * into v_draft;

  insert into public.request_approval_blocks(
    request_template_version_id, block_key, name, sort_order, approver_source,
    fixed_user_ids, minimum_dynamic_approvers, sla_hours, is_required
  )
  select v_draft.id, block_key, name, sort_order, approver_source,
    fixed_user_ids, minimum_dynamic_approvers, sla_hours, is_required
  from public.request_approval_blocks
  where request_template_version_id = v_published.id;

  insert into public.request_template_watchers(request_template_version_id, user_id)
  select v_draft.id, user_id
  from public.request_template_watchers
  where request_template_version_id = v_published.id
  on conflict do nothing;

  insert into public.request_print_templates(
    request_template_version_id, name, file_name, storage_path,
    validation_status, placeholder_schema
  )
  select v_draft.id, name, file_name, storage_path,
    validation_status, placeholder_schema
  from public.request_print_templates
  where request_template_version_id = v_published.id;

  update public.request_templates
  set lifecycle_status = 'DRAFT'
  where id = v_template.id
  returning * into v_template;

  return jsonb_build_object(
    'id', v_draft.request_template_id,
    'draftVersionId', v_draft.id,
    'status', v_draft.status,
    'versionNumber', v_draft.version_number,
    'updatedAt', v_template.updated_at,
    'payload', app_private.request_template_draft_payload(v_draft.id)
  );
end;
$$","-- A copy is a new template lineage. The source version remains immutable and
-- the target starts as version 1 in DRAFT state.
create or replace function app_private.duplicate_request_template(
  p_request_template_id uuid
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := public.current_app_user_id();
  v_source_template public.request_templates%rowtype;
  v_source_version public.request_template_versions%rowtype;
  v_target_template public.request_templates%rowtype;
  v_target_version public.request_template_versions%rowtype;
  v_base_name text;
  v_copy_name text;
  v_suffix integer := 1;
begin
  if v_actor is null or not app_private.request_user_can_manage(v_actor) then
    raise exception using errcode = '42501', message = 'REQUEST_TEMPLATE_FORBIDDEN';
  end if;

  select * into v_source_template
  from public.request_templates
  where id = p_request_template_id
  for update;
  if not found then
    raise exception using errcode = 'P0002', message = 'REQUEST_TEMPLATE_NOT_FOUND';
  end if;

  select * into v_source_version
  from public.request_template_versions version
  where version.request_template_id = v_source_template.id
  order by
    case version.status
      when 'DRAFT' then 1
      when 'PUBLISHED' then 2
      when 'SUPERSEDED' then 3
      else 4
    end,
    version.version_number desc
  limit 1;
  if not found then
    raise exception using errcode = '22023', message = 'REQUEST_TEMPLATE_VERSION_REQUIRED';
  end if;

  v_base_name := v_source_template.name || ' - Bản sao';
  perform pg_advisory_xact_lock(hashtextextended(lower(v_base_name), 0));
  v_copy_name := v_base_name;
  while exists (
    select 1
    from public.request_templates existing_template
    where lower(existing_template.name) = lower(v_copy_name)
  ) loop
    v_suffix := v_suffix + 1;
    v_copy_name := format('%s (%s)', v_base_name, v_suffix);
  end loop;

  insert into public.request_templates(
    name, description, lifecycle_status, current_version_id, created_by
  ) values (
    v_copy_name,
    coalesce(v_source_template.description, ''),
    'DRAFT',
    null,
    v_actor
  ) returning * into v_target_template;

  insert into public.request_template_versions(
    request_template_id, version_number, form_schema, usage_scope,
    flow_mode, completion_policy, request_sla_hours, print_config,
    notification_config, status, created_by
  ) values (
    v_target_template.id,
    1,
    v_source_version.form_schema,
    v_source_version.usage_scope,
    v_source_version.flow_mode,
    v_source_version.completion_policy,
    v_source_version.request_sla_hours,
    v_source_version.print_config,
    v_source_version.notification_config,
    'DRAFT',
    v_actor
  ) returning * into v_target_version;

  insert into public.request_approval_blocks(
    request_template_version_id, block_key, name, sort_order, approver_source,
    fixed_user_ids, minimum_dynamic_approvers, sla_hours, is_required
  )
  select v_target_version.id, block_key, name, sort_order, approver_source,
    fixed_user_ids, minimum_dynamic_approvers, sla_hours, is_required
  from public.request_approval_blocks
  where request_template_version_id = v_source_version.id;

  insert into public.request_template_watchers(request_template_version_id, user_id)
  select v_target_version.id, user_id
  from public.request_template_watchers
  where request_template_version_id = v_source_version.id
  on conflict do nothing;

  insert into public.request_print_templates(
    request_template_version_id, name, file_name, storage_path,
    validation_status, placeholder_schema
  )
  select v_target_version.id, name, file_name, storage_path,
    validation_status, placeholder_schema
  from public.request_print_templates
  where request_template_version_id = v_source_version.id;

  return jsonb_build_object(
    'id', v_target_template.id,
    'draftVersionId', v_target_version.id,
    'status', v_target_version.status,
    'versionNumber', v_target_version.version_number,
    'updatedAt', v_target_template.updated_at,
    'payload', app_private.request_template_draft_payload(v_target_version.id)
  );
end;
$$","create or replace function public.duplicate_request_template(
  p_request_template_id uuid
)
returns jsonb
language sql
security invoker
set search_path = ''
as $$
  select app_private.duplicate_request_template(p_request_template_id);
$$","revoke all on function app_private.duplicate_request_template(uuid)
  from public, anon, authenticated","grant execute on function app_private.duplicate_request_template(uuid) to authenticated","revoke all on function public.duplicate_request_template(uuid) from public, anon","grant execute on function public.duplicate_request_template(uuid) to authenticated"}

{"create or replace function public.process_workflow_instance_fast(
  p_instance_id uuid,
  p_action public.workflow_instance_action,
  p_user_id uuid,
  p_comment text,
  p_next_assignee_user_ids uuid[]
)
returns table (
  id uuid,
  template_id uuid,
  code text,
  title text,
  created_by uuid,
  current_node_id uuid,
  status public.workflow_instance_status,
  watchers text[],
  step_assignees jsonb,
  created_at timestamptz,
  updated_at timestamptz
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_inst public.workflow_instances%rowtype;
  v_current_user uuid := public.current_app_user_id();
  v_actor public.users%rowtype;
  v_template public.workflow_templates%rowtype;
  v_current_node public.workflow_nodes%rowtype;
  v_next_node_id uuid;
  v_next_node_type public.workflow_node_type;
  v_prev_node_id uuid;
  v_prev_node_type public.workflow_node_type;
  v_start_node_id uuid;
  v_first_task_node_id uuid;
  v_can_act boolean := false;
  v_next_assignee_ids uuid[] := coalesce(
    array(
      select distinct assignee.assignee_id
      from unnest(coalesce(p_next_assignee_user_ids, '{}'::uuid[])) as assignee(assignee_id)
      where assignee.assignee_id is not null
    ),
    '{}'::uuid[]
  );
begin
  if v_current_user is null then
    raise exception 'authentication required';
  end if;

  if p_user_id is distinct from v_current_user and not public.is_module_admin('WF') then
    raise exception 'cannot act as another user';
  end if;

  select u.* into v_actor
  from public.users u
  where u.id = p_user_id;

  select wi.* into v_inst
  from public.workflow_instances wi
  where wi.id = p_instance_id
  for update;

  if not found then
    raise exception 'workflow instance not found: %', p_instance_id;
  end if;

  if exists (
    select 1
    from public.request_instances request_instance
    where request_instance.workflow_instance_id = p_instance_id
  ) then
    raise exception using
      errcode = 'P0001',
      message = 'REQUEST_WORKFLOW_USE_REQUEST_MODULE';
  end if;

  if v_inst.status <> 'RUNNING'::public.workflow_instance_status then
    raise exception 'workflow instance is not running';
  end if;

  if v_inst.current_node_id is null then
    raise exception 'workflow instance has no current node';
  end if;

  select wn.* into v_current_node
  from public.workflow_nodes wn
  where wn.id = v_inst.current_node_id;

  if not found then
    raise exception 'workflow current node not found: %', v_inst.current_node_id;
  end if;

  select wt.* into v_template
  from public.workflow_templates wt
  where wt.id = v_inst.template_id;

  if not found then
    raise exception 'workflow template not found: %', v_inst.template_id;
  end if;

  select n.id into v_start_node_id
  from public.workflow_nodes n
  where n.template_id = v_inst.template_id
    and n.type = 'START'::public.workflow_node_type
  limit 1;

  select e.target_node_id into v_first_task_node_id
  from public.workflow_edges e
  where e.source_node_id = v_start_node_id
  limit 1;

  v_can_act :=
    public.is_module_admin('WF')
    or coalesce(v_inst.step_assignees ->> v_inst.current_node_id::text, '') = p_user_id::text
    or (
      jsonb_typeof(v_inst.step_assignees -> v_inst.current_node_id::text) = 'array'
      and exists (
        select 1
        from jsonb_array_elements_text(v_inst.step_assignees -> v_inst.current_node_id::text) assignee(user_id)
        where assignee.user_id = p_user_id::text
      )
    )
    or coalesce(v_current_node.config ->> 'assigneeUserId', '') = p_user_id::text
    or (
      v_actor.id is not null
      and coalesce(v_current_node.config ->> 'assigneeRole', '') = v_actor.role::text
    )
    or p_user_id::text = any(coalesce(v_template.managers, '{}'::text[]))
    or (
      v_inst.created_by = p_user_id
      and v_inst.current_node_id = v_first_task_node_id
      and exists (
        select 1
        from public.workflow_instance_logs wil
        where wil.instance_id = p_instance_id
          and wil.action = 'REVISION_REQUESTED'::public.workflow_instance_action
      )
    );

  if not v_can_act then
    raise exception 'user is not allowed to process current workflow step';
  end if;

  insert into public.workflow_instance_logs(instance_id, node_id, action, acted_by, comment)
  values (p_instance_id, v_inst.current_node_id, p_action, p_user_id, coalesce(p_comment, ''));

  if p_action = 'APPROVED'::public.workflow_instance_action then
    select e.target_node_id, n.type
      into v_next_node_id, v_next_node_type
    from public.workflow_edges e
    join public.workflow_nodes n on n.id = e.target_node_id
    where e.source_node_id = v_inst.current_node_id
    limit 1;

    if v_next_node_id is null then
      raise exception 'no next workflow node found';
    end if;

    update public.workflow_instances wi
    set current_node_id = v_next_node_id,
        status = case
          when v_next_node_type = 'END'::public.workflow_node_type
          then 'COMPLETED'::public.workflow_instance_status
          else wi.status
        end,
        step_assignees = case
          when v_next_node_type <> 'END'::public.workflow_node_type and cardinality(v_next_assignee_ids) > 0
          then coalesce(wi.step_assignees, '{}'::jsonb) || app_private.workflow_assignee_json(v_next_node_id, v_next_assignee_ids)
          else coalesce(wi.step_assignees, '{}'::jsonb)
        end,
        updated_at = now()
    where wi.id = p_instance_id
    returning wi.* into v_inst;
  elsif p_action = 'REJECTED'::public.workflow_instance_action then
    update public.workflow_instances wi
    set status = 'REJECTED'::public.workflow_instance_status,
        updated_at = now()
    where wi.id = p_instance_id
    returning wi.* into v_inst;
  elsif p_action = 'REVISION_REQUESTED'::public.workflow_instance_action then
    select e.source_node_id, n.type
      into v_prev_node_id, v_prev_node_type
    from public.workflow_edges e
    join public.workflow_nodes n on n.id = e.source_node_id
    where e.target_node_id = v_inst.current_node_id
    limit 1;

    if v_prev_node_id is not null and v_prev_node_type = 'START'::public.workflow_node_type then
      select e.target_node_id
        into v_prev_node_id
      from public.workflow_edges e
      where e.source_node_id = v_prev_node_id
      limit 1;
    end if;

    if v_prev_node_id is not null then
      update public.workflow_instances wi
      set current_node_id = v_prev_node_id,
          step_assignees = case
            when cardinality(v_next_assignee_ids) > 0
            then coalesce(wi.step_assignees, '{}'::jsonb) || app_private.workflow_assignee_json(v_prev_node_id, v_next_assignee_ids)
            else coalesce(wi.step_assignees, '{}'::jsonb)
          end,
          updated_at = now()
      where wi.id = p_instance_id
      returning wi.* into v_inst;
    end if;
  end if;

  return query select
    v_inst.id,
    v_inst.template_id,
    v_inst.code,
    v_inst.title,
    v_inst.created_by,
    v_inst.current_node_id,
    v_inst.status,
    coalesce(v_inst.watchers, '{}'::text[]),
    coalesce(v_inst.step_assignees, '{}'::jsonb),
    v_inst.created_at,
    v_inst.updated_at;
end;
$$","revoke execute on function public.process_workflow_instance_fast(uuid, public.workflow_instance_action, uuid, text, uuid[]) from anon","revoke execute on function public.process_workflow_instance_fast(uuid, public.workflow_instance_action, uuid, text, uuid[]) from public","grant execute on function public.process_workflow_instance_fast(uuid, public.workflow_instance_action, uuid, text, uuid[]) to authenticated","notify pgrst, 'reload schema'"}

{"-- Vehicle Booking Phase 1.1B: state machine and command hardening.
-- Cloud-only additive migration; safe to re-run.

begin","alter table public.fleet_system_settings
  add column if not exists trip_reminder_minutes integer not null default 60,
  add column if not exists require_handover_for_self_drive boolean not null default true,
  add column if not exists allow_dispatch_approval_override boolean not null default true","do $settings_constraints$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.fleet_system_settings'::regclass
      and conname = 'fleet_system_settings_trip_reminder_nonnegative'
  ) then
    alter table public.fleet_system_settings
      add constraint fleet_system_settings_trip_reminder_nonnegative
      check (trip_reminder_minutes >= 0);
  end if;
end;
$settings_constraints$","alter table public.fleet_vehicle_profiles
  alter column home_base_id set not null","do $booking_constraints$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.vehicle_booking_assignments'::regclass
      and conname = 'vehicle_assignment_fulfillment_shape_check'
  ) then
    alter table public.vehicle_booking_assignments
      add constraint vehicle_assignment_fulfillment_shape_check
      check (
        (
          fulfillment_type = 'INTERNAL_WITH_DRIVER'
          and vehicle_asset_id is not null
          and operator_user_id is not null
          and operator_type = 'PROFESSIONAL_DRIVER'
          and external_service_type is null
        )
        or (
          fulfillment_type = 'INTERNAL_SELF_DRIVE'
          and vehicle_asset_id is not null
          and operator_user_id is not null
          and operator_type = 'SELF_DRIVER'
          and handover_officer_user_id is not null
          and external_service_type is null
        )
        or (
          fulfillment_type = 'EXTERNAL_TRANSPORT'
          and vehicle_asset_id is null
          and operator_user_id is null
          and operator_type is null
          and handover_officer_user_id is null
          and nullif(trim(external_service_type), '') is not null
        )
      );
  end if;

  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.vehicle_booking_assignments'::regclass
      and conname = 'vehicle_assignment_non_home_base_reason_check'
  ) then
    alter table public.vehicle_booking_assignments
      add constraint vehicle_assignment_non_home_base_reason_check
      check (
        not allow_non_home_base_return
        or nullif(trim(non_home_base_return_reason), '') is not null
      );
  end if;

  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.vehicle_trip_logs'::regclass
      and conname = 'vehicle_trip_start_evidence_check'
  ) then
    alter table public.vehicle_trip_logs
      add constraint vehicle_trip_start_evidence_check
      check (
        trip_status = 'NOT_STARTED'
        or (
          start_odometer is not null
          and nullif(trim(start_photo_path), '') is not null
          and (
            (not start_location_capture_failed and start_latitude is not null and start_longitude is not null)
            or (
              start_location_capture_failed
              and nullif(trim(start_location_failure_reason), '') is not null
            )
          )
        )
      );
  end if;

  if not exists (
    select 1 from pg_constraint
    where conrelid = 'public.vehicle_trip_logs'::regclass
      and conname = 'vehicle_trip_finish_evidence_check'
  ) then
    alter table public.vehicle_trip_logs
      add constraint vehicle_trip_finish_evidence_check
      check (
        trip_status <> 'FINISHED'
        or (
          end_odometer is not null
          and nullif(trim(end_photo_path), '') is not null
          and vehicle_condition_end is not null
          and (
            vehicle_condition_end <> 'ISSUE'
            or nullif(trim(issue_note), '') is not null
          )
          and (
            (not end_location_capture_failed and end_latitude is not null and end_longitude is not null)
            or (
              end_location_capture_failed
              and nullif(trim(end_location_failure_reason), '') is not null
            )
          )
        )
      );
  end if;
end;
$booking_constraints$","create index if not exists idx_vehicle_participants_user_booking
  on public.vehicle_booking_participants(user_id, booking_id)
  where user_id is not null","create index if not exists idx_vehicle_assignments_operator_active
  on public.vehicle_booking_assignments(operator_user_id, booking_id)
  where is_active and operator_user_id is not null","create index if not exists idx_vehicle_assignments_handover_active
  on public.vehicle_booking_assignments(handover_officer_user_id, booking_id)
  where is_active and handover_officer_user_id is not null","create index if not exists idx_vehicle_unavailability_asset_range
  on public.vehicle_unavailability_periods using gist(vehicle_asset_id, scheduled_range)","create index if not exists idx_operator_unavailability_user_range
  on public.operator_unavailability_periods using gist(operator_user_id, scheduled_range)","create or replace function app_private.vehicle_raise_permission_denied(p_detail text)
returns void
language plpgsql
volatile
security definer
set search_path = ''
as $$
begin
  raise exception using
    errcode = '42501',
    message = 'PERMISSION_DENIED',
    detail = p_detail;
end;
$$","create or replace function app_private.vehicle_record_audit(
  p_actor_user_id uuid,
  p_booking_id uuid,
  p_event text,
  p_old_data jsonb default '{}'::jsonb,
  p_new_data jsonb default '{}'::jsonb,
  p_description text default null
) returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.audit_trail (
    table_name,
    record_id,
    action,
    changes,
    old_data,
    new_data,
    user_id,
    user_name,
    module,
    description,
    record_label,
    entity_type,
    changed_fields,
    change_count,
    impact_level,
    context
  ) values (
    'vehicle_bookings',
    p_booking_id::text,
    'UPDATE',
    jsonb_build_object('event', p_event),
    coalesce(p_old_data, '{}'::jsonb),
    coalesce(p_new_data, '{}'::jsonb),
    p_actor_user_id::text,
    '',
    'VEHICLE_BOOKING',
    coalesce(p_description, p_event),
    p_booking_id::text,
    'vehicle_booking',
    array(select jsonb_object_keys(coalesce(p_new_data, '{}'::jsonb))),
    (
      select count(*)::integer
      from jsonb_object_keys(coalesce(p_new_data, '{}'::jsonb))
    ),
    case when p_event like '%OVERRIDE%' or p_event in ('NO_SHOW', 'CANCELLED') then 'high' else 'normal' end,
    jsonb_build_object('booking_id', p_booking_id, 'event', p_event)
  );
end;
$$","create or replace function app_private.vehicle_enqueue_notification(
  p_booking_id uuid,
  p_event_type text,
  p_recipient_user_id uuid,
  p_payload jsonb default '{}'::jsonb
) returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_recipient_user_id is null then
    return;
  end if;

  insert into app_private.vehicle_booking_notification_outbox (
    event_key,
    recipient_user_id,
    payload
  ) values (
    'vehicle:' || p_booking_id::text || ':' || p_event_type || ':' || p_recipient_user_id::text,
    p_recipient_user_id,
    coalesce(p_payload, '{}'::jsonb) || jsonb_build_object(
      'booking_id', p_booking_id,
      'event_type', p_event_type
    )
  ) on conflict (event_key, recipient_user_id) do nothing;
end;
$$","create or replace function app_private.vehicle_assert_operator_eligible(
  p_operator_user_id uuid,
  p_authorization_type text,
  p_vehicle_type text
) returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_authorization public.vehicle_driver_authorizations%rowtype;
begin
  if not exists (
    select 1
    from public.users u
    where u.id = p_operator_user_id
      and coalesce(u.is_active, true)
      and coalesce(u.account_status, 'ACTIVE') = 'ACTIVE'
  ) then
    raise exception using errcode = 'P0001', message = 'OPERATOR_UNAVAILABLE';
  end if;

  select *
  into v_authorization
  from public.vehicle_driver_authorizations vda
  where vda.user_id = p_operator_user_id
    and vda.authorization_type = p_authorization_type;

  if not found or v_authorization.status <> 'ACTIVE' then
    raise exception using errcode = 'P0001', message = case
      when p_authorization_type = 'SELF_DRIVE' then 'SELF_DRIVER_NOT_AUTHORIZED'
      else 'DRIVER_NOT_AUTHORIZED'
    end;
  end if;

  if v_authorization.license_expiry < current_date then
    raise exception using errcode = 'P0001', message = 'DRIVER_LICENSE_EXPIRED';
  end if;

  if v_authorization.health_check_expiry_date is not null
     and v_authorization.health_check_expiry_date < current_date then
    raise exception using errcode = 'P0001', message = 'OPERATOR_UNAVAILABLE';
  end if;

  if v_authorization.allowed_vehicle_types is null
     or not (p_vehicle_type = any(v_authorization.allowed_vehicle_types)) then
    raise exception using errcode = 'P0001', message = 'DRIVER_LICENSE_CLASS_MISMATCH';
  end if;
end;
$$","create or replace function app_private.vehicle_validate_assignment(
  p_booking_id uuid,
  p_fulfillment_type text,
  p_vehicle_asset_id text,
  p_operator_user_id uuid,
  p_handover_officer_user_id uuid,
  p_allow_non_home_base_return boolean,
  p_non_home_base_return_reason text,
  p_external_service_type text
) returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_vehicle public.fleet_vehicle_profiles%rowtype;
  v_buffer_minutes integer := 0;
  v_reserved_range tstzrange;
begin
  select * into v_booking
  from public.vehicle_bookings b
  where b.id = p_booking_id;

  if not found then
    raise exception using errcode = 'P0001', message = 'BOOKING_NOT_FOUND';
  end if;

  select coalesce(settings.booking_buffer_minutes, 0)
  into v_buffer_minutes
  from public.fleet_system_settings settings
  where settings.id = 1;

  v_reserved_range := tstzrange(
    v_booking.requested_pickup_at,
    v_booking.expected_return_at + make_interval(mins => coalesce(v_buffer_minutes, 0)),
    '[)'
  );

  if coalesce(p_allow_non_home_base_return, false)
     and nullif(trim(p_non_home_base_return_reason), '') is null then
    raise exception using errcode = 'P0001', message = 'NON_HOME_BASE_RETURN_REASON_REQUIRED';
  end if;

  if p_fulfillment_type = 'EXTERNAL_TRANSPORT' then
    if p_vehicle_asset_id is not null or p_operator_user_id is not null
       or p_handover_officer_user_id is not null then
      raise exception using errcode = 'P0001', message = 'INVALID_EXTERNAL_ASSIGNMENT';
    end if;
    if nullif(trim(p_external_service_type), '') is null then
      raise exception using errcode = 'P0001', message = 'EXTERNAL_SERVICE_TYPE_REQUIRED';
    end if;
    return;
  end if;

  if p_fulfillment_type not in ('INTERNAL_WITH_DRIVER', 'INTERNAL_SELF_DRIVE') then
    raise exception using errcode = 'P0001', message = 'INVALID_FULFILLMENT_TYPE';
  end if;

  if p_vehicle_asset_id is null then
    raise exception using errcode = 'P0001', message = 'VEHICLE_REQUIRED';
  end if;
  if p_operator_user_id is null then
    raise exception using errcode = 'P0001', message = 'OPERATOR_REQUIRED';
  end if;
  if p_fulfillment_type = 'INTERNAL_SELF_DRIVE' and p_handover_officer_user_id is null then
    raise exception using errcode = 'P0001', message = 'HANDOVER_OFFICER_REQUIRED';
  end if;

  select * into v_vehicle
  from public.fleet_vehicle_profiles profile
  where profile.asset_id = p_vehicle_asset_id
  for share;

  if not found or not v_vehicle.active
     or v_vehicle.availability_status <> 'AVAILABLE'
     or v_vehicle.home_base_id is null then
    raise exception using errcode = 'P0001', message = 'VEHICLE_UNAVAILABLE';
  end if;

  if v_vehicle.inspection_expiry_date is not null
     and v_vehicle.inspection_expiry_date < current_date then
    raise exception using errcode = 'P0001', message = 'VEHICLE_INSPECTION_EXPIRED';
  end if;
  if v_vehicle.insurance_expiry_date is not null
     and v_vehicle.insurance_expiry_date < current_date then
    raise exception using errcode = 'P0001', message = 'VEHICLE_INSURANCE_EXPIRED';
  end if;
  if p_fulfillment_type = 'INTERNAL_SELF_DRIVE' and not v_vehicle.allow_self_drive then
    raise exception using errcode = 'P0001', message = 'SELF_DRIVE_NOT_ALLOWED';
  end if;

  perform app_private.vehicle_assert_operator_eligible(
    p_operator_user_id,
    case when p_fulfillment_type = 'INTERNAL_SELF_DRIVE'
      then 'SELF_DRIVE' else 'PROFESSIONAL_DRIVER' end,
    v_vehicle.vehicle_type
  );

  if exists (
    select 1
    from public.vehicle_unavailability_periods unavailable
    where unavailable.vehicle_asset_id = p_vehicle_asset_id
      and unavailable.scheduled_range && v_reserved_range
  ) then
    raise exception using errcode = 'P0001', message = 'VEHICLE_UNAVAILABLE';
  end if;

  if exists (
    select 1
    from public.operator_unavailability_periods unavailable
    where unavailable.operator_user_id = p_operator_user_id
      and unavailable.scheduled_range && v_reserved_range
  ) then
    raise exception using errcode = 'P0001', message = 'OPERATOR_UNAVAILABLE';
  end if;
end;
$$","revoke all on function app_private.vehicle_raise_permission_denied(text) from public, anon, authenticated","revoke all on function app_private.vehicle_record_audit(uuid, uuid, text, jsonb, jsonb, text) from public, anon, authenticated","revoke all on function app_private.vehicle_enqueue_notification(uuid, text, uuid, jsonb) from public, anon, authenticated","revoke all on function app_private.vehicle_assert_operator_eligible(uuid, text, text) from public, anon, authenticated","revoke all on function app_private.vehicle_validate_assignment(uuid, text, text, uuid, uuid, boolean, text, text) from public, anon, authenticated","create or replace function app_private.command_reject_vehicle_booking(
  p_actor_user_id uuid,
  p_booking_id uuid,
  p_reject_reason text
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_booking public.vehicle_bookings%rowtype;
begin
  if nullif(trim(p_reject_reason), '') is null then
    raise exception using errcode = 'P0001', message = 'REJECT_REASON_REQUIRED';
  end if;

  select * into v_booking
  from public.vehicle_bookings b
  where b.id = p_booking_id
  for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'BOOKING_NOT_FOUND';
  end if;
  if v_booking.status <> 'PENDING_APPROVAL' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;
  if v_booking.manager_user_id_snapshot is distinct from p_actor_user_id
     and not app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch') then
    perform app_private.vehicle_raise_permission_denied('Only the snapshot manager or dispatcher can reject');
  end if;

  update public.vehicle_bookings
  set status = 'CANCELLED',
      close_reason = 'REJECTED_BY_MANAGER',
      close_note = trim(p_reject_reason),
      cancelled_by_user_id = p_actor_user_id,
      cancelled_at = now(),
      updated_at = now()
  where id = p_booking_id;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    p_booking_id,
    'REJECTED',
    jsonb_build_object('status', v_booking.status),
    jsonb_build_object('status', 'CANCELLED', 'close_reason', 'REJECTED_BY_MANAGER'),
    'Từ chối booking xe'
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'BOOKING_REJECTED',
    v_booking.requester_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code)
  );

  return jsonb_build_object('success', true, 'status', 'CANCELLED', 'close_reason', 'REJECTED_BY_MANAGER');
end;
$$","create or replace function app_private.command_dispatch_vehicle_booking(
  p_actor_user_id uuid,
  p_booking_id uuid,
  p_fulfillment_type text,
  p_vehicle_asset_id text default null,
  p_operator_user_id uuid default null,
  p_handover_officer_user_id uuid default null,
  p_allow_non_home_base_return boolean default false,
  p_non_home_base_return_reason text default null,
  p_external_service_type text default null,
  p_external_provider_name text default null,
  p_external_driver_name text default null,
  p_external_driver_phone text default null,
  p_external_vehicle_plate text default null,
  p_external_estimated_cost numeric default null,
  p_dispatch_reason_code text default null,
  p_assignment_note text default null,
  p_override_reason text default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_assignment_id uuid := gen_random_uuid();
  v_buffer_minutes integer := 0;
  v_keys text[] := array[]::text[];
  v_key text;
  v_operator_type text;
  v_home_base_id uuid;
begin
  if not app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch') then
    perform app_private.vehicle_raise_permission_denied('Dispatcher permission is required');
  end if;

  select * into v_booking
  from public.vehicle_bookings b
  where b.id = p_booking_id
  for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'BOOKING_NOT_FOUND';
  end if;
  if v_booking.status not in ('PENDING_APPROVAL', 'WAITING_DISPATCH') then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;
  if v_booking.status = 'PENDING_APPROVAL'
     and nullif(trim(p_override_reason), '') is null then
    raise exception using errcode = 'P0001', message = 'OVERRIDE_REASON_REQUIRED';
  end if;

  if p_vehicle_asset_id is not null then
    v_keys := array_append(v_keys, 'vehicle:' || p_vehicle_asset_id);
  end if;
  if p_operator_user_id is not null then
    v_keys := array_append(v_keys, 'operator:' || p_operator_user_id::text);
  end if;
  select coalesce(array_agg(resource_key order by resource_key), array[]::text[])
  into v_keys
  from unnest(v_keys) resource_key;
  foreach v_key in array v_keys loop
    perform pg_advisory_xact_lock(hashtextextended(v_key, 0));
  end loop;

  perform app_private.vehicle_validate_assignment(
    p_booking_id,
    p_fulfillment_type,
    p_vehicle_asset_id,
    p_operator_user_id,
    p_handover_officer_user_id,
    p_allow_non_home_base_return,
    p_non_home_base_return_reason,
    p_external_service_type
  );

  select coalesce(settings.booking_buffer_minutes, 0)
  into v_buffer_minutes
  from public.fleet_system_settings settings
  where settings.id = 1;

  if p_vehicle_asset_id is not null then
    select profile.home_base_id into v_home_base_id
    from public.fleet_vehicle_profiles profile
    where profile.asset_id = p_vehicle_asset_id;
  end if;

  v_operator_type := case p_fulfillment_type
    when 'INTERNAL_WITH_DRIVER' then 'PROFESSIONAL_DRIVER'
    when 'INTERNAL_SELF_DRIVE' then 'SELF_DRIVER'
    else null
  end;

  insert into public.vehicle_booking_assignments (
    id, booking_id, version, is_active, fulfillment_type,
    vehicle_asset_id, operator_user_id, operator_type,
    reserved_start_at, reserved_end_at, home_base_id_snapshot,
    handover_officer_user_id, allow_non_home_base_return,
    non_home_base_return_reason, external_service_type,
    external_provider_name, external_driver_name, external_driver_phone,
    external_vehicle_plate, external_estimated_cost, dispatch_reason_code,
    assigned_by_user_id, assignment_note
  ) values (
    v_assignment_id, p_booking_id, 1, true, p_fulfillment_type,
    p_vehicle_asset_id, p_operator_user_id, v_operator_type,
    v_booking.requested_pickup_at,
    v_booking.expected_return_at + make_interval(mins => coalesce(v_buffer_minutes, 0)),
    v_home_base_id, p_handover_officer_user_id,
    coalesce(p_allow_non_home_base_return, false), p_non_home_base_return_reason,
    p_external_service_type, p_external_provider_name, p_external_driver_name,
    p_external_driver_phone, p_external_vehicle_plate, p_external_estimated_cost,
    p_dispatch_reason_code, p_actor_user_id, p_assignment_note
  );

  if p_fulfillment_type <> 'EXTERNAL_TRANSPORT' then
    insert into public.vehicle_trip_logs (
      booking_id, assignment_id, assignment_version_snapshot,
      vehicle_asset_id_snapshot, operator_user_id_snapshot, trip_status
    ) values (
      p_booking_id, v_assignment_id, 1,
      p_vehicle_asset_id, p_operator_user_id, 'NOT_STARTED'
    );
  end if;

  update public.vehicle_bookings
  set status = 'ASSIGNED',
      approved_by_user_id = coalesce(approved_by_user_id, p_actor_user_id),
      approved_at = coalesce(approved_at, now()),
      approval_source = case when status = 'PENDING_APPROVAL' then 'DISPATCH_OVERRIDE' else approval_source end,
      approval_note = case when status = 'PENDING_APPROVAL' then trim(p_override_reason) else approval_note end,
      manager_resolution_status = case when status = 'PENDING_APPROVAL' then 'OVERRIDDEN' else manager_resolution_status end,
      updated_at = now()
  where id = p_booking_id;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    p_booking_id,
    case when v_booking.status = 'PENDING_APPROVAL' then 'DISPATCH_OVERRIDE' else 'DISPATCHED' end,
    jsonb_build_object('status', v_booking.status),
    jsonb_build_object('status', 'ASSIGNED', 'assignment_id', v_assignment_id, 'fulfillment_type', p_fulfillment_type),
    'Điều phối booking xe'
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'BOOKING_ASSIGNED',
    v_booking.requester_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code, 'assignment_id', v_assignment_id)
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'BOOKING_ASSIGNED',
    p_operator_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code, 'assignment_id', v_assignment_id)
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'HANDOVER_ASSIGNED',
    p_handover_officer_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code, 'assignment_id', v_assignment_id)
  );

  return jsonb_build_object('success', true, 'assignment_id', v_assignment_id, 'status', 'ASSIGNED');
end;
$$","create or replace function app_private.command_reassign_vehicle_booking(
  p_actor_user_id uuid,
  p_booking_id uuid,
  p_reassign_reason text,
  p_fulfillment_type text,
  p_vehicle_asset_id text default null,
  p_operator_user_id uuid default null,
  p_handover_officer_user_id uuid default null,
  p_allow_non_home_base_return boolean default false,
  p_non_home_base_return_reason text default null,
  p_external_service_type text default null,
  p_external_provider_name text default null,
  p_external_driver_name text default null,
  p_external_driver_phone text default null,
  p_external_vehicle_plate text default null,
  p_external_estimated_cost numeric default null,
  p_dispatch_reason_code text default null,
  p_assignment_note text default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_old_assignment public.vehicle_booking_assignments%rowtype;
  v_new_assignment_id uuid := gen_random_uuid();
  v_new_version integer;
  v_buffer_minutes integer := 0;
  v_operator_type text;
  v_home_base_id uuid;
  v_keys text[] := array[]::text[];
  v_key text;
begin
  if not app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch') then
    perform app_private.vehicle_raise_permission_denied('Dispatcher permission is required');
  end if;
  if nullif(trim(p_reassign_reason), '') is null then
    raise exception using errcode = 'P0001', message = 'REASSIGN_REASON_REQUIRED';
  end if;

  select * into v_booking
  from public.vehicle_bookings b
  where b.id = p_booking_id
  for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'BOOKING_NOT_FOUND';
  end if;
  if v_booking.status <> 'ASSIGNED' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;

  select * into v_old_assignment
  from public.vehicle_booking_assignments assignment
  where assignment.booking_id = p_booking_id and assignment.is_active
  for update;
  if not found then
    raise exception using errcode = 'P0001', message = 'ASSIGNMENT_NOT_FOUND';
  end if;

  v_keys := array_remove(array[
    case when v_old_assignment.vehicle_asset_id is not null then 'vehicle:' || v_old_assignment.vehicle_asset_id end,
    case when v_old_assignment.operator_user_id is not null then 'operator:' || v_old_assignment.operator_user_id::text end,
    case when p_vehicle_asset_id is not null then 'vehicle:' || p_vehicle_asset_id end,
    case when p_operator_user_id is not null then 'operator:' || p_operator_user_id::text end
  ], null);
  select coalesce(array_agg(distinct resource_key order by resource_key), array[]::text[])
  into v_keys
  from unnest(v_keys) resource_key;
  foreach v_key in array v_keys loop
    perform pg_advisory_xact_lock(hashtextextended(v_key, 0));
  end loop;

  perform app_private.vehicle_validate_assignment(
    p_booking_id,
    p_fulfillment_type,
    p_vehicle_asset_id,
    p_operator_user_id,
    p_handover_officer_user_id,
    p_allow_non_home_base_return,
    p_non_home_base_return_reason,
    p_external_service_type
  );

  select coalesce(max(assignment.version), 0) + 1
  into v_new_version
  from public.vehicle_booking_assignments assignment
  where assignment.booking_id = p_booking_id;

  update public.vehicle_booking_assignments
  set is_active = false,
      released_at = coalesce(released_at, now()),
      superseded_at = now(),
      superseded_by_user_id = p_actor_user_id,
      supersede_reason = trim(p_reassign_reason),
      updated_at = now()
  where id = v_old_assignment.id;

  delete from public.vehicle_trip_logs
  where booking_id = p_booking_id
    and trip_status = 'NOT_STARTED';

  select coalesce(settings.booking_buffer_minutes, 0)
  into v_buffer_minutes
  from public.fleet_system_settings settings
  where settings.id = 1;

  if p_vehicle_asset_id is not null then
    select profile.home_base_id into v_home_base_id
    from public.fleet_vehicle_profiles profile
    where profile.asset_id = p_vehicle_asset_id;
  end if;

  v_operator_type := case p_fulfillment_type
    when 'INTERNAL_WITH_DRIVER' then 'PROFESSIONAL_DRIVER'
    when 'INTERNAL_SELF_DRIVE' then 'SELF_DRIVER'
    else null
  end;

  insert into public.vehicle_booking_assignments (
    id, booking_id, version, is_active, fulfillment_type,
    vehicle_asset_id, operator_user_id, operator_type,
    reserved_start_at, reserved_end_at, home_base_id_snapshot,
    handover_officer_user_id, allow_non_home_base_return,
    non_home_base_return_reason, external_service_type,
    external_provider_name, external_driver_name, external_driver_phone,
    external_vehicle_plate, external_estimated_cost, dispatch_reason_code,
    assigned_by_user_id, assignment_note
  ) values (
    v_new_assignment_id, p_booking_id, v_new_version, true, p_fulfillment_type,
    p_vehicle_asset_id, p_operator_user_id, v_operator_type,
    v_booking.requested_pickup_at,
    v_booking.expected_return_at + make_interval(mins => coalesce(v_buffer_minutes, 0)),
    v_home_base_id, p_handover_officer_user_id,
    coalesce(p_allow_non_home_base_return, false), p_non_home_base_return_reason,
    p_external_service_type, p_external_provider_name, p_external_driver_name,
    p_external_driver_phone, p_external_vehicle_plate, p_external_estimated_cost,
    p_dispatch_reason_code, p_actor_user_id, p_assignment_note
  );

  if p_fulfillment_type <> 'EXTERNAL_TRANSPORT' then
    insert into public.vehicle_trip_logs (
      booking_id, assignment_id, assignment_version_snapshot,
      vehicle_asset_id_snapshot, operator_user_id_snapshot, trip_status
    ) values (
      p_booking_id, v_new_assignment_id, v_new_version,
      p_vehicle_asset_id, p_operator_user_id, 'NOT_STARTED'
    );
  end if;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    p_booking_id,
    'REASSIGNED',
    jsonb_build_object(
      'assignment_id', v_old_assignment.id,
      'vehicle_asset_id', v_old_assignment.vehicle_asset_id,
      'operator_user_id', v_old_assignment.operator_user_id
    ),
    jsonb_build_object(
      'assignment_id', v_new_assignment_id,
      'vehicle_asset_id', p_vehicle_asset_id,
      'operator_user_id', p_operator_user_id,
      'reason', trim(p_reassign_reason)
    ),
    'Đổi phương án điều phối xe'
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'BOOKING_REASSIGNED',
    v_booking.requester_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code, 'assignment_id', v_new_assignment_id)
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'BOOKING_REASSIGNED_OLD_OPERATOR',
    v_old_assignment.operator_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code)
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'BOOKING_REASSIGNED_NEW_OPERATOR',
    p_operator_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code, 'assignment_id', v_new_assignment_id)
  );

  return jsonb_build_object(
    'success', true,
    'assignment_id', v_new_assignment_id,
    'version', v_new_version,
    'status', 'ASSIGNED'
  );
end;
$$","create or replace function app_private.command_respond_to_vehicle_assignment(
  p_actor_user_id uuid,
  p_booking_id uuid,
  p_response text,
  p_decline_reason text default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_assignment public.vehicle_booking_assignments%rowtype;
begin
  if p_response not in ('CONFIRMED', 'DECLINED') then
    raise exception using errcode = 'P0001', message = 'INVALID_ASSIGNMENT_RESPONSE';
  end if;
  if p_response = 'DECLINED' and nullif(trim(p_decline_reason), '') is null then
    raise exception using errcode = 'P0001', message = 'DECLINE_REASON_REQUIRED';
  end if;

  select * into v_assignment
  from public.vehicle_booking_assignments assignment
  where assignment.booking_id = p_booking_id and assignment.is_active
  for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'ASSIGNMENT_NOT_FOUND';
  end if;
  if v_assignment.operator_user_id is distinct from p_actor_user_id then
    perform app_private.vehicle_raise_permission_denied('Only the assigned operator can respond');
  end if;
  if not exists (
    select 1 from public.vehicle_bookings booking
    where booking.id = p_booking_id and booking.status = 'ASSIGNED'
  ) then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;

  update public.vehicle_booking_assignments
  set operator_confirmation_status = p_response,
      operator_confirmed_at = case when p_response = 'CONFIRMED' then now() else null end,
      operator_decline_reason = case when p_response = 'DECLINED' then trim(p_decline_reason) else null end,
      updated_at = now()
  where id = v_assignment.id;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    p_booking_id,
    'ASSIGNMENT_' || p_response,
    jsonb_build_object('operator_confirmation_status', v_assignment.operator_confirmation_status),
    jsonb_build_object('operator_confirmation_status', p_response),
    'Phản hồi phân công chuyến xe'
  );

  if p_response = 'DECLINED' then
    insert into app_private.vehicle_booking_notification_outbox(event_key, recipient_user_id, payload)
    select
      'vehicle:' || p_booking_id::text || ':ASSIGNMENT_DECLINED:' || grant_row.user_id::text,
      grant_row.user_id,
      jsonb_build_object('booking_id', p_booking_id, 'event_type', 'ASSIGNMENT_DECLINED')
    from public.user_permission_grants grant_row
    where grant_row.permission_code in ('booking.vehicle.dispatch', 'booking.vehicle.admin')
      and grant_row.is_active
      and grant_row.revoked_at is null
      and (grant_row.expires_at is null or grant_row.expires_at > now())
    on conflict (event_key, recipient_user_id) do nothing;
  end if;

  return jsonb_build_object('success', true, 'response', p_response, 'requires_reassignment', p_response = 'DECLINED');
end;
$$","create or replace function app_private.command_confirm_vehicle_handover(
  p_actor_user_id uuid,
  p_booking_id uuid,
  p_event_type text,
  p_note text default null,
  p_override_reason text default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_assignment public.vehicle_booking_assignments%rowtype;
  v_handover_id uuid := gen_random_uuid();
  v_on_behalf boolean := false;
begin
  if p_event_type not in ('OUTBOUND_HANDOVER', 'RETURN_RECEIPT') then
    raise exception using errcode = 'P0001', message = 'INVALID_HANDOVER_EVENT';
  end if;

  select * into v_booking
  from public.vehicle_bookings booking
  where booking.id = p_booking_id
  for update;
  select * into v_assignment
  from public.vehicle_booking_assignments assignment
  where assignment.booking_id = p_booking_id and assignment.is_active
  for update;

  if v_booking.id is null or v_assignment.id is null then
    raise exception using errcode = 'P0001', message = 'ASSIGNMENT_NOT_FOUND';
  end if;
  if v_assignment.fulfillment_type <> 'INTERNAL_SELF_DRIVE' then
    raise exception using errcode = 'P0001', message = 'HANDOVER_NOT_APPLICABLE';
  end if;
  if p_event_type = 'OUTBOUND_HANDOVER' and v_booking.status <> 'ASSIGNED' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;
  if p_event_type = 'RETURN_RECEIPT' and v_booking.status <> 'COMPLETED' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;

  if v_assignment.handover_officer_user_id is distinct from p_actor_user_id then
    if not app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch') then
      perform app_private.vehicle_raise_permission_denied('Only the handover officer or dispatcher can confirm');
    end if;
    if nullif(trim(p_override_reason), '') is null then
      raise exception using errcode = 'P0001', message = 'OVERRIDE_REASON_REQUIRED';
    end if;
    v_on_behalf := true;
  end if;

  if p_event_type = 'RETURN_RECEIPT' and not exists (
    select 1 from public.vehicle_handover_logs log
    where log.assignment_id = v_assignment.id
      and log.event_type = 'OUTBOUND_HANDOVER'
  ) then
    raise exception using errcode = 'P0001', message = 'OUTBOUND_HANDOVER_REQUIRED';
  end if;

  insert into public.vehicle_handover_logs (
    id, booking_id, assignment_id, assignment_version_snapshot,
    vehicle_asset_id_snapshot, operator_user_id_snapshot, event_type,
    officer_user_id, confirmed_on_behalf, override_reason, note
  ) values (
    v_handover_id, p_booking_id, v_assignment.id, v_assignment.version,
    v_assignment.vehicle_asset_id, v_assignment.operator_user_id, p_event_type,
    p_actor_user_id, v_on_behalf, nullif(trim(p_override_reason), ''), p_note
  );

  if p_event_type = 'OUTBOUND_HANDOVER' then
    update public.fleet_vehicle_profiles
    set custody_status = 'IN_CUSTODY',
        current_custody_assignment_id = v_assignment.id,
        updated_at = now()
    where asset_id = v_assignment.vehicle_asset_id
      and (
        current_custody_assignment_id is null
        or current_custody_assignment_id = v_assignment.id
      );
    if not found then
      raise exception using errcode = 'P0001', message = 'VEHICLE_IN_CUSTODY';
    end if;
  else
    update public.fleet_vehicle_profiles
    set custody_status = 'AVAILABLE',
        current_custody_assignment_id = null,
        updated_at = now()
    where asset_id = v_assignment.vehicle_asset_id
      and current_custody_assignment_id = v_assignment.id;
    update public.vehicle_booking_assignments
    set released_at = coalesce(released_at, now()), updated_at = now()
    where id = v_assignment.id;
  end if;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    p_booking_id,
    p_event_type,
    '{}'::jsonb,
    jsonb_build_object('assignment_id', v_assignment.id, 'confirmed_on_behalf', v_on_behalf),
    case when p_event_type = 'OUTBOUND_HANDOVER' then 'Bàn giao xe tự lái' else 'Nhận lại xe tự lái' end
  );

  return jsonb_build_object('success', true, 'handover_id', v_handover_id, 'event_type', p_event_type);
end;
$$","create or replace function app_private.command_record_vehicle_trip_checkpoint(
  p_actor_user_id uuid,
  p_booking_id uuid,
  p_checkpoint_type text
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_assignment public.vehicle_booking_assignments%rowtype;
begin
  select * into v_booking from public.vehicle_bookings where id = p_booking_id for update;
  select * into v_assignment from public.vehicle_booking_assignments
  where booking_id = p_booking_id and is_active for share;
  if v_booking.id is null or v_assignment.id is null then
    raise exception using errcode = 'P0001', message = 'ASSIGNMENT_NOT_FOUND';
  end if;
  if v_booking.status <> 'IN_PROGRESS' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;
  if v_assignment.operator_user_id is distinct from p_actor_user_id
     and not app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch') then
    perform app_private.vehicle_raise_permission_denied('Only assigned operator or dispatcher can record checkpoints');
  end if;

  if p_checkpoint_type = 'DEPARTED_HOME_BASE' then
    update public.vehicle_trip_logs
    set departed_home_base_at = coalesce(departed_home_base_at, now()), updated_at = now()
    where booking_id = p_booking_id and trip_status = 'IN_PROGRESS';
  elsif p_checkpoint_type = 'PICKED_UP_PASSENGER' then
    update public.vehicle_trip_logs
    set actual_pickup_at = coalesce(actual_pickup_at, now()), updated_at = now()
    where booking_id = p_booking_id and trip_status = 'IN_PROGRESS';
  else
    raise exception using errcode = 'P0001', message = 'INVALID_CHECKPOINT_TYPE';
  end if;

  return jsonb_build_object('success', true, 'checkpoint_type', p_checkpoint_type);
end;
$$","create or replace function app_private.vehicle_assert_evidence_path(
  p_booking_id uuid,
  p_path text,
  p_namespace text
) returns void
language plpgsql
immutable
security definer
set search_path = ''
as $$
begin
  if nullif(trim(p_path), '') is null then
    raise exception using errcode = 'P0001', message = 'ODOMETER_PHOTO_REQUIRED';
  end if;
  if p_path not like p_booking_id::text || '/' || p_namespace || '/%' then
    raise exception using errcode = 'P0001', message = 'INVALID_EVIDENCE_PATH';
  end if;
end;
$$","drop function if exists public.start_vehicle_trip(uuid, numeric, text, numeric, numeric, numeric, boolean, text)","drop function if exists app_private.command_start_vehicle_trip(uuid, uuid, numeric, text, numeric, numeric, numeric, boolean, text)","create or replace function app_private.command_start_vehicle_trip(
  p_actor_user_id uuid,
  p_booking_id uuid,
  p_start_odometer numeric,
  p_start_photo_path text,
  p_latitude numeric default null,
  p_longitude numeric default null,
  p_accuracy_m numeric default null,
  p_location_capture_failed boolean default false,
  p_location_failure_reason text default null,
  p_override_reason text default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_assignment public.vehicle_booking_assignments%rowtype;
  v_vehicle public.fleet_vehicle_profiles%rowtype;
  v_is_dispatcher boolean := false;
  v_requires_handover boolean := true;
  v_used_override boolean := false;
begin
  select * into v_booking from public.vehicle_bookings where id = p_booking_id for update;
  select * into v_assignment from public.vehicle_booking_assignments
  where booking_id = p_booking_id and is_active for update;

  if v_booking.id is null or v_assignment.id is null then
    raise exception using errcode = 'P0001', message = 'ASSIGNMENT_NOT_FOUND';
  end if;
  if v_booking.status <> 'ASSIGNED' or v_assignment.fulfillment_type = 'EXTERNAL_TRANSPORT' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;

  v_is_dispatcher := app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch');
  if v_assignment.operator_user_id is distinct from p_actor_user_id then
    if not v_is_dispatcher then
      perform app_private.vehicle_raise_permission_denied('Only assigned operator or dispatcher can start');
    end if;
    if nullif(trim(p_override_reason), '') is null then
      raise exception using errcode = 'P0001', message = 'OVERRIDE_REASON_REQUIRED';
    end if;
    v_used_override := true;
  end if;

  if v_assignment.operator_confirmation_status = 'DECLINED' then
    if not v_is_dispatcher or nullif(trim(p_override_reason), '') is null then
      raise exception using errcode = 'P0001', message = 'ASSIGNMENT_DECLINED';
    end if;
    v_used_override := true;
  elsif v_assignment.operator_confirmation_status = 'PENDING'
        and v_assignment.operator_user_id = p_actor_user_id then
    update public.vehicle_booking_assignments
    set operator_confirmation_status = 'CONFIRMED',
        operator_confirmed_at = now(),
        updated_at = now()
    where id = v_assignment.id;
  end if;

  if p_start_odometer is null then
    raise exception using errcode = 'P0001', message = 'ODOMETER_REQUIRED';
  end if;
  perform app_private.vehicle_assert_evidence_path(p_booking_id, p_start_photo_path, 'trips');

  if coalesce(p_location_capture_failed, false) then
    if nullif(trim(p_location_failure_reason), '') is null then
      raise exception using errcode = 'P0001', message = 'LOCATION_FAILURE_REASON_REQUIRED';
    end if;
  elsif p_latitude is null or p_longitude is null then
    raise exception using errcode = 'P0001', message = 'LOCATION_REQUIRED';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('vehicle:' || v_assignment.vehicle_asset_id, 0));
  select * into v_vehicle
  from public.fleet_vehicle_profiles
  where asset_id = v_assignment.vehicle_asset_id
  for update;

  if not found or not v_vehicle.active or v_vehicle.availability_status <> 'AVAILABLE' then
    raise exception using errcode = 'P0001', message = 'VEHICLE_UNAVAILABLE';
  end if;
  if v_vehicle.current_custody_assignment_id is not null
     and v_vehicle.current_custody_assignment_id <> v_assignment.id then
    raise exception using errcode = 'P0001', message = 'VEHICLE_IN_CUSTODY';
  end if;

  if p_start_odometer < v_vehicle.current_odometer then
    if not v_is_dispatcher or nullif(trim(p_override_reason), '') is null then
      raise exception using errcode = 'P0001', message = 'INVALID_ODOMETER_RANGE';
    end if;
    v_used_override := true;
  end if;

  select coalesce(settings.require_handover_for_self_drive, true)
  into v_requires_handover
  from public.fleet_system_settings settings
  where settings.id = 1;

  if v_assignment.fulfillment_type = 'INTERNAL_SELF_DRIVE'
     and v_requires_handover
     and not exists (
       select 1 from public.vehicle_handover_logs log
       where log.assignment_id = v_assignment.id
         and log.event_type = 'OUTBOUND_HANDOVER'
     ) then
    if not v_is_dispatcher or nullif(trim(p_override_reason), '') is null then
      raise exception using errcode = 'P0001', message = 'HANDOVER_REQUIRED';
    end if;
    v_used_override := true;
  end if;

  update public.fleet_vehicle_profiles
  set custody_status = 'IN_CUSTODY',
      current_custody_assignment_id = v_assignment.id,
      updated_at = now()
  where asset_id = v_assignment.vehicle_asset_id;

  update public.vehicle_trip_logs
  set trip_status = 'IN_PROGRESS',
      started_by_user_id = p_actor_user_id,
      departed_home_base_at = now(),
      start_odometer = p_start_odometer,
      start_photo_path = trim(p_start_photo_path),
      start_latitude = p_latitude,
      start_longitude = p_longitude,
      start_accuracy_m = p_accuracy_m,
      start_location_capture_failed = coalesce(p_location_capture_failed, false),
      start_location_failure_reason = nullif(trim(p_location_failure_reason), ''),
      updated_at = now()
  where booking_id = p_booking_id and trip_status = 'NOT_STARTED';
  if not found then
    raise exception using errcode = 'P0001', message = 'TRIP_LOG_NOT_FOUND';
  end if;

  update public.vehicle_bookings
  set status = 'IN_PROGRESS', updated_at = now()
  where id = p_booking_id;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    p_booking_id,
    case when v_used_override then 'TRIP_STARTED_OVERRIDE' else 'TRIP_STARTED' end,
    jsonb_build_object('status', v_booking.status),
    jsonb_build_object('status', 'IN_PROGRESS', 'start_odometer', p_start_odometer),
    'Bắt đầu chuyến xe'
  );
  return jsonb_build_object('success', true, 'status', 'IN_PROGRESS');
end;
$$","drop function if exists public.finish_vehicle_trip(uuid, numeric, text, numeric, numeric, numeric, boolean, text, text, text)","drop function if exists app_private.command_finish_vehicle_trip(uuid, uuid, numeric, text, numeric, numeric, numeric, boolean, text, text, text)","create or replace function app_private.command_finish_vehicle_trip(
  p_actor_user_id uuid,
  p_booking_id uuid,
  p_end_odometer numeric,
  p_end_photo_path text,
  p_latitude numeric default null,
  p_longitude numeric default null,
  p_accuracy_m numeric default null,
  p_location_capture_failed boolean default false,
  p_location_failure_reason text default null,
  p_vehicle_condition_end text default 'NORMAL',
  p_issue_note text default null,
  p_override_reason text default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_assignment public.vehicle_booking_assignments%rowtype;
  v_trip public.vehicle_trip_logs%rowtype;
  v_distance numeric(12, 1);
  v_is_dispatcher boolean := false;
begin
  select * into v_booking from public.vehicle_bookings where id = p_booking_id for update;
  select * into v_assignment from public.vehicle_booking_assignments
  where booking_id = p_booking_id and is_active for update;
  select * into v_trip from public.vehicle_trip_logs where booking_id = p_booking_id for update;

  if v_booking.id is null or v_assignment.id is null or v_trip.id is null then
    raise exception using errcode = 'P0001', message = 'TRIP_LOG_NOT_FOUND';
  end if;
  if v_booking.status <> 'IN_PROGRESS' or v_trip.trip_status <> 'IN_PROGRESS' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;

  v_is_dispatcher := app_private.vehicle_user_has_permission(p_actor_user_id, 'booking.vehicle.dispatch');
  if v_assignment.operator_user_id is distinct from p_actor_user_id then
    if not v_is_dispatcher then
      perform app_private.vehicle_raise_permission_denied('Only assigned operator or dispatcher can finish');
    end if;
    if nullif(trim(p_override_reason), '') is null then
      raise exception using errcode = 'P0001', message = 'OVERRIDE_REASON_REQUIRED';
    end if;
  end if;

  if p_end_odometer is null then
    raise exception using errcode = 'P0001', message = 'ODOMETER_REQUIRED';
  end if;
  if p_end_odometer < v_trip.start_odometer then
    raise exception using errcode = 'P0001', message = 'INVALID_ODOMETER_RANGE';
  end if;
  perform app_private.vehicle_assert_evidence_path(p_booking_id, p_end_photo_path, 'trips');

  if coalesce(p_location_capture_failed, false) then
    if nullif(trim(p_location_failure_reason), '') is null then
      raise exception using errcode = 'P0001', message = 'LOCATION_FAILURE_REASON_REQUIRED';
    end if;
  elsif p_latitude is null or p_longitude is null then
    raise exception using errcode = 'P0001', message = 'LOCATION_REQUIRED';
  end if;
  if p_vehicle_condition_end not in ('NORMAL', 'ISSUE') then
    raise exception using errcode = 'P0001', message = 'INVALID_VEHICLE_CONDITION';
  end if;
  if p_vehicle_condition_end = 'ISSUE' and nullif(trim(p_issue_note), '') is null then
    raise exception using errcode = 'P0001', message = 'ISSUE_NOTE_REQUIRED';
  end if;

  v_distance := p_end_odometer - v_trip.start_odometer;

  update public.vehicle_trip_logs
  set trip_status = 'FINISHED',
      finished_by_user_id = p_actor_user_id,
      actual_return_at = now(),
      end_odometer = p_end_odometer,
      end_photo_path = trim(p_end_photo_path),
      end_latitude = p_latitude,
      end_longitude = p_longitude,
      end_accuracy_m = p_accuracy_m,
      end_location_capture_failed = coalesce(p_location_capture_failed, false),
      end_location_failure_reason = nullif(trim(p_location_failure_reason), ''),
      distance_km = v_distance,
      vehicle_condition_end = p_vehicle_condition_end,
      issue_note = nullif(trim(p_issue_note), ''),
      updated_at = now()
  where id = v_trip.id;

  update public.fleet_vehicle_profiles
  set current_odometer = greatest(current_odometer, p_end_odometer),
      updated_at = now()
  where asset_id = v_assignment.vehicle_asset_id;

  update public.vehicle_bookings
  set status = 'COMPLETED', updated_at = now()
  where id = p_booking_id;

  if v_assignment.fulfillment_type = 'INTERNAL_WITH_DRIVER' then
    update public.fleet_vehicle_profiles
    set custody_status = 'AVAILABLE', current_custody_assignment_id = null, updated_at = now()
    where asset_id = v_assignment.vehicle_asset_id
      and current_custody_assignment_id = v_assignment.id;
    update public.vehicle_booking_assignments
    set released_at = coalesce(released_at, now()), updated_at = now()
    where id = v_assignment.id;
  end if;

  insert into public.vehicle_booking_feedback(booking_id, respondent_user_id, status)
  values (p_booking_id, v_booking.requester_user_id, 'PENDING')
  on conflict (booking_id) do nothing;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    p_booking_id,
    'TRIP_FINISHED',
    jsonb_build_object('status', v_booking.status),
    jsonb_build_object('status', 'COMPLETED', 'distance_km', v_distance),
    'Kết thúc chuyến xe'
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'TRIP_COMPLETED',
    v_booking.requester_user_id,
    jsonb_build_object('booking_code', v_booking.booking_code, 'distance_km', v_distance)
  );
  perform app_private.vehicle_enqueue_notification(
    p_booking_id,
    'VEHICLE_RETURN_REQUIRED',
    case when v_assignment.fulfillment_type = 'INTERNAL_SELF_DRIVE'
      then v_assignment.handover_officer_user_id else null end,
    jsonb_build_object('booking_code', v_booking.booking_code)
  );

  return jsonb_build_object('success', true, 'status', 'COMPLETED', 'distance_km', v_distance);
end;
