$$","do $command_privileges$
declare
  v_function record;
begin
  for v_function in
    select procedure.oid::regprocedure as signature
    from pg_proc procedure
    join pg_namespace namespace on namespace.oid = procedure.pronamespace
    where namespace.nspname = 'app_private'
      and procedure.proname like 'command\\_%vehicle%' escape '\\'
  loop
    execute format('revoke all on function %s from public, anon', v_function.signature);
    execute format('grant execute on function %s to authenticated', v_function.signature);
  end loop;
end;
$command_privileges$","revoke all on function public.reject_vehicle_booking(uuid, text) from public, anon","revoke all on function public.dispatch_vehicle_booking(uuid, text, text, uuid, uuid, boolean, text, text, text, text, text, text, numeric, text, text, text) from public, anon","revoke all on function public.reassign_vehicle_booking(uuid, text, text, text, uuid, uuid, boolean, text, text, text, text, text, text, numeric, text, text) from public, anon","revoke all on function public.respond_to_vehicle_assignment(uuid, text, text) from public, anon","revoke all on function public.confirm_vehicle_handover(uuid, text, text, text) from public, anon","revoke all on function public.record_vehicle_trip_checkpoint(uuid, text) from public, anon","revoke all on function public.start_vehicle_trip(uuid, numeric, text, numeric, numeric, numeric, boolean, text, text) from public, anon","revoke all on function public.finish_vehicle_trip(uuid, numeric, text, numeric, numeric, numeric, boolean, text, text, text, text) from public, anon","revoke all on function public.confirm_vehicle_return(uuid, text, text) from public, anon","revoke all on function public.complete_external_transport(uuid, numeric, text, text) from public, anon","revoke all on function public.submit_vehicle_feedback(uuid, boolean, integer, text[], text, text) from public, anon","revoke all on function public.cancel_vehicle_booking(uuid, text) from public, anon","revoke all on function public.mark_vehicle_booking_no_show(uuid, text) from public, anon","revoke all on function public.create_operator_unavailability(uuid, timestamptz, timestamptz, text, text) from public, anon","revoke all on function public.cancel_operator_unavailability(uuid, text) from public, anon","revoke all on function public.cancel_vehicle_unavailability(uuid, text) from public, anon","revoke all on function public.replace_vehicle_booking_participants(uuid, jsonb) from public, anon","grant execute on function public.reject_vehicle_booking(uuid, text) to authenticated","grant execute on function public.dispatch_vehicle_booking(uuid, text, text, uuid, uuid, boolean, text, text, text, text, text, text, numeric, text, text, text) to authenticated","grant execute on function public.reassign_vehicle_booking(uuid, text, text, text, uuid, uuid, boolean, text, text, text, text, text, text, numeric, text, text) to authenticated","grant execute on function public.respond_to_vehicle_assignment(uuid, text, text) to authenticated","grant execute on function public.confirm_vehicle_handover(uuid, text, text, text) to authenticated","grant execute on function public.record_vehicle_trip_checkpoint(uuid, text) to authenticated","grant execute on function public.start_vehicle_trip(uuid, numeric, text, numeric, numeric, numeric, boolean, text, text) to authenticated","grant execute on function public.finish_vehicle_trip(uuid, numeric, text, numeric, numeric, numeric, boolean, text, text, text, text) to authenticated","grant execute on function public.confirm_vehicle_return(uuid, text, text) to authenticated","grant execute on function public.complete_external_transport(uuid, numeric, text, text) to authenticated","grant execute on function public.submit_vehicle_feedback(uuid, boolean, integer, text[], text, text) to authenticated","grant execute on function public.cancel_vehicle_booking(uuid, text) to authenticated","grant execute on function public.mark_vehicle_booking_no_show(uuid, text) to authenticated","grant execute on function public.create_operator_unavailability(uuid, timestamptz, timestamptz, text, text) to authenticated","grant execute on function public.cancel_operator_unavailability(uuid, text) to authenticated","grant execute on function public.cancel_vehicle_unavailability(uuid, text) to authenticated","grant execute on function public.replace_vehicle_booking_participants(uuid, jsonb) to authenticated",commit}

{"-- Enable the Phase 2 dispatch read models for Supabase Realtime Postgres Changes.

do $$
declare
  v_table text;
begin
  foreach v_table in array array[
    'vehicle_bookings',
    'vehicle_booking_assignments',
    'fleet_vehicle_profiles',
    'vehicle_unavailability_periods',
    'operator_unavailability_periods'
  ] loop
    if not exists (
      select 1
      from pg_publication_tables published
      where published.pubname = 'supabase_realtime'
        and published.schemaname = 'public'
        and published.tablename = v_table
    ) then
      execute format('alter publication supabase_realtime add table public.%I', v_table);
    end if;
  end loop;
end;
$$"}

{"-- Vehicle Booking Phase 3C/3D operational commands and scoped timelines.

begin","create or replace function app_private.command_submit_vehicle_feedback(
  p_actor_user_id uuid,
  p_booking_id uuid,
  p_is_issue boolean,
  p_rating integer default null,
  p_positive_tags text[] default null,
  p_issue_category text default null,
  p_comment text default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_feedback public.vehicle_booking_feedback%rowtype;
  v_issue_id uuid;
begin
  if p_rating is null or p_rating not between 1 and 5 then
    raise exception using errcode = '22023', message = 'RATING_REQUIRED';
  end if;

  if exists (
    select 1
    from unnest(coalesce(p_positive_tags, array[]::text[])) tag
    where tag not in (
      'CLEAN_VEHICLE', 'COURTEOUS_DRIVER', 'ON_TIME', 'SAFE_DRIVING'
    )
  ) then
    raise exception using errcode = '22023', message = 'INVALID_POSITIVE_TAG';
  end if;

  if p_rating <= 3 and not p_is_issue then
    raise exception using errcode = '22023', message = 'LOW_RATING_REQUIRES_ISSUE';
  end if;

  if p_is_issue then
    if coalesce(p_issue_category, '') not in (
      'SAFETY', 'DRIVER_CONDUCT', 'VEHICLE_CONDITION',
      'SERVICE_DELAY', 'COST', 'OTHER'
    ) then
      raise exception using errcode = '22023', message = 'INVALID_ISSUE_CATEGORY';
    end if;
    if length(trim(coalesce(p_comment, ''))) not between 1 and 4000 then
      raise exception using errcode = '22023', message = 'ISSUE_COMMENT_INVALID';
    end if;
  end if;

  select * into v_booking
  from public.vehicle_bookings
  where id = p_booking_id
  for share;

  select * into v_feedback
  from public.vehicle_booking_feedback
  where booking_id = p_booking_id
  for update;

  if v_booking.id is null or v_feedback.id is null then
    raise exception using errcode = 'P0001', message = 'FEEDBACK_NOT_FOUND';
  end if;
  if v_booking.status <> 'COMPLETED' or v_feedback.status <> 'PENDING' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;
  if p_actor_user_id not in (
    v_booking.requester_user_id,
    coalesce(v_booking.trip_owner_user_id, v_booking.requester_user_id)
  ) then
    perform app_private.vehicle_raise_permission_denied(
      'Only requester or trip owner can submit feedback'
    );
  end if;

  if p_is_issue then
    insert into public.vehicle_booking_issues(
      booking_id, reporter_user_id, issue_category, comment
    ) values (
      p_booking_id, p_actor_user_id, p_issue_category, trim(p_comment)
    ) returning id into v_issue_id;

    update public.vehicle_booking_feedback
    set respondent_user_id = p_actor_user_id,
        status = 'ISSUE_REPORTED',
        rating = p_rating,
        positive_tags = coalesce(p_positive_tags, array[]::text[]),
        submitted_at = now(),
        updated_at = now()
    where id = v_feedback.id;

    perform app_private.vehicle_record_audit(
      p_actor_user_id,
      p_booking_id,
      'FEEDBACK_ISSUE_REPORTED',
      jsonb_build_object('status', v_feedback.status),
      jsonb_build_object(
        'status', 'ISSUE_REPORTED',
        'rating', p_rating,
        'issue_id', v_issue_id,
        'issue_category', p_issue_category
      ),
      'Ghi nhận phản ánh booking xe (nội dung đã ẩn)'
    );
  else
    update public.vehicle_booking_feedback
    set respondent_user_id = p_actor_user_id,
        status = 'CONFIRMED',
        rating = p_rating,
        positive_tags = coalesce(p_positive_tags, array[]::text[]),
        submitted_at = now(),
        updated_at = now()
    where id = v_feedback.id;

    perform app_private.vehicle_record_audit(
      p_actor_user_id,
      p_booking_id,
      'FEEDBACK_CONFIRMED',
      jsonb_build_object('status', v_feedback.status),
      jsonb_build_object('status', 'CONFIRMED', 'rating', p_rating),
      'Xác nhận dịch vụ chuyến xe'
    );
  end if;

  return jsonb_build_object(
    'success', true,
    'is_issue', p_is_issue,
    'issue_id', v_issue_id
  );
end;
$$","revoke all on function app_private.command_submit_vehicle_feedback(
  uuid, uuid, boolean, integer, text[], text, text
) from public, anon","grant execute on function app_private.command_submit_vehicle_feedback(
  uuid, uuid, boolean, integer, text[], text, text
) to authenticated",commit,begin,"create or replace function app_private.vehicle_require_audit_scope(
  p_actor_user_id uuid,
  p_department_id uuid
) returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_department_id is null then
    if not app_private.vehicle_user_has_scoped_permission(
      p_actor_user_id,
      'booking.vehicle.view_audit',
      'global',
      '*'
    ) then
      perform app_private.vehicle_raise_permission_denied(
        'Global vehicle audit permission required'
      );
    end if;
  elsif not (
    app_private.vehicle_user_has_scoped_permission(
      p_actor_user_id,
      'booking.vehicle.view_audit',
      'global',
      '*'
    )
    or app_private.vehicle_user_has_scoped_permission(
      p_actor_user_id,
      'booking.vehicle.view_audit',
      'department',
      p_department_id::text
    )
  ) then
    perform app_private.vehicle_raise_permission_denied(
      'Department vehicle audit permission required'
    );
  end if;
end;
$$","create or replace function public.get_vehicle_booking_audit_timeline(
  p_booking_id uuid default null,
  p_department_id uuid default null,
  p_event_type text default null,
  p_from_at timestamptz default null,
  p_to_at timestamptz default null,
  p_limit integer default 50,
  p_cursor_occurred_at timestamptz default null,
  p_cursor_id text default null
) returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100));
  v_effective_department_id uuid := p_department_id;
  v_booking_department_id uuid;
  v_rows jsonb := '[]'::jsonb;
  v_items jsonb := '[]'::jsonb;
  v_next_cursor jsonb := null;
begin
  if p_from_at is not null and p_to_at is not null and p_to_at <= p_from_at then
    raise exception using errcode = '22023', message = 'INVALID_AUDIT_PERIOD';
  end if;
  if p_event_type is not null and p_event_type not in (
    'BOOKING_EVENT', 'ASSIGNMENT_VERSION', 'HANDOVER'
  ) then
    raise exception using errcode = '22023', message = 'INVALID_AUDIT_EVENT_TYPE';
  end if;

  if p_booking_id is not null then
    select booking.department_id_snapshot
    into v_booking_department_id
    from public.vehicle_bookings booking
    where booking.id = p_booking_id;

    if not found then
      raise exception using errcode = 'P0001', message = 'BOOKING_NOT_FOUND';
    end if;
    if p_department_id is not null
       and p_department_id is distinct from v_booking_department_id then
      raise exception using errcode = '22023', message = 'BOOKING_DEPARTMENT_MISMATCH';
    end if;
    v_effective_department_id := v_booking_department_id;
  end if;

  perform app_private.vehicle_require_audit_scope(
    public.current_app_user_id(),
    v_effective_department_id
  );

  with timeline as (
    select
      'AUDIT:' || audit.id::text as synthetic_id,
      booking.id as booking_id,
      booking.booking_code,
      booking.department_id_snapshot as department_id,
      audit.created_at as occurred_at,
      'BOOKING_EVENT'::text as source_type,
      coalesce(audit.changes ->> 'event', audit.action) as event_type,
      coalesce(audit.description, audit.changes ->> 'event', audit.action) as title,
      coalesce(actor.name, actor.email, nullif(audit.user_name, '')) as actor_name,
      coalesce(audit.description, audit.action) as summary,
      jsonb_strip_nulls(jsonb_build_object(
        'oldStatus', audit.old_data ->> 'status',
        'newStatus', audit.new_data ->> 'status',
        'rating', audit.new_data ->> 'rating',
        'issueCategory', audit.new_data ->> 'issue_category',
        'approvalSource', audit.new_data ->> 'approval_source',
        'closeReason', audit.new_data ->> 'close_reason'
      )) as details
    from public.audit_trail audit
    join public.vehicle_bookings booking on booking.id::text = audit.record_id
    left join public.users actor on actor.id::text = audit.user_id
    where audit.module = 'VEHICLE_BOOKING'

    union all

    select
      'ASSIGNMENT:' || assignment.id::text,
      booking.id,
      booking.booking_code,
      booking.department_id_snapshot,
      assignment.assigned_at,
      'ASSIGNMENT_VERSION'::text,
      case when assignment.superseded_at is null
        then 'ASSIGNMENT_CREATED' else 'ASSIGNMENT_SUPERSEDED' end,
      'Phân công phiên bản ' || assignment.version::text,
      coalesce(actor.name, actor.email),
      case
        when assignment.superseded_at is null then 'Tạo phương án điều phối'
        else 'Thay đổi phương án điều phối'
      end,
      jsonb_strip_nulls(jsonb_build_object(
        'version', assignment.version,
        'fulfillmentType', assignment.fulfillment_type,
        'vehicleAssetId', assignment.vehicle_asset_id,
        'operatorUserId', assignment.operator_user_id,
        'supersedeReason', assignment.supersede_reason,
        'dispatchReasonCode', assignment.dispatch_reason_code
      ))
    from public.vehicle_booking_assignments assignment
    join public.vehicle_bookings booking on booking.id = assignment.booking_id
    left join public.users actor on actor.id = assignment.assigned_by_user_id

    union all

    select
      'HANDOVER:' || handover.id::text,
      booking.id,
      booking.booking_code,
      booking.department_id_snapshot,
      handover.confirmed_at,
      'HANDOVER'::text,
      handover.event_type,
      case handover.event_type
        when 'OUTBOUND_HANDOVER' then 'Bàn giao xe và chìa khóa'
        else 'Nhận lại xe và chìa khóa'
      end,
      coalesce(actor.name, actor.email),
      case handover.event_type
        when 'OUTBOUND_HANDOVER' then 'Xác nhận bàn giao xe tự lái'
        else 'Xác nhận nhận lại xe tự lái'
      end,
      jsonb_strip_nulls(jsonb_build_object(
        'assignmentVersion', handover.assignment_version_snapshot,
        'vehicleAssetId', handover.vehicle_asset_id_snapshot,
        'confirmedOnBehalf', handover.confirmed_on_behalf,
        'overrideReason', handover.override_reason,
        'note', handover.note
      ))
    from public.vehicle_handover_logs handover
    join public.vehicle_bookings booking on booking.id = handover.booking_id
    left join public.users actor on actor.id = handover.officer_user_id
  ), filtered_timeline as (
    select timeline.*
    from timeline
    where (p_booking_id is null or timeline.booking_id = p_booking_id)
      and (
        v_effective_department_id is null
        or timeline.department_id = v_effective_department_id
      )
      and (p_event_type is null or timeline.source_type = p_event_type)
      and (p_from_at is null or timeline.occurred_at >= p_from_at)
      and (p_to_at is null or timeline.occurred_at < p_to_at)
      and (
        p_cursor_occurred_at is null
        or (timeline.occurred_at, timeline.synthetic_id)
          < (p_cursor_occurred_at, p_cursor_id)
      )
    order by timeline.occurred_at desc, timeline.synthetic_id desc
    limit v_limit + 1
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'id', row.synthetic_id,
    'bookingId', row.booking_id,
    'bookingCode', row.booking_code,
    'occurredAt', row.occurred_at,
    'sourceType', row.source_type,
    'eventType', row.event_type,
    'title', row.title,
    'actorName', row.actor_name,
    'summary', row.summary,
    'details', row.details
  ) order by row.occurred_at desc, row.synthetic_id desc), '[]'::jsonb)
  into v_rows
  from filtered_timeline row;

  if jsonb_array_length(v_rows) > v_limit then
    v_items := v_rows - v_limit;
    v_next_cursor := jsonb_build_object(
      'occurredAt', v_items -> (v_limit - 1) ->> 'occurredAt',
      'id', v_items -> (v_limit - 1) ->> 'id'
    );
  else
    v_items := v_rows;
  end if;

  return jsonb_build_object('items', v_items, 'nextCursor', v_next_cursor);
end;
$$","revoke all on function app_private.vehicle_require_audit_scope(uuid, uuid)
  from public, anon, authenticated","revoke all on function public.get_vehicle_booking_audit_timeline(
  uuid, uuid, text, timestamptz, timestamptz, integer, timestamptz, text
) from public, anon","grant execute on function public.get_vehicle_booking_audit_timeline(
  uuid, uuid, text, timestamptz, timestamptz, integer, timestamptz, text
) to authenticated",commit,begin,"create or replace function app_private.vehicle_require_sensitive_issue_view(
  p_actor_user_id uuid
) returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not app_private.vehicle_user_has_permission(
    p_actor_user_id,
    'booking.vehicle.view_sensitive_feedback'
  ) then
    perform app_private.vehicle_raise_permission_denied(
      'Sensitive feedback view permission required'
    );
  end if;
end;
$$","create or replace function public.get_vehicle_booking_issues(
  p_status text default null,
  p_limit integer default 50,
  p_cursor_created_at timestamptz default null,
  p_cursor_id uuid default null
) returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_limit integer := greatest(1, least(coalesce(p_limit, 50), 100));
  v_rows jsonb := '[]'::jsonb;
  v_items jsonb := '[]'::jsonb;
  v_next_cursor jsonb := null;
begin
  perform app_private.vehicle_require_sensitive_issue_view(
    public.current_app_user_id()
  );

  if p_status is not null and p_status not in (
    'PENDING', 'IN_REVIEW', 'RESOLVED', 'DISMISSED'
  ) then
    raise exception using errcode = '22023', message = 'INVALID_ISSUE_STATUS';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', issue_rows.id,
    'bookingId', issue_rows.booking_id,
    'bookingCode', issue_rows.booking_code,
    'reporterUserId', issue_rows.reporter_user_id,
    'reporterName', issue_rows.reporter_name,
    'departmentName', issue_rows.department_name,
    'issueCategory', issue_rows.issue_category,
    'comment', issue_rows.comment,
    'rating', issue_rows.rating,
    'resolutionStatus', issue_rows.resolution_status,
    'resolutionNote', issue_rows.resolution_note,
    'resolvedByName', issue_rows.resolved_by_name,
    'resolvedAt', issue_rows.resolved_at,
    'createdAt', issue_rows.created_at
  ) order by issue_rows.created_at desc, issue_rows.id desc), '[]'::jsonb)
  into v_rows
  from (
    select
      issue.id,
      issue.booking_id,
      booking.booking_code,
      issue.reporter_user_id,
      coalesce(reporter.name, reporter.email, issue.reporter_user_id::text) as reporter_name,
      org.name as department_name,
      issue.issue_category,
      issue.comment,
      feedback.rating,
      issue.resolution_status,
      issue.resolution_note,
      coalesce(resolver.name, resolver.email) as resolved_by_name,
      issue.resolved_at,
      issue.created_at
    from public.vehicle_booking_issues issue
    join public.vehicle_bookings booking on booking.id = issue.booking_id
    left join public.vehicle_booking_feedback feedback
      on feedback.booking_id = issue.booking_id
    left join public.users reporter on reporter.id = issue.reporter_user_id
    left join public.users resolver on resolver.id = issue.resolved_by_user_id
    left join public.org_units org on org.id = booking.department_id_snapshot
    where (p_status is null or issue.resolution_status = p_status)
      and (
        p_cursor_created_at is null
        or (issue.created_at, issue.id) < (p_cursor_created_at, p_cursor_id)
      )
    order by issue.created_at desc, issue.id desc
    limit v_limit + 1
  ) issue_rows;

  if jsonb_array_length(v_rows) > v_limit then
    v_items := v_rows - v_limit;
    v_next_cursor := jsonb_build_object(
      'createdAt', v_items -> (v_limit - 1) ->> 'createdAt',
      'id', v_items -> (v_limit - 1) ->> 'id'
    );
  else
    v_items := v_rows;
  end if;

  return jsonb_build_object('items', v_items, 'nextCursor', v_next_cursor);
end;
$$","create or replace function app_private.command_transition_vehicle_booking_issue(
  p_actor_user_id uuid,
  p_issue_id uuid,
  p_target_status text,
  p_resolution_note text default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_issue public.vehicle_booking_issues%rowtype;
  v_booking public.vehicle_bookings%rowtype;
begin
  if not app_private.vehicle_user_has_permission(
    p_actor_user_id,
    'booking.vehicle.resolve_sensitive_feedback'
  ) then
    perform app_private.vehicle_raise_permission_denied(
      'Sensitive feedback resolution permission required'
    );
  end if;

  select * into v_issue
  from public.vehicle_booking_issues
  where id = p_issue_id
  for update;

  if v_issue.id is null then
    raise exception using errcode = 'P0001', message = 'ISSUE_NOT_FOUND';
  end if;

  if v_issue.resolution_status in ('RESOLVED', 'DISMISSED')
     and v_issue.resolution_status = p_target_status then
    return jsonb_build_object(
      'success', true,
      'status', v_issue.resolution_status,
      'idempotent', true
    );
  end if;

  if not (
    (v_issue.resolution_status = 'PENDING' and p_target_status = 'IN_REVIEW')
    or (
      v_issue.resolution_status = 'IN_REVIEW'
      and p_target_status in ('RESOLVED', 'DISMISSED')
    )
  ) then
    raise exception using errcode = 'P0001', message = 'INVALID_ISSUE_TRANSITION';
  end if;

  if p_target_status in ('RESOLVED', 'DISMISSED')
     and length(trim(coalesce(p_resolution_note, ''))) not between 1 and 4000 then
    raise exception using errcode = '22023', message = 'RESOLUTION_NOTE_INVALID';
  end if;

  update public.vehicle_booking_issues
  set resolution_status = p_target_status,
      resolution_note = case
        when p_target_status in ('RESOLVED', 'DISMISSED')
        then trim(p_resolution_note)
        else resolution_note
      end,
      resolved_by_user_id = case
        when p_target_status in ('RESOLVED', 'DISMISSED')
        then p_actor_user_id
        else null
      end,
      resolved_at = case
        when p_target_status in ('RESOLVED', 'DISMISSED')
        then now()
        else null
      end,
      updated_at = now()
  where id = p_issue_id;

  if p_target_status in ('RESOLVED', 'DISMISSED') then
    update public.vehicle_booking_feedback
    set status = 'RESOLVED', updated_at = now()
    where booking_id = v_issue.booking_id;
  end if;

  select * into v_booking
  from public.vehicle_bookings
  where id = v_issue.booking_id;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    v_issue.booking_id,
    'FEEDBACK_ISSUE_STATUS_CHANGED',
    jsonb_build_object('status', v_issue.resolution_status),
    jsonb_build_object(
      'status', p_target_status,
      'issue_id', v_issue.id,
      'issue_category', v_issue.issue_category
    ),
    'Cập nhật trạng thái phản ánh booking xe (nội dung đã ẩn)'
  );

  if p_target_status in ('RESOLVED', 'DISMISSED') then
    perform app_private.vehicle_enqueue_notification(
      v_issue.booking_id,
      'ISSUE_RESOLVED',
      v_issue.reporter_user_id,
      jsonb_build_object(
        'booking_code', v_booking.booking_code,
        'resolution_status', p_target_status
      )
    );
  end if;

  return jsonb_build_object(
    'success', true,
    'status', p_target_status,
    'idempotent', false
  );
end;
$$","create or replace function public.transition_vehicle_booking_issue(
  p_issue_id uuid,
  p_target_status text,
  p_resolution_note text default null
) returns jsonb
language sql
security invoker
set search_path = ''
as $$
  select app_private.command_transition_vehicle_booking_issue(
    public.current_app_user_id(),
    p_issue_id,
    p_target_status,
    p_resolution_note
  );
$$","revoke all on function app_private.vehicle_require_sensitive_issue_view(uuid)
  from public, anon, authenticated","revoke all on function app_private.command_transition_vehicle_booking_issue(
  uuid, uuid, text, text
) from public, anon","grant execute on function app_private.command_transition_vehicle_booking_issue(
  uuid, uuid, text, text
) to authenticated","revoke all on function public.get_vehicle_booking_issues(
  text, integer, timestamptz, uuid
) from public, anon","grant execute on function public.get_vehicle_booking_issues(
  text, integer, timestamptz, uuid
) to authenticated","revoke all on function public.transition_vehicle_booking_issue(uuid, text, text)
  from public, anon","grant execute on function public.transition_vehicle_booking_issue(uuid, text, text)
  to authenticated",commit}

{begin,"create or replace function app_private.get_fleet_vehicle_type_options_impl(
  p_actor_user_id uuid
) returns table (
  vehicle_type text,
  vehicle_count bigint
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_actor_user_id is distinct from public.current_app_user_id() then
    perform app_private.vehicle_raise_permission_denied('Actor mismatch');
  end if;

  if not (
    app_private.vehicle_user_has_permission(
      p_actor_user_id,
      'booking.vehicle.manage_authorizations'
    )
    or app_private.vehicle_user_has_permission(
      p_actor_user_id,
      'booking.vehicle.manage_fleet'
    )
    or app_private.vehicle_user_has_permission(
      p_actor_user_id,
      'booking.vehicle.dispatch'
    )
  ) then
    perform app_private.vehicle_raise_permission_denied(
      'Vehicle type catalog permission required'
    );
  end if;

  return query
  select
    trim(profile.vehicle_type),
    count(*)::bigint
  from public.fleet_vehicle_profiles profile
  where nullif(trim(profile.vehicle_type), '') is not null
  group by trim(profile.vehicle_type)
  order by trim(profile.vehicle_type);
end;
$$","create or replace function public.get_fleet_vehicle_type_options()
returns table (
  vehicle_type text,
  vehicle_count bigint
)
language sql
stable
security invoker
set search_path = ''
as $$
  select *
  from app_private.get_fleet_vehicle_type_options_impl(
    public.current_app_user_id()
  );
$$","create or replace function app_private.vehicle_assert_operator_eligible(
  p_operator_user_id uuid,
  p_authorization_type text,
  p_vehicle_type text
) returns void
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_authorization public.vehicle_driver_authorizations%rowtype;
begin
  if not exists (
    select 1
    from public.users app_user
    where app_user.id = p_operator_user_id
      and coalesce(app_user.is_active, true)
      and coalesce(app_user.account_status, 'ACTIVE') = 'ACTIVE'
  ) then
    raise exception using errcode = 'P0001', message = 'OPERATOR_UNAVAILABLE';
  end if;

  select *
  into v_authorization
  from public.vehicle_driver_authorizations authorization_row
  where authorization_row.user_id = p_operator_user_id
    and authorization_row.authorization_type = p_authorization_type;

  if not found or v_authorization.status <> 'ACTIVE' then
    raise exception using errcode = 'P0001', message = case
      when p_authorization_type = 'SELF_DRIVE' then 'SELF_DRIVER_NOT_AUTHORIZED'
      else 'DRIVER_NOT_AUTHORIZED'
    end;
  end if;

  if v_authorization.license_expiry < current_date then
    raise exception using errcode = 'P0001', message = 'DRIVER_LICENSE_EXPIRED';
  end if;

  if v_authorization.health_check_expiry_date is not null
     and v_authorization.health_check_expiry_date < current_date then
    raise exception using errcode = 'P0001', message = 'OPERATOR_UNAVAILABLE';
  end if;

  if v_authorization.allowed_vehicle_types is null
     or not (p_vehicle_type = any(v_authorization.allowed_vehicle_types)) then
    raise exception using errcode = 'P0001', message = 'DRIVER_VEHICLE_TYPE_MISMATCH';
  end if;
end;
$$","revoke all on function app_private.get_fleet_vehicle_type_options_impl(uuid)
  from public, anon","grant execute on function app_private.get_fleet_vehicle_type_options_impl(uuid)
  to authenticated","revoke all on function public.get_fleet_vehicle_type_options()
  from public, anon","grant execute on function public.get_fleet_vehicle_type_options()
  to authenticated","revoke all on function app_private.vehicle_assert_operator_eligible(uuid, text, text)
  from public, anon, authenticated",commit}

{"-- Human-readable Vehicle Booking assignment details and notification context.

begin","create or replace function app_private.get_vehicle_booking_assignment_display_impl(
  p_actor_user_id uuid,
  p_booking_id uuid
) returns table (
  assignment_id uuid,
  fulfillment_type text,
  vehicle_code text,
  vehicle_name text,
  vehicle_image_url text,
  operator_name text,
  operator_title text,
  operator_avatar_url text,
  external_provider_name text,
  external_driver_name text,
  external_vehicle_plate text
)
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if p_actor_user_id is distinct from public.current_app_user_id() then
    raise exception using errcode = '42501', message = 'VEHICLE_ACTOR_MISMATCH';
  end if;

  if not app_private.vehicle_user_can_view_booking(p_actor_user_id, p_booking_id) then
    raise exception using errcode = '42501', message = 'VEHICLE_BOOKING_ACCESS_DENIED';
  end if;

  return query
  select
    assignment.id,
    assignment.fulfillment_type,
    asset.code,
    asset.name,
    asset.image_url,
    coalesce(nullif(trim(employee.full_name), ''), nullif(trim(app_user.name), '')),
    nullif(trim(employee.title), ''),
    coalesce(nullif(trim(employee.avatar_url), ''), nullif(trim(app_user.avatar), '')),
    assignment.external_provider_name,
    assignment.external_driver_name,
    assignment.external_vehicle_plate
  from public.vehicle_booking_assignments assignment
  left join public.assets asset on asset.id = assignment.vehicle_asset_id
  left join public.users app_user on app_user.id = assignment.operator_user_id
  left join lateral (
    select employee_row.full_name, employee_row.title, employee_row.avatar_url
    from public.employees employee_row
    where employee_row.user_id = assignment.operator_user_id
    order by
      case when employee_row.status = 'Đang làm việc' then 0 else 1 end,
      employee_row.updated_at desc,
      employee_row.id
    limit 1
  ) employee on true
  where assignment.booking_id = p_booking_id
    and assignment.is_active
  order by assignment.version desc
  limit 1;
end;
$$","create or replace function public.get_vehicle_booking_assignment_display(
  p_booking_id uuid
) returns table (
  assignment_id uuid,
  fulfillment_type text,
  vehicle_code text,
  vehicle_name text,
  vehicle_image_url text,
  operator_name text,
  operator_title text,
  operator_avatar_url text,
  external_provider_name text,
  external_driver_name text,
  external_vehicle_plate text
)
language sql
stable
security invoker
set search_path = ''
as $$
  select *
  from app_private.get_vehicle_booking_assignment_display_impl(
    public.current_app_user_id(),
    p_booking_id
  );
$$","revoke all on function public.get_vehicle_booking_assignment_display(uuid) from public, anon, service_role","grant execute on function public.get_vehicle_booking_assignment_display(uuid) to authenticated","revoke all on function app_private.get_vehicle_booking_assignment_display_impl(uuid, uuid) from public, anon, service_role","grant execute on function app_private.get_vehicle_booking_assignment_display_impl(uuid, uuid) to authenticated","create or replace function app_private.build_vehicle_booking_notification_context(
  p_booking_id uuid,
  p_assignment_id uuid,
  p_recipient_user_id uuid,
  p_event_type text
) returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_assignment public.vehicle_booking_assignments%rowtype;
  v_requester_name text;
  v_driver_name text;
begin
  select booking.* into v_booking
  from public.vehicle_bookings booking
  where booking.id = p_booking_id;

  if not found then
    return null;
  end if;

  if p_assignment_id is not null then
    select assignment.* into v_assignment
    from public.vehicle_booking_assignments assignment
    where assignment.booking_id = p_booking_id
      and assignment.id = p_assignment_id;
  end if;

  if v_assignment.id is null
     and p_event_type = 'BOOKING_REASSIGNED_OLD_OPERATOR'
     and p_recipient_user_id is not null then
    select assignment.* into v_assignment
    from public.vehicle_booking_assignments assignment
    where assignment.booking_id = p_booking_id
      and not assignment.is_active
      and assignment.operator_user_id = p_recipient_user_id
      and assignment.superseded_at is not null
    order by assignment.superseded_at desc, assignment.version desc
    limit 1;
  end if;

  if v_assignment.id is null then
    select assignment.* into v_assignment
    from public.vehicle_booking_assignments assignment
    where assignment.booking_id = p_booking_id
      and assignment.is_active
    order by assignment.version desc
    limit 1;
  end if;

  select coalesce(
    nullif(trim(employee.full_name), ''),
    nullif(trim(app_user.name), ''),
    'Chưa có thông tin'
  ) into v_requester_name
  from public.users app_user
  left join lateral (
    select employee_row.full_name
    from public.employees employee_row
    where employee_row.user_id = app_user.id
    order by
      case when employee_row.status = 'Đang làm việc' then 0 else 1 end,
      employee_row.updated_at desc,
      employee_row.id
    limit 1
  ) employee on true
  where app_user.id = v_booking.requester_user_id;

  v_requester_name := coalesce(v_requester_name, 'Chưa có thông tin');

  if v_assignment.id is not null then
    if nullif(trim(v_assignment.external_driver_name), '') is not null then
      v_driver_name := trim(v_assignment.external_driver_name);
    elsif v_assignment.operator_user_id is not null then
      select coalesce(
        nullif(trim(employee.full_name), ''),
        nullif(trim(app_user.name), '')
      ) into v_driver_name
      from public.users app_user
      left join lateral (
        select employee_row.full_name
        from public.employees employee_row
        where employee_row.user_id = app_user.id
        order by
          case when employee_row.status = 'Đang làm việc' then 0 else 1 end,
          employee_row.updated_at desc,
          employee_row.id
        limit 1
      ) employee on true
      where app_user.id = v_assignment.operator_user_id;
    end if;
  end if;

  return jsonb_build_object(
    'booking_id', v_booking.id,
    'booking_code', v_booking.booking_code,
    'event_type', coalesce(nullif(trim(p_event_type), ''), 'BOOKING_UPDATED'),
    'requester_name', v_requester_name,
    'purpose', coalesce(nullif(trim(v_booking.purpose), ''), 'Chưa có nội dung'),
    'driver_name', coalesce(nullif(trim(v_driver_name), ''), 'Chưa phân công'),
    'pickup_location', coalesce(nullif(trim(v_booking.pickup_location_text), ''), 'Chưa có thông tin'),
    'destination', coalesce(nullif(trim(v_booking.destination_text), ''), 'Chưa có thông tin')
  );
end;
$$","revoke all on function app_private.build_vehicle_booking_notification_context(uuid, uuid, uuid, text) from public, anon, authenticated, service_role","create or replace function app_private.insert_vehicle_booking_notification(
  p_outbox_id uuid
) returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_outbox app_private.vehicle_booking_notification_outbox%rowtype;
  v_booking_id uuid;
  v_assignment_id uuid;
  v_context jsonb;
  v_purpose text;
  v_compact_purpose text;
  v_message text;
  v_notification_id uuid;
begin
  select outbox.* into v_outbox
  from app_private.vehicle_booking_notification_outbox outbox
  where outbox.id = p_outbox_id;

  if not found then
    raise exception using errcode = 'P0001', message = 'VEHICLE_NOTIFICATION_OUTBOX_NOT_FOUND';
  end if;

  if coalesce(v_outbox.payload ->> 'booking_id', '')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    v_booking_id := (v_outbox.payload ->> 'booking_id')::uuid;
  end if;

  if coalesce(v_outbox.payload ->> 'assignment_id', '')
       ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    v_assignment_id := (v_outbox.payload ->> 'assignment_id')::uuid;
  end if;

  v_context := app_private.build_vehicle_booking_notification_context(
    v_booking_id,
    v_assignment_id,
    v_outbox.recipient_user_id,
    v_outbox.event_type
  );

  if v_context is null then
    raise exception using errcode = 'P0001', message = 'VEHICLE_NOTIFICATION_BOOKING_NOT_FOUND';
  end if;

  v_purpose := v_context ->> 'purpose';
  v_compact_purpose := case
    when char_length(v_purpose) > 80 then left(v_purpose, 80) || '…'
    else v_purpose
  end;
  v_message := concat(
    'Người đặt: ', v_context ->> 'requester_name',
    ' · Nội dung: ', v_compact_purpose,
    ' · Tài xế: ', v_context ->> 'driver_name',
    ' · ', v_context ->> 'pickup_location',
    ' → ', v_context ->> 'destination'
  );

  insert into public.notifications(
    user_id, title, body, type, priority, module, link, metadata,
    category, message, severity, source_type, source_id,
    push_enabled, action_url, entity_type, entity_id
  ) values (
    v_outbox.recipient_user_id::text,
    app_private.vehicle_notification_title(v_outbox.event_type),
    v_message,
    'info', 'normal', 'VEHICLE_BOOKING',
    '/booking/vehicle/my?booking=' || v_booking_id,
    coalesce(v_outbox.payload, '{}'::jsonb)
      || v_context
      || jsonb_build_object('eventKey', v_outbox.event_key),
    'vehicle_booking', v_message, 'info', 'vehicle_booking',
    v_booking_id::text, true,
    '/booking/vehicle/my?booking=' || v_booking_id,
    'vehicle_booking', v_booking_id
  ) returning id into v_notification_id;

  return v_notification_id;
end;
$$","revoke all on function app_private.insert_vehicle_booking_notification(uuid) from public, anon, authenticated, service_role","create or replace function app_private.deliver_vehicle_notification(
  p_outbox_id uuid
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_outbox app_private.vehicle_booking_notification_outbox%rowtype;
  v_notification_id uuid;
begin
  perform app_private.require_vehicle_notification_worker();

  select * into v_outbox
  from app_private.vehicle_booking_notification_outbox
  where id = p_outbox_id
  for update;

  if not found or v_outbox.status = 'DELIVERED' then
    return jsonb_build_object('delivered', false);
  end if;
  if v_outbox.status <> 'PROCESSING' then
    raise exception using errcode = 'P0001', message = 'VEHICLE_NOTIFICATION_NOT_CLAIMED';
  end if;

  v_notification_id := app_private.insert_vehicle_booking_notification(v_outbox.id);

  update app_private.vehicle_booking_notification_outbox
  set status = 'DELIVERED', delivered_at = now(), locked_at = null,
      last_error = null, updated_at = now()
  where id = v_outbox.id;

  return jsonb_build_object('delivered', true, 'notificationId', v_notification_id);
end;
$$","create or replace function app_private.process_vehicle_notification_outbox(
  p_limit integer default 50
) returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_outbox record;
  v_processed integer := 0;
begin
  update app_private.vehicle_booking_notification_outbox outbox
  set status = 'FAILED', locked_at = null,
      last_error = 'Stale PROCESSING lease recovered', available_at = now(), updated_at = now()
  where outbox.status = 'PROCESSING'
    and outbox.locked_at < now() - interval '15 minutes'
    and outbox.attempt_count < 10;

  for v_outbox in
    select outbox.*
    from app_private.vehicle_booking_notification_outbox outbox
    where outbox.status in ('PENDING', 'FAILED')
      and outbox.attempt_count < 10
      and outbox.available_at <= now()
    order by outbox.available_at, outbox.id
    limit least(greatest(coalesce(p_limit, 50), 1), 100)
    for update skip locked
  loop
    begin
      update app_private.vehicle_booking_notification_outbox
      set status = 'PROCESSING', locked_at = now(),
          attempt_count = attempt_count + 1, updated_at = now()
      where id = v_outbox.id;

      perform app_private.insert_vehicle_booking_notification(v_outbox.id);

      update app_private.vehicle_booking_notification_outbox
      set status = 'DELIVERED', delivered_at = now(), locked_at = null,
          last_error = null, updated_at = now()
      where id = v_outbox.id;
      v_processed := v_processed + 1;
    exception when others then
      update app_private.vehicle_booking_notification_outbox
      set status = 'FAILED', locked_at = null, last_error = left(sqlerrm, 500),
          available_at = now() + interval '5 minutes', updated_at = now()
      where id = v_outbox.id;
    end;
  end loop;

  return v_processed;
end;
$$","create or replace function app_private.backfill_vehicle_booking_notification_context()
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_notification record;
  v_booking_text text;
  v_assignment_text text;
  v_recipient_text text;
  v_booking_id uuid;
  v_assignment_id uuid;
  v_recipient_user_id uuid;
  v_event_type text;
  v_context jsonb;
  v_purpose text;
  v_compact_purpose text;
  v_message text;
  v_updated bigint := 0;
begin
  for v_notification in
    select notification.id, notification.user_id, notification.source_id,
      notification.entity_id, notification.metadata
    from public.notifications notification
    where notification.category = 'vehicle_booking'
       or notification.source_type = 'vehicle_booking'
       or notification.entity_type = 'vehicle_booking'
  loop
    v_booking_id := null;
    v_assignment_id := null;
    v_recipient_user_id := null;
    v_context := null;

    v_booking_text := coalesce(
      nullif(v_notification.metadata ->> 'booking_id', ''),
      nullif(v_notification.metadata ->> 'bookingId', ''),
      nullif(v_notification.entity_id::text, ''),
      nullif(v_notification.source_id, '')
    );
    v_assignment_text := nullif(v_notification.metadata ->> 'assignment_id', '');
    v_recipient_text := nullif(v_notification.user_id, '');
    v_event_type := coalesce(
      nullif(v_notification.metadata ->> 'event_type', ''),
      nullif(v_notification.metadata ->> 'eventType', ''),
      'BOOKING_UPDATED'
    );

    if coalesce(v_booking_text, '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      v_booking_id := v_booking_text::uuid;
    end if;
    if coalesce(v_assignment_text, '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      v_assignment_id := v_assignment_text::uuid;
    end if;
    if coalesce(v_recipient_text, '')
         ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      v_recipient_user_id := v_recipient_text::uuid;
    end if;

    if v_booking_id is null then
      continue;
    end if;

    v_context := app_private.build_vehicle_booking_notification_context(
      v_booking_id,
      v_assignment_id,
      v_recipient_user_id,
      v_event_type
    );
    if v_context is null then
      continue;
    end if;

    v_purpose := v_context ->> 'purpose';
    v_compact_purpose := case
      when char_length(v_purpose) > 80 then left(v_purpose, 80) || '…'
      else v_purpose
    end;
    v_message := concat(
      'Người đặt: ', v_context ->> 'requester_name',
      ' · Nội dung: ', v_compact_purpose,
      ' · Tài xế: ', v_context ->> 'driver_name',
      ' · ', v_context ->> 'pickup_location',
      ' → ', v_context ->> 'destination'
    );

    update public.notifications notification
    set metadata = coalesce(notification.metadata, '{}'::jsonb) || v_context,
        message = v_message,
        body = v_message
    where notification.id = v_notification.id;

    v_updated := v_updated + 1;
  end loop;

  return v_updated;
end;
$$","revoke all on function app_private.backfill_vehicle_booking_notification_context() from public, anon, authenticated, service_role","select app_private.backfill_vehicle_booking_notification_context()",commit}

{"create or replace function app_private.can_act_on_subject_impl(
  p_subject_type text,
  p_subject_id text,
  p_action text
)
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_actor_user_id uuid := public.current_app_user_id();
  v_log public.daily_logs%rowtype;
  v_owner_id uuid;
  v_required_permission text;
  v_responsibilities text[];
begin
  if v_actor_user_id is null or not app_private.can_view_subject_impl(p_subject_type, p_subject_id) then
    return false;
  end if;

  if p_subject_type <> 'daily_log' then
    return false;
  end if;

  select * into v_log from public.daily_logs where id = p_subject_id;
  if not found then
    return false;
  end if;

  if p_action = 'view' then
    return true;
  end if;

  if p_action = 'submit' then
    select owner_user.id
    into v_owner_id
    from public.users owner_user
    where owner_user.id::text = coalesce(
      nullif(v_log.created_by_id, ''),
      nullif(v_log.submitted_by_id, ''),
      nullif(v_log.submitted_by, ''),
      nullif(v_log.created_by, '')
    )
    limit 1;

    return coalesce(v_log.status, 'draft') in ('draft', 'rejected')
      and (
        (
          v_owner_id = v_actor_user_id
          and app_private.daily_log_has_action(
            v_log.project_id::text,
            v_log.construction_site_id::text,
            'project.daily_log.submit',
            v_actor_user_id
          )
        )
        or (
          v_log.summary_source_type = 'member_contributions'
          and (
            app_private.daily_log_has_action(
              v_log.project_id::text,
              v_log.construction_site_id::text,
              'project.daily_log.summarize',
              v_actor_user_id
            )
            or app_private.daily_log_has_action(
              v_log.project_id::text,
              v_log.construction_site_id::text,
              'project.daily_log.submit',
              v_actor_user_id
            )
          )
        )
      );
  end if;

  if p_action = 'verify' then
    v_required_permission := 'project.daily_log.verify';
    v_responsibilities := array['current_verifier'];
  elsif p_action = 'approve' then
    v_required_permission := 'project.daily_log.approve';
    v_responsibilities := array['current_approver'];
  elsif p_action = 'return' then
    v_required_permission := 'project.daily_log.return';
    v_responsibilities := array['current_verifier', 'current_approver'];
  else
    return false;
  end if;

  return coalesce(v_log.status, 'draft') = 'submitted'
    and app_private.daily_log_has_action(
      v_log.project_id::text,
      v_log.construction_site_id::text,
      v_required_permission,
      v_actor_user_id
    )
    and app_private.daily_log_assignment_is_active(
      p_subject_id,
      v_actor_user_id,
      v_responsibilities,
      case when p_action = 'return' then null else v_required_permission end
    );
end;
$$","revoke all on function app_private.can_act_on_subject_impl(text, text, text)
  from public, anon, authenticated","notify pgrst, 'reload schema'"}

{begin,"create or replace function app_private.resolve_active_direct_manager(p_user_id uuid)
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select manager.id
  from public.users employee
  join public.users manager on manager.id = employee.manager_id
  where employee.id = p_user_id
    and manager.id <> p_user_id
    and coalesce(manager.is_active, true)
    and coalesce(manager.account_status, 'ACTIVE') = 'ACTIVE';
$$","create or replace function app_private.resolve_request_direct_manager(p_user_id uuid)
returns uuid
language sql
stable
security definer
set search_path = ''
as $$
  select app_private.resolve_active_direct_manager(p_user_id);
$$","create or replace function app_private.resolve_request_block_approvers(
  p_block_id uuid,
  p_creator_id uuid,
  p_dynamic_user_ids uuid[]
)
returns uuid[]
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_block public.request_approval_blocks%rowtype;
  v_source text;
  v_result uuid[] := '{}'::uuid[];
  v_ids uuid[] := '{}'::uuid[];
  v_id uuid;
  v_manager_id uuid;
  v_minimum integer;
begin
  select * into v_block
  from public.request_approval_blocks
  where id = p_block_id;
  if not found then
    raise exception using errcode = 'P0002', message = 'REQUEST_APPROVAL_BLOCK_NOT_FOUND';
  end if;

  v_source := v_block.approver_source;
  if v_source in ('FIXED_SINGLE', 'FIXED_MULTI') then
    v_ids := coalesce(v_block.fixed_user_ids, '{}'::uuid[]);
  elsif v_source = 'DIRECT_MANAGER' then
    v_manager_id := app_private.resolve_active_direct_manager(p_creator_id);
    if v_manager_id is null then
      raise exception using errcode = '22023', message = 'REQUEST_DIRECT_MANAGER_MISSING';
    end if;
    v_ids := array[v_manager_id];
  elsif v_source = 'DYNAMIC_CREATOR_SELECT' then
    v_ids := coalesce(p_dynamic_user_ids, '{}'::uuid[]);
    v_minimum := coalesce(v_block.minimum_dynamic_approvers, 1);
    if cardinality(v_ids) < v_minimum then
      raise exception using errcode = '22023', message = 'REQUEST_DYNAMIC_APPROVER_REQUIRED';
    end if;
  else
    raise exception using errcode = '22023', message = 'REQUEST_APPROVER_SOURCE_INVALID';
  end if;

  foreach v_id in array v_ids loop
    if v_id is null or v_id = any(v_result) then
      continue;
    end if;
    if v_id = p_creator_id then
      raise exception using errcode = '22023', message = 'REQUEST_APPROVER_SELF_NOT_ALLOWED';
    end if;
    if not exists (
      select 1
      from public.users app_user
      where app_user.id = v_id
        and coalesce(app_user.is_active, true)
        and coalesce(app_user.account_status, 'ACTIVE') = 'ACTIVE'
    ) then
      raise exception using errcode = '22023', message = 'REQUEST_APPROVER_INACTIVE';
    end if;
    v_result := array_append(v_result, v_id);
  end loop;

  if cardinality(v_result) = 0 then
    raise exception using errcode = '22023', message = 'REQUEST_APPROVER_REQUIRED';
  end if;
  if v_source = 'FIXED_SINGLE' and cardinality(v_result) <> 1 then
    raise exception using errcode = '22023', message = 'REQUEST_APPROVER_SINGLE_REQUIRED';
  end if;
  return v_result;
end;
$$","create or replace function app_private.enforce_request_approver_not_creator()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_creator_id uuid;
begin
  select request_instance.created_by
  into v_creator_id
  from public.request_instances request_instance
  where request_instance.workflow_subject_id = new.workflow_subject_id;

  if found and new.assignee_user_id = v_creator_id then
    raise exception using errcode = '22023', message = 'REQUEST_APPROVER_SELF_NOT_ALLOWED';
  end if;
  return new;
end;
$$","drop trigger if exists trg_request_approver_not_creator
  on public.workflow_step_assignments","create trigger trg_request_approver_not_creator
before insert or update of assignee_user_id
on public.workflow_step_assignments
for each row
execute function app_private.enforce_request_approver_not_creator()","revoke all on function app_private.resolve_active_direct_manager(uuid)
  from public, anon, authenticated","revoke all on function app_private.resolve_request_direct_manager(uuid)
  from public, anon, authenticated","revoke all on function app_private.resolve_request_block_approvers(uuid, uuid, uuid[])
  from public, anon","grant execute on function app_private.resolve_request_block_approvers(uuid, uuid, uuid[])
  to authenticated","revoke all on function app_private.enforce_request_approver_not_creator()
  from public, anon, authenticated","alter table public.fleet_system_settings
  add column if not exists require_direct_manager_approval boolean not null default true","alter table public.vehicle_bookings
  add column if not exists manager_approval_route text,
  add column if not exists manager_bypass_confirmed_by_user_id uuid
    references public.users(id) on delete set null,
  add column if not exists manager_bypass_confirmed_at timestamptz","do $vehicle_manager_route_constraint$
begin
  if not exists (
    select 1
    from pg_constraint
    where conrelid = 'public.vehicle_bookings'::regclass
      and conname = 'vehicle_bookings_manager_approval_route_check'
  ) then
    alter table public.vehicle_bookings
      add constraint vehicle_bookings_manager_approval_route_check
      check (
        manager_approval_route is null
        or manager_approval_route in (
          'MANAGER',
          'CONFIG_DISABLED',
          'MISSING_MANAGER_BYPASS',
          'LEGACY'
        )
      );
  end if;
end;
$vehicle_manager_route_constraint$","update public.vehicle_bookings
set manager_approval_route = 'LEGACY'
where status <> 'DRAFT'
  and manager_approval_route is null","create index if not exists idx_vehicle_bookings_manager_approval_route
  on public.vehicle_bookings(manager_approval_route, status)","create or replace function app_private.vehicle_active_dispatcher_count()
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select count(distinct grant_row.user_id)::integer
  from public.user_permission_grants grant_row
  join public.users app_user on app_user.id = grant_row.user_id
  where grant_row.permission_code = 'booking.vehicle.dispatch'
    and grant_row.scope_type = 'global'
    and grant_row.scope_id = '*'
    and grant_row.is_active
    and grant_row.revoked_at is null
    and (grant_row.expires_at is null or grant_row.expires_at > now())
    and coalesce(app_user.is_active, true)
    and coalesce(app_user.account_status, 'ACTIVE') = 'ACTIVE';
$$","create or replace function app_private.vehicle_enqueue_notification(
  p_booking_id uuid,
  p_event_type text,
  p_recipient_user_id uuid,
  p_payload jsonb default '{}'::jsonb
) returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  if p_recipient_user_id is null then
    return;
  end if;

  insert into app_private.vehicle_booking_notification_outbox (
    event_key,
    recipient_user_id,
    event_type,
    payload
  ) values (
    'vehicle:' || p_booking_id::text || ':' || p_event_type || ':' || p_recipient_user_id::text,
    p_recipient_user_id,
    coalesce(nullif(trim(p_event_type), ''), 'BOOKING_UPDATED'),
    coalesce(p_payload, '{}'::jsonb) || jsonb_build_object(
      'booking_id', p_booking_id,
      'event_type', coalesce(nullif(trim(p_event_type), ''), 'BOOKING_UPDATED')
    )
  ) on conflict (event_key, recipient_user_id) do nothing;
end;
$$","create or replace function app_private.vehicle_enqueue_dispatcher_notifications(
  p_booking_id uuid,
  p_event_type text,
  p_payload jsonb default '{}'::jsonb
) returns integer
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_recipient record;
  v_count integer := 0;
begin
  for v_recipient in
    select distinct grant_row.user_id
    from public.user_permission_grants grant_row
    join public.users app_user on app_user.id = grant_row.user_id
    where grant_row.permission_code = 'booking.vehicle.dispatch'
      and grant_row.scope_type = 'global'
      and grant_row.scope_id = '*'
      and grant_row.is_active
      and grant_row.revoked_at is null
      and (grant_row.expires_at is null or grant_row.expires_at > now())
      and coalesce(app_user.is_active, true)
      and coalesce(app_user.account_status, 'ACTIVE') = 'ACTIVE'
  loop
    perform app_private.vehicle_enqueue_notification(
      p_booking_id,
      p_event_type,
      v_recipient.user_id,
      p_payload
    );
    v_count := v_count + 1;
  end loop;
  return v_count;
end;
$$","create or replace function app_private.preview_vehicle_booking_submission_route_impl(
  p_actor_user_id uuid
) returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_requires_manager boolean := true;
  v_manager_user_id uuid;
  v_dispatcher_count integer := 0;
begin
  if p_actor_user_id is null
     or p_actor_user_id is distinct from public.current_app_user_id() then
    raise exception using errcode = '42501', message = 'VEHICLE_ACTOR_MISMATCH';
  end if;

  select coalesce(settings.require_direct_manager_approval, true)
  into v_requires_manager
  from public.fleet_system_settings settings
  where settings.id = 1;

  if not coalesce(v_requires_manager, true) then
    v_dispatcher_count := app_private.vehicle_active_dispatcher_count();
    if v_dispatcher_count = 0 then
      raise exception using errcode = '22023', message = 'VEHICLE_DISPATCHER_MISSING';
    end if;
    return jsonb_build_object(
      'route', 'CONFIG_DISABLED',
      'manager_user_id', null,
      'dispatcher_count', v_dispatcher_count
    );
  end if;

  v_manager_user_id := app_private.resolve_active_direct_manager(p_actor_user_id);
  if v_manager_user_id is not null then
    return jsonb_build_object(
      'route', 'MANAGER',
      'manager_user_id', v_manager_user_id,
      'dispatcher_count', app_private.vehicle_active_dispatcher_count()
    );
  end if;

  v_dispatcher_count := app_private.vehicle_active_dispatcher_count();
  if v_dispatcher_count = 0 then
    raise exception using errcode = '22023', message = 'VEHICLE_DISPATCHER_MISSING';
  end if;
  return jsonb_build_object(
    'route', 'MISSING_MANAGER_CONFIRMATION_REQUIRED',
    'manager_user_id', null,
    'dispatcher_count', v_dispatcher_count
  );
end;
$$","create or replace function public.preview_vehicle_booking_submission_route()
returns jsonb
language sql
stable
security invoker
set search_path = ''
as $$
  select app_private.preview_vehicle_booking_submission_route_impl(
    public.current_app_user_id()
  );
$$","drop function if exists public.submit_vehicle_booking(uuid)","drop function if exists app_private.command_submit_vehicle_booking(uuid, uuid)","create function app_private.command_submit_vehicle_booking(
  p_actor_user_id uuid,
  p_booking_id uuid,
  p_confirm_missing_manager_bypass boolean default false
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_booking public.vehicle_bookings%rowtype;
  v_requires_manager boolean := true;
  v_manager_user_id uuid;
  v_dispatcher_count integer := 0;
  v_route text;
  v_status text;
begin
  select booking.* into v_booking
  from public.vehicle_bookings booking
  where booking.id = p_booking_id
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'BOOKING_NOT_FOUND';
  end if;
  if v_booking.requester_user_id is distinct from p_actor_user_id
     and not app_private.vehicle_user_has_permission(
       p_actor_user_id,
       'booking.vehicle.admin'
     ) then
    perform app_private.vehicle_raise_permission_denied('Only requester can submit booking');
  end if;
  if v_booking.status <> 'DRAFT' then
    raise exception using errcode = 'P0001', message = 'INVALID_STATUS_TRANSITION';
  end if;

  select coalesce(settings.require_direct_manager_approval, true)
  into v_requires_manager
  from public.fleet_system_settings settings
  where settings.id = 1;

  if coalesce(v_requires_manager, true) then
    v_manager_user_id := app_private.resolve_active_direct_manager(
      v_booking.requester_user_id
    );
  end if;

  if not coalesce(v_requires_manager, true) then
    v_route := 'CONFIG_DISABLED';
    v_status := 'WAITING_DISPATCH';
  elsif v_manager_user_id is not null then
    v_route := 'MANAGER';
    v_status := 'PENDING_APPROVAL';
  elsif not coalesce(p_confirm_missing_manager_bypass, false) then
    raise exception using
      errcode = '22023',
      message = 'VEHICLE_DIRECT_MANAGER_CONFIRMATION_REQUIRED';
  else
    v_route := 'MISSING_MANAGER_BYPASS';
    v_status := 'WAITING_DISPATCH';
  end if;

  if v_status = 'WAITING_DISPATCH' then
    v_dispatcher_count := app_private.vehicle_active_dispatcher_count();
    if v_dispatcher_count = 0 then
      raise exception using errcode = '22023', message = 'VEHICLE_DISPATCHER_MISSING';
    end if;
  end if;

  update public.vehicle_bookings
  set status = v_status,
      submitted_at = now(),
      manager_user_id_snapshot = case when v_route = 'MANAGER' then v_manager_user_id else null end,
      manager_resolution_status = case
        when v_route = 'MISSING_MANAGER_BYPASS' then 'MISSING'
        else 'NORMAL'
      end,
      manager_approval_route = v_route,
      manager_bypass_confirmed_by_user_id = case
        when v_route = 'MISSING_MANAGER_BYPASS' then p_actor_user_id
        else null
      end,
      manager_bypass_confirmed_at = case
        when v_route = 'MISSING_MANAGER_BYPASS' then now()
        else null
      end,
      updated_at = now()
  where id = p_booking_id;

  perform app_private.vehicle_record_audit(
    p_actor_user_id,
    p_booking_id,
    case
      when v_route = 'MANAGER' then 'BOOKING_SUBMITTED_MANAGER'
      when v_route = 'CONFIG_DISABLED' then 'BOOKING_SUBMITTED_CONFIG_DISABLED'
      else 'BOOKING_SUBMITTED_MANAGER_BYPASS'
    end,
    jsonb_build_object('status', 'DRAFT'),
    jsonb_build_object(
      'status', v_status,
      'manager_approval_route', v_route,
      'manager_user_id_snapshot', v_manager_user_id
    ),
    'Gửi yêu cầu đặt xe'
  );

  if v_route = 'MANAGER' then
    perform app_private.vehicle_enqueue_notification(
      p_booking_id,
      'BOOKING_SUBMITTED',
      v_manager_user_id,
      jsonb_build_object('booking_code', v_booking.booking_code)
    );
  else
    perform app_private.vehicle_enqueue_dispatcher_notifications(
      p_booking_id,
      'BOOKING_WAITING_DISPATCH',
      jsonb_build_object(
        'booking_code', v_booking.booking_code,
        'manager_approval_route', v_route
      )
    );
  end if;

  return jsonb_build_object(
    'success', true,
    'status', v_status,
    'manager_approval_route', v_route,
    'manager_user_id', v_manager_user_id,
    'dispatcher_count', v_dispatcher_count
  );
end;
$$","create function public.submit_vehicle_booking(
  p_booking_id uuid,
  p_confirm_missing_manager_bypass boolean default false
) returns jsonb
language sql
security invoker
set search_path = ''
as $$
  select app_private.command_submit_vehicle_booking(
    public.current_app_user_id(),
    p_booking_id,
    p_confirm_missing_manager_bypass
  );
$$","drop function if exists public.update_fleet_system_settings(
  integer, integer, integer, integer, integer, numeric, integer, boolean, boolean
)","drop function if exists app_private.command_update_fleet_system_settings(
  uuid, integer, integer, integer, integer, integer, numeric, integer, boolean, boolean
)","create function app_private.command_update_fleet_system_settings(
  p_actor_user_id uuid,
  p_booking_buffer_minutes integer,
  p_late_cancellation_cutoff_minutes integer,
  p_feedback_auto_close_hours integer,
  p_home_base_warning_radius_meters integer,
  p_on_time_tolerance_minutes integer,
  p_max_evidence_image_mb numeric,
  p_trip_reminder_minutes integer default 60,
  p_require_handover_for_self_drive boolean default true,
  p_allow_dispatch_approval_override boolean default true,
  p_require_direct_manager_approval boolean default true
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not app_private.vehicle_user_has_permission(
    p_actor_user_id,
    'booking.vehicle.admin'
  ) then
    perform app_private.vehicle_raise_permission_denied(
      'Booking administrator permission required'
    );
  end if;

  update public.fleet_system_settings
  set booking_buffer_minutes = p_booking_buffer_minutes,
      late_cancellation_cutoff_minutes = p_late_cancellation_cutoff_minutes,
      feedback_auto_close_hours = p_feedback_auto_close_hours,
      home_base_warning_radius_meters = p_home_base_warning_radius_meters,
      on_time_tolerance_minutes = p_on_time_tolerance_minutes,
      max_evidence_image_mb = p_max_evidence_image_mb,
      trip_reminder_minutes = p_trip_reminder_minutes,
      require_handover_for_self_drive = p_require_handover_for_self_drive,
      allow_dispatch_approval_override = p_allow_dispatch_approval_override,
      require_direct_manager_approval = p_require_direct_manager_approval,
      updated_at = now()
  where id = 1;

  return jsonb_build_object('success', true);
end;
$$","create function public.update_fleet_system_settings(
