    'permissionCode', 'booking.vehicle.admin',
    'scopeType', 'global',
    'scopeId', '*'
  )),
  jsonb_build_object('source', 'request_vehicle_direct_manager_routing')
from seeded_booking_admins seeded","revoke all on function app_private.vehicle_active_dispatcher_count()
