for each row execute function app_private.guard_used_warehouse_project_reassignment()","drop function if exists public.create_warehouse_with_site_binding(text, text, text, text, uuid, boolean)","create or replace function public.create_warehouse_with_site_binding(
  p_warehouse_id text,
  p_name text,
  p_address text,
  p_type text,
  p_project_id text default null,
  p_construction_site_id uuid default null,
  p_is_default_for_site boolean default false
)
returns public.warehouses
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_warehouse public.warehouses%rowtype;
begin
  if not app_private.can_manage_warehouse_site_bindings() then
    raise exception 'Bạn không có quyền tạo và gán kho vào dự án.';
  end if;
  if nullif(btrim(p_warehouse_id), '') is null
     or nullif(btrim(p_name), '') is null
     or nullif(btrim(p_type), '') is null then
    raise exception 'Kho mới phải có mã, tên và loại kho.';
  end if;
  if p_type = 'SITE' and (p_project_id is null or p_construction_site_id is null) then
    raise exception 'Kho SITE phải chọn dự án và công trường.';
  end if;
  if coalesce(p_is_default_for_site, false)
     and (p_project_id is null or p_construction_site_id is null or p_type <> 'SITE') then
    raise exception 'Kho mặc định phải là kho SITE đã gắn dự án/công trường.';
  end if;
  if exists (select 1 from public.warehouses where id = p_warehouse_id) then
    raise exception 'Mã kho % đã tồn tại.', p_warehouse_id;
  end if;
  if coalesce(p_is_default_for_site, false) then
    update public.warehouses set is_default_for_site = false
    where construction_site_id = p_construction_site_id and is_default_for_site;
  end if;
  insert into public.warehouses(
    id, name, address, type, is_archived, project_id,
    construction_site_id, is_default_for_site
  ) values (
    p_warehouse_id, btrim(p_name), coalesce(p_address, ''), btrim(p_type), false,
    nullif(p_project_id, ''), p_construction_site_id, coalesce(p_is_default_for_site, false)
  ) returning * into v_warehouse;
  return v_warehouse;
end;
$$","drop function if exists public.set_warehouse_construction_site_binding(text, uuid, boolean, text, text, text)","create or replace function public.set_warehouse_construction_site_binding(
  p_warehouse_id text,
  p_project_id text,
  p_construction_site_id uuid,
  p_is_default_for_site boolean default false,
  p_name text default null,
  p_address text default null,
  p_type text default null
)
returns public.warehouses
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_warehouse public.warehouses%rowtype;
  v_next_type text;
begin
  if not app_private.can_manage_warehouse_site_bindings() then
    raise exception 'Bạn không có quyền gán kho vào dự án.';
  end if;
  select * into v_warehouse from public.warehouses
  where id = p_warehouse_id for update;
  if not found then raise exception 'Không tìm thấy kho %.', p_warehouse_id; end if;
  v_next_type := coalesce(nullif(btrim(p_type), ''), v_warehouse.type);
  if v_next_type = 'SITE' and (p_project_id is null or p_construction_site_id is null) then
    raise exception 'Kho SITE phải chọn dự án và công trường.';
  end if;
  if coalesce(p_is_default_for_site, false)
     and (p_project_id is null or p_construction_site_id is null or v_next_type <> 'SITE'
       or coalesce(v_warehouse.is_archived, false)) then
    raise exception 'Kho mặc định phải là kho SITE đã gắn dự án/công trường.';
  end if;
  if coalesce(p_is_default_for_site, false) then
    update public.warehouses set is_default_for_site = false
    where construction_site_id = p_construction_site_id
      and id <> p_warehouse_id and is_default_for_site;
  end if;
  update public.warehouses set
    name = coalesce(nullif(btrim(p_name), ''), name),
    address = coalesce(p_address, address),
    type = v_next_type,
    project_id = nullif(p_project_id, ''),
    construction_site_id = p_construction_site_id,
    is_default_for_site = coalesce(p_is_default_for_site, false)
  where id = p_warehouse_id
  returning * into v_warehouse;
  return v_warehouse;
end;
$$","revoke all on function public.create_warehouse_with_site_binding(text, text, text, text, text, uuid, boolean) from public, anon","grant execute on function public.create_warehouse_with_site_binding(text, text, text, text, text, uuid, boolean) to authenticated","revoke all on function public.set_warehouse_construction_site_binding(text, text, uuid, boolean, text, text, text) from public, anon","grant execute on function public.set_warehouse_construction_site_binding(text, text, uuid, boolean, text, text, text) to authenticated","create or replace function app_private.classify_wms_business_event(
  p_type text,
  p_source_type text,
  p_related_request_id text,
  p_items jsonb
)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when p_type = 'TRANSFER' then 'warehouse_transfer'
    when p_type = 'LIQUIDATION' then 'warehouse_loss'
    when p_type = 'ADJUSTMENT' then 'inventory_adjustment'
    when p_type = 'IMPORT' and exists (
      select 1 from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) line
      where nullif(line->>'materialIssueReturnId', '') is not null
    ) then 'project_return_receipt'
    when p_type = 'IMPORT' and lower(coalesce(p_source_type, '')) = 'site_direct_purchase'
      then 'site_hot_purchase_receipt'
    when p_type = 'IMPORT' and (
      lower(coalesce(p_source_type, '')) in ('supplier_direct_delivery_note', 'supplier_contract')
      or exists (
        select 1 from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) line
        where nullif(line->>'supplierDirectDeliveryNoteId', '') is not null
      )
    ) then 'direct_supplier_receipt'
    when p_type = 'IMPORT' and (
      lower(coalesce(p_source_type, '')) in ('po_delivery_batch', 'po_receipt')
      or exists (
        select 1 from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) line
        where nullif(line->>'purchaseOrderLineId', '') is not null
      )
    ) and (
      p_related_request_id is not null
      or exists (
        select 1 from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) line
        where nullif(line->>'materialRequestId', '') is not null
           or nullif(line->>'requestLineId', '') is not null
      )
    ) then 'request_po_receipt'
    when p_type = 'IMPORT' and lower(coalesce(p_source_type, '')) in ('po_delivery_batch', 'po_receipt')
      then 'proactive_po_receipt'
    when p_type = 'EXPORT' and exists (
      select 1 from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) line
      where nullif(line->>'materialIssueOrderId', '') is not null
        and nullif(line->>'materialIssueReturnId', '') is null
    ) then 'construction_issue'
    when p_type = 'EXPORT' and (
      lower(coalesce(p_source_type, '')) in ('supplier_return', 'purchase_order_supplier_return')
      or exists (
        select 1 from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) line
        where nullif(line->>'supplierReturnId', '') is not null
      )
    ) then 'supplier_return'
    else null
  end;
$$","create or replace function app_private.resolve_wms_business_event()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_derived text;
  v_warehouse_id text;
  v_scope record;
  v_line jsonb;
  v_payload_project_id text;
  v_payload_site_id text;
begin
  v_derived := app_private.classify_wms_business_event(
    new.type::text, new.source_type, new.related_request_id, new.items
  );
  new.business_event_type := coalesce(new.business_event_type, v_derived);

  if new.status::text = 'COMPLETED' then
    if new.business_event_type is null then
      raise exception 'Phiếu kho hoàn tất phải có mục đích nghiệp vụ.';
    end if;
    if new.business_event_type in ('direct_manual_receipt', 'warehouse_loss', 'inventory_adjustment')
       and nullif(btrim(coalesce(new.business_event_reason, new.note, '')), '') is null then
      raise exception 'Bắt buộc nhập lý do cho mục đích nghiệp vụ này.';
    end if;

    for v_line in select value from jsonb_array_elements(coalesce(new.items, '[]'::jsonb))
    loop
      v_warehouse_id := case
        when new.type::text in ('EXPORT', 'LIQUIDATION') then new.source_warehouse_id
        when new.type::text = 'ADJUSTMENT' then coalesce(new.target_warehouse_id, new.source_warehouse_id)
        else new.target_warehouse_id
      end;
      select * into v_scope from app_private.resolve_warehouse_project_scope(v_warehouse_id);
      v_payload_project_id := nullif(coalesce(v_line->>'projectId', v_line->>'project_id'), '');
      v_payload_site_id := nullif(coalesce(v_line->>'constructionSiteId', v_line->>'construction_site_id'), '');
      if (v_payload_project_id is not null and v_payload_project_id is distinct from v_scope.project_id)
         or (v_payload_site_id is not null and v_payload_site_id is distinct from v_scope.construction_site_id) then
        raise exception 'Scope chứng từ không khớp scope kho.';
      end if;
    end loop;
  end if;
  return new;
end;
$$","revoke all on function app_private.classify_wms_business_event(text, text, text, jsonb) from public, anon, authenticated","revoke all on function app_private.resolve_wms_business_event() from public, anon, authenticated","-- Historical documents are classified, but unknown direct issues remain legacy
-- and are never converted to consume events.
update public.transactions transaction_row
set business_event_type = coalesce(
  app_private.classify_wms_business_event(
    transaction_row.type::text,
    transaction_row.source_type,
    transaction_row.related_request_id,
    transaction_row.items
  ),
  case
    when transaction_row.type::text = 'IMPORT' then 'legacy_direct_receipt'
    when transaction_row.type::text = 'EXPORT' then 'legacy_direct_issue'
    when transaction_row.type::text = 'TRANSFER' then 'warehouse_transfer'
    when transaction_row.type::text = 'LIQUIDATION' then 'warehouse_loss'
    when transaction_row.type::text = 'ADJUSTMENT' then 'inventory_adjustment'
    else null
  end
)
where transaction_row.business_event_type is null","drop trigger if exists trg_resolve_wms_business_event on public.transactions","create trigger trg_resolve_wms_business_event
before insert or update of status, type, items, source_type, related_request_id, business_event_type
on public.transactions
for each row execute function app_private.resolve_wms_business_event()","create or replace function app_private.sync_wms_transaction_to_inventory_ledger(p_transaction_id text)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_tx public.transactions%rowtype;
  v_existing_id uuid;
  v_inventory_transaction_id uuid;
  v_has_in boolean := false;
  v_has_out boolean := false;
  v_in_code text;
  v_out_code text;
  v_header_code text;
  v_header_type text;
  v_line jsonb;
  v_entry_no integer := 0;
  v_tx_date timestamptz;
  v_item_id text;
  v_qty numeric;
  v_price numeric;
  v_source_line_id text;
  v_metadata jsonb;
  v_event_type text;
  v_entry_type text;
  v_warehouse_id text;
  v_scope record;
  v_payload_project_id text;
  v_payload_site_id text;
  v_header_project_id text;
  v_header_site_id text;
begin
  select * into v_tx
  from public.transactions
  where id = p_transaction_id
  for update;
  if not found then raise exception 'transaction not found: %', p_transaction_id; end if;
  if v_tx.status::text <> 'COMPLETED' then return null; end if;

  select id into v_existing_id
  from public.inventory_transactions
  where source_type = 'wms_transaction' and source_id = v_tx.id
  limit 1;
  if v_existing_id is not null then return v_existing_id; end if;

  v_event_type := coalesce(
    v_tx.business_event_type,
    app_private.classify_wms_business_event(
      v_tx.type::text, v_tx.source_type, v_tx.related_request_id, v_tx.items
    )
  );
  if v_event_type is null then
    raise exception 'Phiếu kho hoàn tất phải có mục đích nghiệp vụ.';
  end if;
  v_tx_date := coalesce(nullif(v_tx.date::text, '')::timestamptz, now());
  v_has_in := (
    v_tx.type::text in ('IMPORT', 'TRANSFER')
    and exists (
      select 1 from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb)) item(value)
      where coalesce(nullif(item.value->>'quantity', '')::numeric, 0) > 0
    )
  ) or exists (
    select 1 from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb)) item(value)
    where v_tx.type::text = 'ADJUSTMENT'
      and coalesce(nullif(item.value->>'quantity', '')::numeric, 0) > 0
  );
  v_has_out := (
    v_tx.type::text in ('EXPORT', 'TRANSFER', 'LIQUIDATION')
    and exists (
      select 1 from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb)) item(value)
      where coalesce(nullif(item.value->>'quantity', '')::numeric, 0) > 0
    )
  ) or exists (
    select 1 from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb)) item(value)
    where v_tx.type::text = 'ADJUSTMENT'
      and coalesce(nullif(item.value->>'quantity', '')::numeric, 0) < 0
  );
  if not v_has_in and not v_has_out then return null; end if;

  if v_has_in then v_in_code := app_private.next_inventory_ledger_code('in'); end if;
  if v_has_out then v_out_code := app_private.next_inventory_ledger_code('out'); end if;
  v_header_code := coalesce(v_out_code, v_in_code);
  v_header_type := case
    when v_event_type = 'project_return_receipt' then 'project_return_receipt'
    when v_tx.type::text = 'TRANSFER' and v_has_out then 'transfer_issue'
    when v_tx.type::text = 'IMPORT' then 'purchase_receipt'
    when v_tx.type::text = 'EXPORT' then 'project_issue'
    when v_tx.type::text = 'LIQUIDATION' then 'loss_issue'
    when v_tx.type::text = 'ADJUSTMENT' and v_has_in then 'adjustment_in'
    else 'adjustment_out'
  end;

  v_metadata := jsonb_build_object(
    'wmsTransactionId', v_tx.id,
    'wmsType', v_tx.type::text,
    'wmsStatus', v_tx.status::text,
    'businessEventType', v_event_type,
    'businessEventReason', v_tx.business_event_reason,
    'sourceWarehouseId', v_tx.source_warehouse_id,
    'targetWarehouseId', v_tx.target_warehouse_id,
    'supplierId', v_tx.supplier_id,
    'items', coalesce(v_tx.items, '[]'::jsonb)
  );

  insert into public.inventory_transactions(
    code, transaction_type, status, transaction_date,
    source_type, source_id, source_code, related_request_id,
    project_id, construction_site_id, business_event_type,
    description, metadata, created_by, approved_by, posted_at
  ) values (
    v_header_code, v_header_type, 'posted', v_tx_date,
    'wms_transaction', v_tx.id, v_tx.id, v_tx.related_request_id,
    null, null, v_event_type,
    v_tx.note, v_metadata, v_tx.requester_id, v_tx.approver_id, now()
  ) returning id into v_inventory_transaction_id;

  for v_line in select value from jsonb_array_elements(coalesce(v_tx.items, '[]'::jsonb))
  loop
    v_item_id := v_line->>'itemId';
    v_qty := coalesce(nullif(v_line->>'quantity', '')::numeric, 0);
    v_price := coalesce(nullif(v_line->>'price', '')::numeric, 0);
    v_source_line_id := nullif(coalesce(
      v_line->>'requestLineId', v_line->>'materialIssueLineId', v_line->>'lineId'
    ), '');
    if v_item_id is null then raise exception 'invalid transaction item payload'; end if;
    if v_qty = 0 then continue; end if;

    if v_tx.type::text = 'IMPORT' then
      if v_qty < 0 then raise exception 'invalid import quantity'; end if;
      v_warehouse_id := v_tx.target_warehouse_id;
      v_entry_type := case when v_event_type = 'project_return_receipt'
        then 'project_return_receipt' else 'purchase_receipt' end;
      select * into v_scope from app_private.resolve_warehouse_project_scope(v_warehouse_id);
      v_payload_project_id := nullif(coalesce(v_line->>'projectId', v_line->>'project_id'), '');
      v_payload_site_id := nullif(coalesce(v_line->>'constructionSiteId', v_line->>'construction_site_id'), '');
      if (v_payload_project_id is not null and v_payload_project_id is distinct from v_scope.project_id)
         or (v_payload_site_id is not null and v_payload_site_id is distinct from v_scope.construction_site_id) then
        raise exception 'Scope chứng từ không khớp scope kho.';
      end if;
      v_entry_no := v_entry_no + 1;
      perform app_private.post_inventory_ledger_entry(
        v_inventory_transaction_id, v_entry_no, v_in_code, v_tx_date,
        v_entry_type, 'in', v_item_id, v_warehouse_id,
        v_scope.project_id, v_scope.construction_site_id,
        'wms_transaction', v_tx.id, v_tx.id, v_source_line_id, v_tx.related_request_id,
        v_qty, v_price, v_tx.note,
        v_line || jsonb_build_object('businessEventType', v_event_type),
        v_tx.requester_id, v_tx.approver_id
      );
    elsif v_tx.type::text = 'EXPORT' then
      if v_qty < 0 then raise exception 'invalid export quantity'; end if;
      v_warehouse_id := v_tx.source_warehouse_id;
      select * into v_scope from app_private.resolve_warehouse_project_scope(v_warehouse_id);
      v_entry_no := v_entry_no + 1;
      perform app_private.post_inventory_ledger_entry(
        v_inventory_transaction_id, v_entry_no, v_out_code, v_tx_date,
        'project_issue', 'out', v_item_id, v_warehouse_id,
        v_scope.project_id, v_scope.construction_site_id,
        'wms_transaction', v_tx.id, v_tx.id, v_source_line_id, v_tx.related_request_id,
        v_qty, v_price, v_tx.note,
        v_line || jsonb_build_object('businessEventType', v_event_type),
        v_tx.requester_id, v_tx.approver_id
      );
    elsif v_tx.type::text = 'TRANSFER' then
      if v_qty < 0 then raise exception 'invalid transfer quantity'; end if;
      select * into v_scope from app_private.resolve_warehouse_project_scope(v_tx.source_warehouse_id);
      v_entry_no := v_entry_no + 1;
      perform app_private.post_inventory_ledger_entry(
        v_inventory_transaction_id, v_entry_no, v_out_code, v_tx_date,
        'transfer_issue', 'out', v_item_id, v_tx.source_warehouse_id,
        v_scope.project_id, v_scope.construction_site_id,
        'wms_transaction', v_tx.id, v_tx.id, v_source_line_id, v_tx.related_request_id,
        v_qty, v_price, v_tx.note,
        v_line || jsonb_build_object('businessEventType', v_event_type),
        v_tx.requester_id, v_tx.approver_id
      );
      select * into v_scope from app_private.resolve_warehouse_project_scope(v_tx.target_warehouse_id);
      v_entry_no := v_entry_no + 1;
      perform app_private.post_inventory_ledger_entry(
        v_inventory_transaction_id, v_entry_no, v_in_code, v_tx_date,
        'transfer_receipt', 'in', v_item_id, v_tx.target_warehouse_id,
        v_scope.project_id, v_scope.construction_site_id,
        'wms_transaction', v_tx.id, v_tx.id, v_source_line_id, v_tx.related_request_id,
        v_qty, v_price, v_tx.note,
        v_line || jsonb_build_object('businessEventType', v_event_type),
        v_tx.requester_id, v_tx.approver_id
      );
    elsif v_tx.type::text = 'LIQUIDATION' then
      if v_qty < 0 then raise exception 'invalid liquidation quantity'; end if;
      select * into v_scope from app_private.resolve_warehouse_project_scope(v_tx.source_warehouse_id);
      v_entry_no := v_entry_no + 1;
      perform app_private.post_inventory_ledger_entry(
        v_inventory_transaction_id, v_entry_no, v_out_code, v_tx_date,
        'loss_issue', 'out', v_item_id, v_tx.source_warehouse_id,
        v_scope.project_id, v_scope.construction_site_id,
        'wms_transaction', v_tx.id, v_tx.id, v_source_line_id, v_tx.related_request_id,
        v_qty, v_price, v_tx.note,
        v_line || jsonb_build_object('businessEventType', v_event_type),
        v_tx.requester_id, v_tx.approver_id
      );
    elsif v_tx.type::text = 'ADJUSTMENT' then
      v_warehouse_id := coalesce(v_tx.target_warehouse_id, v_tx.source_warehouse_id);
      select * into v_scope from app_private.resolve_warehouse_project_scope(v_warehouse_id);
      v_entry_no := v_entry_no + 1;
      perform app_private.post_inventory_ledger_entry(
        v_inventory_transaction_id, v_entry_no,
        case when v_qty > 0 then v_in_code else v_out_code end,
        v_tx_date,
        case when v_qty > 0 then 'adjustment_in' else 'adjustment_out' end,
        case when v_qty > 0 then 'in' else 'out' end,
        v_item_id, v_warehouse_id, v_scope.project_id, v_scope.construction_site_id,
        'wms_transaction', v_tx.id, v_tx.id, v_source_line_id, v_tx.related_request_id,
        abs(v_qty), v_price, v_tx.note,
        v_line || jsonb_build_object('businessEventType', v_event_type),
        v_tx.requester_id, v_tx.approver_id
      );
    end if;
  end loop;

  if v_entry_no = 0 then
    delete from public.inventory_transactions where id = v_inventory_transaction_id;
    return null;
  end if;

  update public.inventory_ledger_entries
  set business_event_type = v_event_type
  where inventory_transaction_id = v_inventory_transaction_id;

  select
    case when count(distinct coalesce(entry.project_id, '<null>')) = 1
      then max(entry.project_id) else null end,
    case when count(distinct coalesce(entry.construction_site_id, '<null>')) = 1
      then max(entry.construction_site_id) else null end
  into v_header_project_id, v_header_site_id
  from public.inventory_ledger_entries entry
  where entry.inventory_transaction_id = v_inventory_transaction_id;

  update public.inventory_transactions set
    project_id = v_header_project_id,
    construction_site_id = v_header_site_id,
    business_event_type = v_event_type
  where id = v_inventory_transaction_id;

  return v_inventory_transaction_id;
end;
$$","revoke all on function app_private.sync_wms_transaction_to_inventory_ledger(text) from public, anon, authenticated","-- Snapshot current physical balances before changing only their reporting scope.
create temporary table v1_balance_before on commit drop as
select balance.warehouse_id, balance.material_id,
  sum(balance.on_hand_qty) as on_hand_qty,
  sum(balance.total_value) as total_value
from public.inventory_balances balance
group by balance.warehouse_id, balance.material_id","update public.inventory_ledger_entries entry
set project_id = warehouse.project_id,
    construction_site_id = warehouse.construction_site_id::text
from public.warehouses warehouse
where warehouse.id = entry.warehouse_id
  and (entry.project_id is distinct from warehouse.project_id
    or entry.construction_site_id is distinct from warehouse.construction_site_id::text)","update public.inventory_ledger_entries entry
set business_event_type = transaction_row.business_event_type
from public.transactions transaction_row
where entry.source_type = 'wms_transaction'
  and transaction_row.id = entry.source_id
  and entry.business_event_type is null","update public.inventory_ledger_entries entry
set business_event_type = case
  when entry.transaction_type in ('transfer_receipt', 'transfer_issue') then 'warehouse_transfer'
  when entry.transaction_type = 'project_return_receipt' then 'project_return_receipt'
  when entry.transaction_type = 'loss_issue' then 'warehouse_loss'
  when entry.transaction_type in ('adjustment_in', 'adjustment_out') then 'inventory_adjustment'
  when entry.movement_direction = 'in' then 'legacy_direct_receipt'
  else 'legacy_direct_issue'
end
where entry.business_event_type is null","update public.inventory_balances balance
set project_id = warehouse.project_id,
    construction_site_id = warehouse.construction_site_id::text
from public.warehouses warehouse
where warehouse.id = balance.warehouse_id","update public.inventory_transactions inventory_transaction
set business_event_type = transaction_row.business_event_type
from public.transactions transaction_row
where inventory_transaction.source_type = 'wms_transaction'
  and transaction_row.id = inventory_transaction.source_id","with header_scope as (
  select entry.inventory_transaction_id,
    case when count(distinct coalesce(entry.project_id, '<null>')) = 1
      then max(entry.project_id) else null end as project_id,
    case when count(distinct coalesce(entry.construction_site_id, '<null>')) = 1
      then max(entry.construction_site_id) else null end as construction_site_id
  from public.inventory_ledger_entries entry
  group by entry.inventory_transaction_id
)
update public.inventory_transactions inventory_transaction
set project_id = header_scope.project_id,
    construction_site_id = header_scope.construction_site_id
from header_scope
where header_scope.inventory_transaction_id = inventory_transaction.id","update public.material_issue_orders issue_order
set project_id = warehouse.project_id,
    construction_site_id = warehouse.construction_site_id::text
from public.warehouses warehouse
where warehouse.id = issue_order.source_warehouse_id","update public.material_party_ledger party_entry
set project_id = issue_order.project_id,
    construction_site_id = issue_order.construction_site_id
from public.material_issue_orders issue_order
where issue_order.id = party_entry.issue_order_id","do $$
declare
  v_balance_mismatch_count integer;
  v_unscoped_site_entries integer;
begin
  select count(*) into v_balance_mismatch_count
  from (
    select coalesce(before_row.warehouse_id, after_row.warehouse_id) as warehouse_id,
      coalesce(before_row.material_id, after_row.material_id) as material_id
    from v1_balance_before before_row
    full join (
      select balance.warehouse_id, balance.material_id,
        sum(balance.on_hand_qty) as on_hand_qty,
        sum(balance.total_value) as total_value
      from public.inventory_balances balance
      group by balance.warehouse_id, balance.material_id
    ) after_row using (warehouse_id, material_id)
    where coalesce(before_row.on_hand_qty, 0) <> coalesce(after_row.on_hand_qty, 0)
       or coalesce(before_row.total_value, 0) <> coalesce(after_row.total_value, 0)
  ) mismatch;
  if v_balance_mismatch_count > 0 then
    raise exception 'V1 cut-over stopped: % warehouse/material balances changed.', v_balance_mismatch_count;
  end if;

  select count(*) into v_unscoped_site_entries
  from public.inventory_ledger_entries entry
  join public.warehouses warehouse on warehouse.id = entry.warehouse_id
  where warehouse.type = 'SITE'
    and not coalesce(warehouse.is_archived, false)
    and (entry.project_id is null or entry.construction_site_id is null);
  if v_unscoped_site_entries > 0 then
    raise exception 'V1 cut-over stopped: % SITE ledger entries remain unscoped.', v_unscoped_site_entries;
  end if;
end $$","notify pgrst, 'reload schema'"}

{"-- Preserve the approver route for returned Daily Log summaries and prevent
-- deleting legacy source logs while a materialized summary still references them.

create or replace function app_private.daily_log_target_permission(
  p_summary_source_type text,
  p_submitted_to_permission text
)
returns text
language sql
immutable
set search_path = ''
as $$
  select case
    when p_summary_source_type = 'member_contributions'
      or p_submitted_to_permission = 'approve'
    then 'project.daily_log.approve'
    else 'project.daily_log.verify'
  end;
$$","revoke all on function app_private.daily_log_target_permission(text, text)
  from public, anon, authenticated","create or replace function app_private.preserve_daily_log_summary_approval_route()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if app_private.daily_log_target_permission(
    new.summary_source_type,
    new.submitted_to_permission
  ) = 'project.daily_log.approve' then
    new.submitted_to_permission := 'approve';
  end if;
  return new;
end;
$$","revoke all on function app_private.preserve_daily_log_summary_approval_route()
  from public, anon, authenticated","drop trigger if exists preserve_daily_log_summary_approval_route on public.daily_logs","create trigger preserve_daily_log_summary_approval_route
before insert or update of summary_source_type, submitted_to_permission, status
on public.daily_logs
for each row
execute function app_private.preserve_daily_log_summary_approval_route()","do $$
declare
  v_previous_guard text := current_setting('app.daily_log_transition_context', true);
begin
  perform set_config('app.daily_log_transition_context', 'on', true);

  update public.daily_logs
  set submitted_to_permission = 'approve'
  where summary_source_type = 'member_contributions'
    and submitted_to_permission is distinct from 'approve';

  perform set_config('app.daily_log_transition_context', coalesce(v_previous_guard, ''), true);
exception when others then
  perform set_config('app.daily_log_transition_context', coalesce(v_previous_guard, ''), true);
  raise;
end;
$$","create index if not exists idx_daily_logs_legacy_summary_source_ids
on public.daily_logs
using gin ((summary_source_metadata -> 'legacyDailyLogIds'))
where summary_source_type = 'member_contributions'","create or replace function app_private.guard_daily_log_legacy_summary_source_delete()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if exists (
    select 1
    from public.daily_logs summary_log
    where summary_log.id <> old.id
      and summary_log.summary_source_type = 'member_contributions'
      and coalesce(summary_log.summary_source_metadata -> 'legacyDailyLogIds', '[]'::jsonb) ? old.id
  ) then
    raise exception 'Phiếu nhật ký nguồn đang được dùng trong bản tổng hợp. Hãy bỏ phiếu khỏi tổng hợp trước khi xoá.'
      using errcode = '23503';
  end if;

  return old;
end;
$$","revoke all on function app_private.guard_daily_log_legacy_summary_source_delete()
  from public, anon, authenticated","drop trigger if exists guard_daily_log_legacy_summary_source_delete on public.daily_logs","create trigger guard_daily_log_legacy_summary_source_delete
before delete on public.daily_logs
for each row
execute function app_private.guard_daily_log_legacy_summary_source_delete()","notify pgrst, 'reload schema'"}

{begin,"set local lock_timeout = '5s'","set local statement_timeout = '60s'","do $$
declare
  v_function record;
  v_definition text;
  v_alias text;
  v_needle text;
  v_occurrences integer;
  v_function_count integer := 0;
  v_replacement_count integer := 0;
  v_expected_functions constant text[] := array[
    'assign_safety_worker_to_site',
    'create_safety_worker_profile_for_site',
    'end_safety_worker_assignment',
    'get_safety_site_worker_detail',
    'issue_safety_assignment_card',
    'log_safety_card_print',
    'lookup_safety_worker_exact',
    'renew_safety_assignment_card',
    'revoke_safety_assignment_card',
    'safety_workforce_detail_for_membership',
    'transfer_safety_worker_site',
    'update_safety_worker_assignment',
    'update_safety_worker_profile_for_site',
    'upsert_safety_worker_documents_for_site'
  ];
begin
  for v_function in
    select procedure.oid, procedure.oid::regprocedure::text as identity
    from pg_proc procedure
    join pg_namespace namespace on namespace.oid = procedure.pronamespace
    where namespace.nspname = 'app_private'
      and procedure.proname = any(v_expected_functions)
    order by procedure.proname
  loop
    v_function_count := v_function_count + 1;
    v_definition := pg_get_functiondef(v_function.oid);

    foreach v_alias in array array['membership', 'worker', 'assignment', 'card']
    loop
      v_needle := 'select ' || v_alias || chr(10);
      v_occurrences := (
        length(v_definition) - length(replace(v_definition, v_needle, ''))
      ) / length(v_needle);

      if v_occurrences > 0 then
        v_definition := replace(
          v_definition,
          v_needle,
          'select ' || v_alias || '.*' || chr(10)
        );
        v_replacement_count := v_replacement_count + v_occurrences;
      end if;
    end loop;

    execute v_definition;
  end loop;

  if v_function_count <> cardinality(v_expected_functions) then
    raise exception
      'SAFETY_HOTFIX_FUNCTION_COUNT: expected %, found %',
      cardinality(v_expected_functions),
      v_function_count;
  end if;

  if v_replacement_count <> 36 then
    raise exception
      'SAFETY_HOTFIX_REPLACEMENT_COUNT: expected 36, found %',
      v_replacement_count;
  end if;
end;
$$",commit}

{"-- A PO sourced from an MR and split into several deliveries is a demand
-- package.  Commercial approval belongs to each delivery, not to the parent
-- PO.  Warehouse status deliberately remains a separate lifecycle.
alter table public.purchase_order_delivery_batches
  add column if not exists approval_status text not null default 'draft',
  add column if not exists approval_requested_by uuid null,
  add column if not exists approval_requested_at timestamptz null,
  add column if not exists approval_decided_by uuid null,
  add column if not exists approval_decided_at timestamptz null,
  add column if not exists approval_decision_note text null","alter table public.purchase_order_delivery_batches
  drop constraint if exists purchase_order_delivery_batches_approval_status_check","alter table public.purchase_order_delivery_batches
  add constraint purchase_order_delivery_batches_approval_status_check
  check (approval_status in ('draft', 'pending_approval', 'approved', 'revision_requested', 'rejected'))","create index if not exists idx_po_delivery_batches_approval
  on public.purchase_order_delivery_batches (purchase_order_id, approval_status, delivery_no)","create or replace function app_private.assert_multiple_delivery_batch_overage_reason_v1(
  p_purchase_order_id text,
  p_delivery_batch_id uuid
) returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_reason text;
begin
  select variance_reason into v_reason
  from public.purchase_order_delivery_batches
  where id = p_delivery_batch_id and purchase_order_id = p_purchase_order_id;

  if coalesce(trim(v_reason), '') <> '' then
    return;
  end if;

  if exists (
    with allocated as (
      select line.purchase_order_line_id, sum(coalesce(line.stock_planned_qty, 0)) as allocated_qty
      from public.purchase_order_delivery_batches batch
      join public.purchase_order_delivery_lines line on line.delivery_batch_id = batch.id
      where batch.purchase_order_id = p_purchase_order_id
        and batch.status <> 'cancelled'
      group by line.purchase_order_line_id
    ), requested as (
      select coalesce(item.value ->> 'lineId', item.value ->> 'itemId') as line_id,
        coalesce(nullif(item.value ->> 'requestedQtySnapshot', '')::numeric,
                 nullif(item.value ->> 'qty', '')::numeric, 0) as requested_qty
      from public.purchase_orders po
      cross join lateral jsonb_array_elements(coalesce(po.items, '[]'::jsonb)) item(value)
      where po.id = p_purchase_order_id
    )
    select 1
    from allocated
    join requested on requested.line_id = allocated.purchase_order_line_id
    where allocated.allocated_qty > requested.requested_qty + 0.000001
  ) then
    raise exception 'Đợt giao vượt nhu cầu MR; phải nhập lý do vượt nhu cầu.' using errcode = '22023';
  end if;
end;
$$","create or replace function public.submit_purchase_order_delivery_batch_approval_v1(
  p_delivery_batch_id uuid,
  p_actor_user_id uuid default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := coalesce(p_actor_user_id, public.current_app_user_id());
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_po public.purchase_orders%rowtype;
begin
  if public.current_app_user_id() is null or v_actor <> public.current_app_user_id() then
    raise exception 'Người thực hiện lệnh không hợp lệ.' using errcode = '42501';
  end if;
  select * into v_batch from public.purchase_order_delivery_batches where id = p_delivery_batch_id for update;
  if not found then raise exception 'Không tìm thấy đợt giao.' using errcode = '22023'; end if;
  select * into v_po from public.purchase_orders where id = v_batch.purchase_order_id for update;
  if coalesce(v_po.source_mode, '') <> 'from_request' or coalesce(v_po.purchase_mode, '') <> 'multiple' then
    raise exception 'Chỉ áp dụng duyệt đợt cho PO MR chia nhiều đợt.' using errcode = '22023';
  end if;
  perform app_private.assert_project_permission_room_action(v_po.project_id, v_po.construction_site_id, 'material_po', 'submit', v_actor);
  if v_batch.status <> 'planned' or v_batch.wms_transaction_id is not null or v_batch.qr_token is not null then
    raise exception 'Chỉ gửi duyệt đợt nháp chưa tạo WMS/QR.' using errcode = '22023';
  end if;
  if coalesce(v_batch.approval_status, 'draft') not in ('draft', 'revision_requested', 'rejected') then
    raise exception 'Đợt giao đang chờ duyệt hoặc đã duyệt.' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.purchase_order_delivery_lines
    where delivery_batch_id = v_batch.id and planned_qty > 0 and stock_planned_qty > 0 and delivery_unit_price >= 0
  ) then
    raise exception 'Đợt giao phải có SL yêu cầu và SL mua lớn hơn 0.' using errcode = '22023';
  end if;
  perform app_private.assert_multiple_delivery_batch_overage_reason_v1(v_po.id, v_batch.id);

  update public.purchase_order_delivery_batches
  set approval_status = 'pending_approval', approval_requested_by = v_actor, approval_requested_at = now(),
      approval_decided_by = null, approval_decided_at = null, approval_decision_note = null, updated_at = now()
  where id = v_batch.id;
  return jsonb_build_object('deliveryBatchId', v_batch.id, 'approvalStatus', 'pending_approval');
end;
$$","create or replace function public.return_purchase_order_delivery_batch_approval_v1(
  p_delivery_batch_id uuid,
  p_decision text,
  p_note text default null,
  p_actor_user_id uuid default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := coalesce(p_actor_user_id, public.current_app_user_id());
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_po public.purchase_orders%rowtype;
  v_next_status text;
begin
  if public.current_app_user_id() is null or v_actor <> public.current_app_user_id() then
    raise exception 'Người thực hiện lệnh không hợp lệ.' using errcode = '42501';
  end if;
  v_next_status := case p_decision when 'revision_requested' then 'revision_requested' when 'rejected' then 'rejected' else null end;
  if v_next_status is null then raise exception 'Quyết định duyệt không hợp lệ.' using errcode = '22023'; end if;
  select * into v_batch from public.purchase_order_delivery_batches where id = p_delivery_batch_id for update;
  if not found then raise exception 'Không tìm thấy đợt giao.' using errcode = '22023'; end if;
  select * into v_po from public.purchase_orders where id = v_batch.purchase_order_id for update;
  perform app_private.assert_project_permission_room_action(v_po.project_id, v_po.construction_site_id, 'material_po', 'approve', v_actor);
  if coalesce(v_batch.approval_status, 'draft') <> 'pending_approval' or v_batch.wms_transaction_id is not null then
    raise exception 'Chỉ trả lại hoặc từ chối đợt đang chờ duyệt.' using errcode = '22023';
  end if;
  update public.purchase_order_delivery_batches
  set approval_status = v_next_status, approval_decided_by = v_actor, approval_decided_at = now(),
      approval_decision_note = nullif(trim(coalesce(p_note, '')), ''), updated_at = now()
  where id = v_batch.id;
  return jsonb_build_object('deliveryBatchId', v_batch.id, 'approvalStatus', v_next_status);
end;
$$","create or replace function public.approve_purchase_order_delivery_batch_v1(
  p_delivery_batch_id uuid,
  p_actor_user_id uuid default null
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_actor uuid := coalesce(p_actor_user_id, public.current_app_user_id());
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_po public.purchase_orders%rowtype;
  v_line public.purchase_order_delivery_lines%rowtype;
  v_item jsonb;
  v_wms_items jsonb := '[]'::jsonb;
  v_tx_id text := 'tx-po-delivery-' || replace(gen_random_uuid()::text, '-', '');
  v_qr_token text := 'pod_' || replace(gen_random_uuid()::text, '-', '');
  v_previous_guard text;
begin
  if public.current_app_user_id() is null or v_actor <> public.current_app_user_id() then
    raise exception 'Người thực hiện lệnh không hợp lệ.' using errcode = '42501';
  end if;
  select * into v_batch from public.purchase_order_delivery_batches where id = p_delivery_batch_id for update;
  if not found then raise exception 'Không tìm thấy đợt giao.' using errcode = '22023'; end if;
  select * into v_po from public.purchase_orders where id = v_batch.purchase_order_id for update;
  if coalesce(v_po.source_mode, '') <> 'from_request' or coalesce(v_po.purchase_mode, '') <> 'multiple' then
    raise exception 'Chỉ áp dụng duyệt đợt cho PO MR chia nhiều đợt.' using errcode = '22023';
  end if;
  perform app_private.assert_project_permission_room_action(v_po.project_id, v_po.construction_site_id, 'material_po', 'approve', v_actor);
  if coalesce(v_batch.approval_status, 'draft') = 'approved' and v_batch.wms_transaction_id is not null then
    return jsonb_build_object('deliveryBatchId', v_batch.id, 'wmsTransactionId', v_batch.wms_transaction_id, 'qrToken', v_batch.qr_token);
  end if;
  if coalesce(v_batch.approval_status, 'draft') <> 'pending_approval' or v_batch.wms_transaction_id is not null then
    raise exception 'Chỉ duyệt đợt đang chờ duyệt và chưa có WMS/QR.' using errcode = '22023';
  end if;
  if nullif(trim(coalesce(v_po.target_warehouse_id, '')), '') is null then
    raise exception 'PO thiếu kho nhận hàng.' using errcode = '22023';
  end if;
  perform app_private.assert_multiple_delivery_batch_overage_reason_v1(v_po.id, v_batch.id);

  for v_line in select * from public.purchase_order_delivery_lines where delivery_batch_id = v_batch.id loop
    if v_line.planned_qty <= 0 or v_line.stock_planned_qty <= 0 then
      raise exception 'SL yêu cầu và SL mua của đợt phải lớn hơn 0.' using errcode = '22023';
    end if;
    select item.value into v_item
    from jsonb_array_elements(coalesce(v_po.items, '[]'::jsonb)) as item(value)
    where coalesce(item.value ->> 'lineId', item.value ->> 'itemId') = v_line.purchase_order_line_id
    limit 1;
    if v_item is null or coalesce(v_item ->> 'itemId', '') <> v_line.item_id then
      raise exception 'Dòng đợt giao không khớp với PO.' using errcode = '22023';
    end if;
    v_wms_items := v_wms_items || jsonb_build_array(jsonb_build_object(
      'itemId', v_line.item_id, 'quantity', v_line.stock_planned_qty, 'orderedQty', v_line.stock_planned_qty,
      'price', v_line.delivery_unit_price, 'accountingQty', v_line.planned_qty, 'accountingUnit', v_line.unit,
      'accountingPrice', v_line.delivery_unit_price, 'purchaseOrderLineId', v_line.purchase_order_line_id,
      'purchaseOrderDeliveryBatchId', v_batch.id, 'purchaseOrderDeliveryLineId', v_line.id,
      'fulfillmentMode', v_po.fulfillment_mode
    ));
  end loop;
  if jsonb_array_length(v_wms_items) = 0 then raise exception 'Đợt giao không có dòng hàng.' using errcode = '22023'; end if;

  insert into public.transactions (
    id, type, date, items, target_warehouse_id, supplier_id, requester_id, created_by, approver_id, status, note,
    business_partner_id, business_partner_name_snapshot, source_type, source_id
  ) values (
    v_tx_id, 'IMPORT'::public.transaction_type, now(), v_wms_items, v_po.target_warehouse_id, v_po.vendor_id,
    v_actor, v_actor, v_actor, 'PENDING'::public.transaction_status,
    coalesce(v_po.po_number, v_po.id) || '-Đợt ' || v_batch.delivery_no || ' đã duyệt',
    null, v_po.vendor_name, 'po_delivery_batch', v_batch.id::text
  );
  update public.purchase_order_delivery_batches
  set approval_status = 'approved', approval_decided_by = v_actor, approval_decided_at = now(),
      qr_token = v_qr_token, idempotency_key = gen_random_uuid(), wms_transaction_id = v_tx_id,
      status = 'receiving', updated_at = now()
  where id = v_batch.id;
  if v_po.status in ('draft', 'sent', 'returned') then
    v_previous_guard := current_setting('app.material_transition_context', true);
    perform set_config('app.material_transition_context', 'on', true);
    update public.purchase_orders set status = 'in_transit', ever_submitted = true, last_action_by = v_actor::text, last_action_at = now()
    where id = v_po.id;
    perform set_config('app.material_transition_context', coalesce(v_previous_guard, ''), true);
  end if;
  return jsonb_build_object('deliveryBatchId', v_batch.id, 'wmsTransactionId', v_tx_id, 'qrToken', v_qr_token);
exception when others then
  perform set_config('app.material_transition_context', coalesce(v_previous_guard, ''), true);
  raise;
end;
$$","revoke all on function public.submit_purchase_order_delivery_batch_approval_v1(uuid, uuid) from public, anon","revoke all on function public.return_purchase_order_delivery_batch_approval_v1(uuid, text, text, uuid) from public, anon","revoke all on function public.approve_purchase_order_delivery_batch_v1(uuid, uuid) from public, anon","grant execute on function public.submit_purchase_order_delivery_batch_approval_v1(uuid, uuid) to authenticated","grant execute on function public.return_purchase_order_delivery_batch_approval_v1(uuid, text, text, uuid) to authenticated","grant execute on function public.approve_purchase_order_delivery_batch_v1(uuid, uuid) to authenticated","-- Existing open multiple-delivery PO lines retain the MR snapshot as their
-- parent demand.  Do not recalculate it from the catalog conversion factor.
update public.purchase_orders po
set items = (
  select jsonb_agg(
    case
      when link.id is null then item.value
      else item.value || jsonb_build_object(
        'requestedQtySnapshot', coalesce(nullif(item.value ->> 'requestedQtySnapshot', '')::numeric, link.requested_qty_snapshot, link.requested_qty, nullif(item.value ->> 'qty', '')::numeric),
        'requestedUnitSnapshot', coalesce(nullif(item.value ->> 'requestedUnitSnapshot', ''), nullif(item.value ->> 'stockUnitSnapshot', ''), nullif(item.value ->> 'unitSnapshot', ''), item.value ->> 'unit'),
        'qty', coalesce(nullif(item.value ->> 'requestedQtySnapshot', '')::numeric, link.requested_qty_snapshot, link.requested_qty, nullif(item.value ->> 'qty', '')::numeric),
        'unit', coalesce(nullif(item.value ->> 'requestedUnitSnapshot', ''), nullif(item.value ->> 'stockUnitSnapshot', ''), nullif(item.value ->> 'unitSnapshot', ''), item.value ->> 'unit'),
        'unitPrice', 0
      )
    end
  )
  from jsonb_array_elements(coalesce(po.items, '[]'::jsonb)) item(value)
  left join lateral (
    select id, requested_qty_snapshot, requested_qty
    from public.purchase_order_request_lines link
    where link.purchase_order_id = po.id
      and link.purchase_order_line_id = coalesce(item.value ->> 'lineId', item.value ->> 'itemId')
    limit 1
  ) link on true
)
where po.source_mode = 'from_request'
  and po.purchase_mode = 'multiple'
  and po.status not in ('cancelled', 'closed')"}

{"-- Commands for MR PO procurement flow v3. Public RPCs are security invoker;
-- privileged mutations are isolated in the unexposed app_private schema.

create or replace function app_private.assert_mr_po_flow_v3_actor_v1(
  p_purchase_order_id text,
  p_action text,
  p_actor_user_id uuid
) returns public.purchase_orders
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_po public.purchase_orders%rowtype;
begin
  if p_actor_user_id is null
    or public.current_app_user_id() is null
    or p_actor_user_id <> public.current_app_user_id()
  then
    raise exception 'Người thực hiện lệnh không hợp lệ.' using errcode = '42501';
  end if;

  select * into v_po
  from public.purchase_orders
  where id = p_purchase_order_id
  for update;

  if not found then
    raise exception 'Không tìm thấy PO.' using errcode = '22023';
  end if;
  if v_po.procurement_flow_version <> 3 or v_po.source_mode <> 'from_request' then
    raise exception 'Lệnh này chỉ áp dụng cho PO từ MR dùng flow v3.' using errcode = '22023';
  end if;

  perform app_private.assert_project_permission_room_action(
    v_po.project_id,
    v_po.construction_site_id,
    'material_po',
    p_action,
    p_actor_user_id
  );
  return v_po;
end;
$$","create or replace function app_private.save_purchase_order_master_estimate_v1(
  p_purchase_order_id text,
  p_is_enabled boolean,
  p_estimate_lines jsonb,
  p_planned_period text,
  p_note text,
  p_actor_user_id uuid
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_po public.purchase_orders%rowtype;
  v_estimate public.purchase_order_master_estimates%rowtype;
begin
  v_po := app_private.assert_mr_po_flow_v3_actor_v1(p_purchase_order_id, 'edit', p_actor_user_id);
  if v_po.purchase_mode <> 'multiple' then
    raise exception 'Đề nghị chủ trương tổng chỉ áp dụng cho PO nhiều đợt.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_estimate_lines, '[]'::jsonb)) <> 'array' then
    raise exception 'Dòng dự toán tổng không hợp lệ.' using errcode = '22023';
  end if;

  insert into public.purchase_order_master_estimates (
    purchase_order_id, project_id, construction_site_id, is_enabled,
    estimate_lines, planned_period, note, created_by, updated_by
  ) values (
    v_po.id, v_po.project_id, v_po.construction_site_id, coalesce(p_is_enabled, false),
    coalesce(p_estimate_lines, '[]'::jsonb), nullif(trim(coalesce(p_planned_period, '')), ''),
    nullif(trim(coalesce(p_note, '')), ''), p_actor_user_id, p_actor_user_id
  )
  on conflict (purchase_order_id) do update set
    is_enabled = excluded.is_enabled,
    estimate_lines = excluded.estimate_lines,
    planned_period = excluded.planned_period,
    note = excluded.note,
    updated_by = excluded.updated_by,
    updated_at = now()
  returning * into v_estimate;

  return to_jsonb(v_estimate);
end;
$$","create or replace function public.save_purchase_order_master_estimate_v1(
  p_purchase_order_id text,
  p_is_enabled boolean,
  p_estimate_lines jsonb default '[]'::jsonb,
  p_planned_period text default null,
  p_note text default null,
  p_actor_user_id uuid default null
) returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
declare
  v_actor uuid := coalesce(p_actor_user_id, public.current_app_user_id());
begin
  return app_private.save_purchase_order_master_estimate_v1(
    p_purchase_order_id, p_is_enabled, p_estimate_lines, p_planned_period, p_note, v_actor
  );
end;
$$","create or replace function app_private.issue_purchase_order_master_estimate_v1(
  p_purchase_order_id text,
  p_actor_user_id uuid
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_po public.purchase_orders%rowtype;
  v_estimate public.purchase_order_master_estimates%rowtype;
  v_version public.purchase_order_master_estimate_versions%rowtype;
  v_version_no integer;
  v_snapshot jsonb;
begin
  v_po := app_private.assert_mr_po_flow_v3_actor_v1(p_purchase_order_id, 'edit', p_actor_user_id);
  if v_po.purchase_mode <> 'multiple' then
    raise exception 'Đề nghị chủ trương tổng chỉ áp dụng cho PO nhiều đợt.' using errcode = '22023';
  end if;
  select * into v_estimate
  from public.purchase_order_master_estimates
  where purchase_order_id = v_po.id
  for update;
  if not found or not v_estimate.is_enabled then
    raise exception 'Chưa bật hoặc chưa lưu đề nghị chủ trương tổng.' using errcode = '22023';
  end if;

  select coalesce(max(version_no), 0) + 1 into v_version_no
  from public.purchase_order_master_estimate_versions
  where purchase_order_id = v_po.id;

  v_snapshot := jsonb_build_object(
    'purchaseOrderId', v_po.id,
    'poNumber', v_po.po_number,
    'projectId', v_po.project_id,
    'constructionSiteId', v_po.construction_site_id,
    'supplierId', v_po.vendor_id,
    'supplierName', v_po.vendor_name,
    'requestItems', v_po.items,
    'estimateLines', v_estimate.estimate_lines,
    'plannedPeriod', v_estimate.planned_period,
    'note', v_estimate.note,
    'issuedAt', now()
  );

  insert into public.purchase_order_master_estimate_versions (
    purchase_order_id, master_estimate_id, version_no, snapshot, issued_by
  ) values (
    v_po.id, v_estimate.id, v_version_no, v_snapshot, p_actor_user_id
  ) returning * into v_version;

  return jsonb_build_object(
    'id', v_version.id,
    'purchaseOrderId', v_version.purchase_order_id,
    'masterEstimateId', v_version.master_estimate_id,
    'versionNo', v_version.version_no,
    'snapshot', v_version.snapshot,
    'issuedBy', v_version.issued_by,
    'issuedAt', v_version.issued_at
  );
end;
$$","create or replace function public.issue_purchase_order_master_estimate_v1(
  p_purchase_order_id text,
  p_actor_user_id uuid default null
) returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
begin
  return app_private.issue_purchase_order_master_estimate_v1(
    p_purchase_order_id,
    coalesce(p_actor_user_id, public.current_app_user_id())
  );
end;
$$","create or replace function app_private.save_purchase_order_delivery_batch_draft_v2(
  p_purchase_order_id text,
  p_delivery_batch_id uuid,
  p_planned_delivery_date date,
  p_vat_rate numeric,
  p_variance_reason text,
  p_note text,
  p_lines jsonb,
  p_actor_user_id uuid
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_po public.purchase_orders%rowtype;
  v_batch public.purchase_order_delivery_batches%rowtype;
  v_line jsonb;
  v_line_key text;
  v_item_id text;
  v_request_qty numeric;
  v_purchase_qty numeric;
  v_price numeric;
  v_count integer := 0;
  v_delivery_no integer;
begin
  v_po := app_private.assert_mr_po_flow_v3_actor_v1(p_purchase_order_id, 'edit', p_actor_user_id);
  if jsonb_typeof(coalesce(p_lines, '[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(p_lines, '[]'::jsonb)) = 0 then
    raise exception 'Đợt đặt hàng phải có ít nhất một dòng.' using errcode = '22023';
  end if;
  if coalesce(p_vat_rate, 0) < 0 or coalesce(p_vat_rate, 0) > 100 then
    raise exception 'VAT không hợp lệ.' using errcode = '22023';
  end if;

  if p_delivery_batch_id is null then
    select coalesce(max(delivery_no), 0) + 1 into v_delivery_no
    from public.purchase_order_delivery_batches
    where purchase_order_id = v_po.id;
    insert into public.purchase_order_delivery_batches (
      purchase_order_id, project_id, construction_site_id, supplier_id,
      supplier_name_snapshot, delivery_no, planned_delivery_date, status,
      approval_status, fulfillment_mode, vat_rate, variance_reason, note, created_by
    ) values (
      v_po.id, v_po.project_id, v_po.construction_site_id, v_po.vendor_id,
      v_po.vendor_name, v_delivery_no, p_planned_delivery_date, 'planned',
      'draft', v_po.fulfillment_mode, coalesce(p_vat_rate, 0),
      nullif(trim(coalesce(p_variance_reason, '')), ''), nullif(trim(coalesce(p_note, '')), ''),
      p_actor_user_id
    ) returning * into v_batch;
  else
    select * into v_batch
    from public.purchase_order_delivery_batches
    where id = p_delivery_batch_id and purchase_order_id = v_po.id
    for update;
    if not found then raise exception 'Không tìm thấy đợt đặt hàng.' using errcode = '22023'; end if;
    if coalesce(v_batch.approval_status, 'draft') not in ('draft', 'revision_requested', 'rejected')
      or v_batch.wms_transaction_id is not null
      or exists (select 1 from public.purchase_order_receipts r where r.delivery_batch_id = v_batch.id)
    then
      raise exception 'Đợt đã gửi duyệt hoặc đã nhận hàng nên không thể sửa.' using errcode = '22023';
    end if;
    update public.purchase_order_delivery_batches set
      supplier_id = v_po.vendor_id,
      supplier_name_snapshot = v_po.vendor_name,
      planned_delivery_date = p_planned_delivery_date,
      vat_rate = coalesce(p_vat_rate, 0),
      variance_reason = nullif(trim(coalesce(p_variance_reason, '')), ''),
      note = nullif(trim(coalesce(p_note, '')), ''),
      approval_status = 'draft',
      approval_decided_by = null,
      approval_decided_at = null,
      approval_decision_note = null,
      updated_at = now()
    where id = v_batch.id
    returning * into v_batch;
    delete from public.purchase_order_delivery_lines where delivery_batch_id = v_batch.id;
  end if;

  for v_line in select value from jsonb_array_elements(p_lines) line(value)
  loop
    v_line_key := nullif(coalesce(v_line ->> 'purchaseOrderLineId', v_line ->> 'purchase_order_line_id'), '');
    v_item_id := nullif(coalesce(v_line ->> 'itemId', v_line ->> 'item_id'), '');
    v_request_qty := coalesce(nullif(coalesce(v_line ->> 'requestQty', v_line ->> 'stock_planned_qty'), '')::numeric, 0);
    v_purchase_qty := coalesce(nullif(coalesce(v_line ->> 'purchaseQty', v_line ->> 'planned_qty'), '')::numeric, 0);
    v_price := coalesce(nullif(coalesce(v_line ->> 'purchaseUnitPrice', v_line ->> 'delivery_unit_price'), '')::numeric, 0);
    if v_line_key is null or v_item_id is null or v_request_qty <= 0 or v_purchase_qty <= 0 or v_price < 0 then
      raise exception 'Dòng đợt đặt hàng thiếu hoặc sai số lượng/đơn giá.' using errcode = '22023';
    end if;
    if not exists (
      select 1 from jsonb_array_elements(v_po.items) item(value)
      where coalesce(item.value ->> 'lineId', item.value ->> 'itemId') = v_line_key
        and item.value ->> 'itemId' = v_item_id
    ) then
      raise exception 'Dòng đợt không thuộc PO gốc.' using errcode = '22023';
    end if;
    insert into public.purchase_order_delivery_lines (
      delivery_batch_id, purchase_order_id, purchase_order_line_id, item_id,
      planned_qty, unit, stock_planned_qty, stock_unit, delivery_unit_price
    ) values (
      v_batch.id, v_po.id, v_line_key, v_item_id,
      v_purchase_qty, nullif(coalesce(v_line ->> 'purchaseUnit', v_line ->> 'unit'), ''),
      v_request_qty, nullif(coalesce(v_line ->> 'requestUnit', v_line ->> 'stock_unit'), ''), v_price
    );
    v_count := v_count + 1;
  end loop;

  return jsonb_build_object(
    'deliveryBatchId', v_batch.id,
    'deliveryNo', v_batch.delivery_no,
    'approvalStatus', 'draft',
    'lineCount', v_count
  );
end;
$$","create or replace function public.save_purchase_order_delivery_batch_draft_v2(
  p_purchase_order_id text,
  p_delivery_batch_id uuid default null,
  p_planned_delivery_date date default null,
  p_vat_rate numeric default 0,
  p_variance_reason text default null,
  p_note text default null,
  p_lines jsonb default '[]'::jsonb,
  p_actor_user_id uuid default null
) returns jsonb
language plpgsql
security invoker
set search_path = ''
as $$
begin
  return app_private.save_purchase_order_delivery_batch_draft_v2(
    p_purchase_order_id, p_delivery_batch_id, p_planned_delivery_date, p_vat_rate,
    p_variance_reason, p_note, p_lines, coalesce(p_actor_user_id, public.current_app_user_id())
  );
end;
$$","create or replace function app_private.delete_purchase_order_delivery_batch_draft_v2(
  p_delivery_batch_id uuid,
  p_actor_user_id uuid
) returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_po_id text;
  v_po public.purchase_orders%rowtype;
  v_batch public.purchase_order_delivery_batches%rowtype;
begin
  select purchase_order_id into v_po_id from public.purchase_order_delivery_batches where id = p_delivery_batch_id;
  if not found then raise exception 'Không tìm thấy đợt đặt hàng.' using errcode = '22023'; end if;
  v_po := app_private.assert_mr_po_flow_v3_actor_v1(v_po_id, 'edit', p_actor_user_id);
  select * into v_batch from public.purchase_order_delivery_batches where id = p_delivery_batch_id for update;
  if coalesce(v_batch.approval_status, 'draft') not in ('draft', 'revision_requested', 'rejected')
    or v_batch.wms_transaction_id is not null
    or exists (select 1 from public.purchase_order_receipts r where r.delivery_batch_id = v_batch.id)
  then
    raise exception 'Chỉ được xóa đợt nháp chưa nhận hàng.' using errcode = '22023';
  end if;
  delete from public.purchase_order_delivery_batches where id = v_batch.id;
  return jsonb_build_object('deliveryBatchId', v_batch.id, 'deleted', true);
end;
$$","create or replace function public.delete_purchase_order_delivery_batch_draft_v2(
  p_delivery_batch_id uuid,
