using (bucket_id='hr-documents' and app_private.has_hrm_template_permission(public.current_app_user_id(),'hrm.document.manage'))","revoke all on public.employees from authenticated,anon","grant all on public.employees to service_role","revoke all on public.hrm_documents from authenticated,anon","revoke all on public.hrm_employee_compensation_assignments from authenticated,anon","revoke all on public.hrm_employee_manual_allowances from authenticated,anon","revoke all on public.hrm_labor_contracts from authenticated,anon","revoke all on public.hrm_payroll_components from authenticated,anon","revoke all on public.hrm_payrolls from authenticated,anon","revoke all on public.hrm_salary_history from authenticated,anon","do $$ declare v_function text; begin
