{begin,"create or replace function app_private.hrm_can_access_employee_subject(
  p_employee_id uuid,
  p_permission_code text,
  p_actor_user_id uuid default public.current_app_user_id()
)
returns boolean language plpgsql stable security definer set search_path = '' as $$
declare
  v_request_user_id uuid := public.current_app_user_id();
  v_subject_user_id uuid;
begin
  if v_request_user_id is null
    or p_actor_user_id is distinct from v_request_user_id
    or p_employee_id is null
    or p_permission_code not like 'hrm.%'
  then return false;
  end if;
  select employee.user_id into v_subject_user_id
  from public.employees employee where employee.id = p_employee_id;
  if v_subject_user_id is null then return false; end if;
  return app_private.has_governed_hrm_permission(v_request_user_id, p_permission_code, 'global', '*')
    or (v_subject_user_id = v_request_user_id
      and app_private.has_governed_hrm_permission(v_request_user_id, p_permission_code, 'own', '*'))
    or (
      app_private.has_governed_hrm_permission(v_request_user_id, p_permission_code, 'direct_reports', '*')
      and app_private.resolve_strict_direct_manager(v_subject_user_id) = v_request_user_id
    );
end;
$$","create or replace function app_private.hrm_can_access_leave_request(
  p_leave_request_id uuid,
  p_permission_code text,
  p_actor_user_id uuid default public.current_app_user_id()
)
returns boolean language sql stable security definer set search_path = '' as $$
  select p_actor_user_id = public.current_app_user_id()
    and coalesce((
      select app_private.hrm_can_access_employee_subject(
        request_row.\"employeeId\", p_permission_code, p_actor_user_id
      )
      from public.hrm_leave_requests request_row where request_row.id = p_leave_request_id
    ), false);
$$","revoke all on function app_private.hrm_can_access_employee_subject(uuid,text,uuid) from public,anon","revoke all on function app_private.hrm_can_access_leave_request(uuid,text,uuid) from public,anon","grant execute on function app_private.hrm_can_access_employee_subject(uuid,text,uuid) to authenticated,service_role","grant execute on function app_private.hrm_can_access_leave_request(uuid,text,uuid) to authenticated,service_role","notify pgrst, 'reload schema'",commit}

{begin,"create or replace function app_private.has_governed_hrm_permission(
  p_user_id uuid,
  p_permission_code text,
  p_scope_type text default 'global',
  p_scope_id text default '*'
)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
    select 1
    from app_private.resolve_effective_permission_sources(
      p_user_id, p_permission_code, p_scope_type, p_scope_id, now()
    ) source_row
    where not (
      source_row.permission_code like 'hrm.%'
      and source_row.source_type = 'LEGACY'
    )
    and (
      not app_private.is_hrm_template_only_permission(source_row.permission_code)
      or (source_row.source_type = 'ROLE' and source_row.source_code in ('HR','HR_MANAGE'))
    )
  );
$$","do $$
declare v_definition text;
begin
  select pg_get_functiondef('app_private.get_effective_permission_sources_authorized(uuid)'::regprocedure)
  into v_definition;
  v_definition := replace(
    v_definition,
    'coalesce(v_target_is_admin, false)
      and source_row.permission_code like ''hrm.%''
      and source_row.source_type = ''LEGACY''',
    'source_row.permission_code like ''hrm.%''
      and source_row.source_type = ''LEGACY'''
  );
  execute v_definition;
  if pg_get_functiondef('app_private.get_effective_permission_sources_authorized(uuid)'::regprocedure)
    like '%coalesce(v_target_is_admin, false)%'
  then raise exception using errcode='55000', message='HRM_LEGACY_AUTHORIZED_RESOLVER_REWRITE_FAILED'; end if;

  select pg_get_functiondef('app_private.get_user_hr_authorization_impl(uuid)'::regprocedure)
  into v_definition;
  v_definition := replace(
    v_definition,
    'and not (v_target.role = ''ADMIN'' and source_row.source_type = ''LEGACY'')',
    'and not (source_row.source_type = ''LEGACY'')'
  );
  execute v_definition;
  if pg_get_functiondef('app_private.get_user_hr_authorization_impl(uuid)'::regprocedure)
    like '%v_target.role = ''ADMIN'' and source_row.source_type = ''LEGACY''%'
  then raise exception using errcode='55000', message='HRM_LEGACY_AUTHORIZATION_SUMMARY_REWRITE_FAILED'; end if;
end;
$$","revoke all on function app_private.has_governed_hrm_permission(uuid,text,text,text) from public,anon,authenticated","notify pgrst, 'reload schema'",commit}

{begin,"create or replace function app_private.hrm_can_access_employee_subject(
  p_employee_id uuid,
  p_permission_code text,
  p_actor_user_id uuid default public.current_app_user_id()
)
returns boolean language plpgsql stable security definer set search_path = '' as $$
declare
  v_request_user_id uuid := public.current_app_user_id();
  v_subject_user_id uuid;
begin
  if v_request_user_id is null
    or p_actor_user_id is distinct from v_request_user_id
    or p_employee_id is null
    or p_permission_code not like 'hrm.%'
  then return false;
  end if;
  if app_private.has_governed_hrm_permission(v_request_user_id, p_permission_code, 'global', '*') then
    return true;
  end if;
  select employee.user_id into v_subject_user_id
  from public.employees employee where employee.id = p_employee_id;
  if v_subject_user_id is null then return false; end if;
  return (v_subject_user_id = v_request_user_id
      and app_private.has_governed_hrm_permission(v_request_user_id, p_permission_code, 'own', '*'))
    or (
      app_private.has_governed_hrm_permission(v_request_user_id, p_permission_code, 'direct_reports', '*')
      and app_private.resolve_strict_direct_manager(v_subject_user_id) = v_request_user_id
    );
end;
$$","revoke all on function app_private.hrm_can_access_employee_subject(uuid,text,uuid) from public,anon","grant execute on function app_private.hrm_can_access_employee_subject(uuid,text,uuid) to authenticated,service_role","notify pgrst, 'reload schema'",commit}

